                        let chisato_energy = game.id("PL!SP-pb1-038-SRE"); // 澁谷かのん＆嵐 千砂都 (energy)
                        game.state.player1.hand.cards.push(triple);
                        game.state.player1.hand.cards.push(hanamaru);
