                        trigger_member_restore_debut_and_check_blade_gain(&mut game, c);

                        let blade = game.state.mods.get_blade_modifier(c);
                        assert!(
                            blade >= 2,
                            "Q242: Exactly 20 cards moved → threshold met, blade+2 should apply"
                        );
