            pub mod discard_self_same_area_group_deploy_q63_q80_test {
                /// Tests for 村野さやか (PL!HS-bp1-002-R) — Activation ability:
                ///
                /// {{kidou.png|起動}}このメンバーをステージから控え室に置く：
                /// 自分の控え室からコスト15以下の「蓮ノ空」のメンバーカードを1枚、
                /// このメンバーが置かれていたエリアに登場させる。
                ///
                /// Q63: Ability debuts don't require paying the card's cost
                /// Q80: Can debut to the area vacated by this same ability this turn
                use crate::helpers::*;
                /// Q63: Debuting via ability effect does not require paying the card's
                /// cost. Activate 村野さやか with a matching 蓮ノ空 member in discard,
                /// verify it appears on stage without requiring extra energy.
                #[test]
                fn discard_self_same_area_group_deploy_q63_ability_debut_no_cost_payment() {
                    let db = load_real_database();
                    let mut game = TestGame::new(db);

                    let sayaka = game.id("PL!HS-bp1-002-R");
                    let hasuno_member = game.id("PL!HS-bp2-004-R"); // 藤島慈, cost=2, group=蓮ノ空

                    // Stage: 村野さやか in Center
                    game.state.player1.stage.stage[1] = sayaka;

                    // Hand: nothing needed
                    // Discard: a 蓮ノ空 member
                    game.state.player1.waitroom.cards.push(hasuno_member);

                    // Energy: 2 for the activation cost
                    game.give_energy(2);

                    game.activate_ability(sayaka);

                    assert!(
                        game.has_pending_choice(),
                        "member-from-discard selection prompt expected"
                    );
                    assert_eq!(
                        game.pending_choice_type().as_deref(),
                        Some("SelectCard"),
                        "expected SelectCard for the debut member pick (zone=discard)"
                    );
                    game.select_indices(&[0]);

                    assert_eq!(
                        game.state.player1.energy_zone.active_count(),
                        0,
                        "Q63: 2E should be fully consumed by activation cost"
                    );
                    assert!(
                        game.state.player1.waitroom.cards.contains(&sayaka),
                        "sayaka should be in waitroom after activation cost"
                    );
                    assert_eq!(
                        game.state.player1.stage.stage[1], hasuno_member,
                        "Q63: 蓮ノ空 member should appear in sayaka's former area without cost payment"
                    );
                }

                /// Q80: Can debut to an area that was vacated by this same ability this
                /// turn. The self_cost puts sayaka in waitroom, freeing the area, and
                /// the effect debuts a new member to the same area — all within one
                /// ability activation.
                #[test]
                fn discard_self_same_area_group_deploy_q80_debut_to_vacated_area_same_turn() {
                    let db = load_real_database();
                    let mut game = TestGame::new(db);

                    let sayaka = game.id("PL!HS-bp1-002-R");
                    let hasuno_member = game.id("PL!HS-bp2-004-R");

                    game.state.player1.stage.stage[1] = sayaka;
                    game.state.player1.waitroom.cards.push(hasuno_member);
                    game.give_energy(2);

                    game.activate_ability(sayaka);

                    assert!(
                        game.has_pending_choice(),
                        "member-from-discard selection prompt expected"
                    );
                    assert_eq!(
                        game.pending_choice_type().as_deref(),
                        Some("SelectCard"),
                        "expected SelectCard for the debut member pick (zone=discard)"
                    );
                    // Select the only eligible card in discard
                    game.select_indices(&[0]);

                    // The area vacated by sayaka should now be filled by the new member
                    assert_eq!(
                        game.state.player1.stage.stage[1], hasuno_member,
                        "Q80: New member should debut to the vacated area (same_area)"
                    );
                    assert!(
                        !game.state.player1.stage.stage.contains(&sayaka),
                        "sayaka should no longer be on stage"
                    );
                }
                        }


            pub mod eternalize_love_test {
                use crate::helpers::*;

                fn fill_decks(game: &mut TestGame, filler: i16) {
                    game.state.player1.main_deck.cards.clear();
                    game.state.player2.main_deck.cards.clear();
                    for _ in 0..30 {
                        game.state.player1.main_deck.cards.push(filler);
                        game.state.player2.main_deck.cards.push(filler);
                    }
                }

                fn trigger_ability(game: &mut TestGame, card_id: i16, trigger_str: &str) {
                    let card = game.db.get_card(card_id).unwrap();
                    let ab = card
                        .resolved_abilities()
                        .find(|a| a.triggers.as_deref() == Some(trigger_str))
                        .unwrap();
                    let pid = game.state.player1.id.clone();
                    let trigger = match trigger_str {
                        "ライブ開始時" => rabuka_engine::core::types::AbilityTrigger::LiveStart,
                        _ => rabuka_engine::core::types::AbilityTrigger::Auto,
                    };
                    game.state.trigger_auto_ability(
                        format!("{}_{}", card.card_no, ab.full_text),
                        trigger,
                        pid,
                        Some(card.card_no.to_string()),
                        Some(card_id),
                        None,
                        None,
                    );
                    game.state
                        .process_pending_auto_abilities(&game.state.player1.id.clone());
                }

                /// 2 same-named 虹ヶ咲 members on stage → condition passes.
                /// Eternalize Love!! should get heart00 -3, NOT -6.
                #[test]
                fn eternalize_love_two_same_name_reduces_by_3_not_6() {
                    let db = load_real_database();
                    let mut game = TestGame::new(db);
                    let member = game.id("PL!N-pb1-015-R");
                    let live = game.id("PL!N-pb1-042-L");
                    let filler = game.id("PL!-sd1-010-SD");

                    // Two cards with the same name on stage
                    let member_copy2 = game.new_id("PL!N-pb1-015-R");
                    game.state.player1.stage.stage = [member, member_copy2, -1];
                    game.state.player1.live_card_zone.cards.push(live);
                    fill_decks(&mut game, filler);

                    // Trigger LiveStart ability
                    trigger_ability(&mut game, live, "ライブ開始時");

                    // Check the heart00 modifier on the live card
                    let modifier = game
                        .state
                        .mods
                        .get_need_heart_modifier(live, rabuka_engine::card::HeartColor::Heart00);
                    assert_eq!(
                        modifier, -3,
                        "Expected -3 heart00 reduction (got {})",
                        modifier
                    );

                    // Also verify no other colors were modified
                    for hc in &[
                        rabuka_engine::card::HeartColor::Heart01,
                        rabuka_engine::card::HeartColor::Heart02,
                        rabuka_engine::card::HeartColor::Heart03,
                        rabuka_engine::card::HeartColor::Heart04,
                        rabuka_engine::card::HeartColor::Heart05,
                        rabuka_engine::card::HeartColor::Heart06,
                    ] {
                        let m = game.state.mods.get_need_heart_modifier(live, *hc);
                        assert_eq!(m, 0, "Expected 0 modifier for {:?}", hc);
                    }

                    // Verify the original need_heart was 12 heart00, reduced to 9
                    let card = game.db.get_card(live).unwrap();
                    let need_heart = card.need_heart.as_ref().unwrap();
                    let original_heart00 = need_heart
                        .hearts
                        .get(&rabuka_engine::card::HeartColor::Heart00)
                        .copied()
                        .unwrap_or(0);
                    assert_eq!(original_heart00, 12, "Eternalize Love!! needs 12 heart00");
                }

                /// Full live flow: 2 same-named 虹ヶ咲 on stage → Eternalize Love!! set as live card
                /// → advance to LiveStart → check modifier during and after performance.
                #[test]
                fn eternalize_love_full_live_flow_heart00_reduction() {
                    let db = load_real_database();
                    let mut game = TestGame::new(db);
                    let member = game.id("PL!N-pb1-015-R");
                    let live = game.id("PL!N-pb1-042-L");
                    let filler = game.id("PL!-sd1-010-SD");

                    // Two same-named 虹ヶ咲 on stage
                    let member_copy2 = game.new_id("PL!N-pb1-015-R");
                    game.state.player1.stage.stage = [member, member_copy2, -1];
                    // Put live card in hand for set_live_card
                    game.state.player1.hand.cards.push(live);

                    fill_decks(&mut game, filler);

                    // Advance by NAME. The two local helpers this used to define
                    // (`advance_to_live_card_set_p1` = 5 passes, `advance_to_live_start` = 2)
                    // hid which window the test was standing in; a phase that gains or loses a
                    // step would have moved the test with no failure to notice.
                    game.advance_to_phase(rabuka_engine::game_state::Phase::LiveCardSetFirstAttacker);
                    game.set_live_card(live);
                    game.advance_to_phase(rabuka_engine::game_state::Phase::FirstAttackerPerformance);

                    // Handle any pending choices from LiveStart
                    // Answer what cannot be declined, decline what can: a mandatory
                    // prompt left parked mid-ability produces exactly the absence
                    // the next assertion checks, so nothing fails.
                    game.drain_choices();

                    // Advance through performance phases
                    // FirstAttackerPerformance → SecondAttackerPerformance
                    game.pass();
                    game.pass();
                    // LiveVictoryDetermination
                    game.pass();
                    // Answer what cannot be declined, decline what can: a mandatory
                    // prompt left parked mid-ability produces exactly the absence
                    // the next assertion checks, so nothing fails.
                    game.drain_choices();
                    // LVD → Active (check_expired_effects runs)
                    game.pass();
                    // Answer what cannot be declined, decline what can: a mandatory
                    // prompt left parked mid-ability produces exactly the absence
                    // the next assertion checks, so nothing fails.
                    game.drain_choices();

                    // Check modifier after live
                    let modifier_after = game
                        .state
                        .mods
                        .get_need_heart_modifier(live, rabuka_engine::card::HeartColor::Heart00);

                    // After live end: modifier is -3 (correct single application).
                    // Before the dedup fix this was -6 due to double-counting in snapshot restore.
                    assert_eq!(
                        modifier_after, -3,
                        "After live end modifier is -3 (was -6 before fix)"
                    );
                }
                        }


            pub mod fuyumari_test {
                /// Tests for 鬼塚冬毬 (PL!SP-pb1-011-R) — Debut ability:
                ///
                /// 登場 「鬼塚冬毬」以外の『Liella!』のメンバー1人をステージから控え室に置いてもよい：
                /// その後の控え室から、これにより控え室に置いたメンバーカードを1枚、
                /// そのメンバーがいたエリアに登場させる。
                ///
                /// Q63: Effect-debut doesn't pay member cost separately.
                /// Q95: Only the exact card sent as cost can be appeared (not same-name copies).
                use crate::helpers::*;
                use rabuka_engine::ability::types::Choice;
                use rabuka_engine::zones::MemberArea;

                fn drain_auto_prompts_fuyumari(game: &mut TestGame) {
                    let mut guard = 0;
                    while game.has_pending_choice() && guard < 10 {
                        guard += 1;
                        match game.get_pending_choice() {
                            Choice::SelectAutoAbility { .. } => game.select_indices(&[]),
                            _ => break,
                        }
                    }
                }

                /// Answer the optional-stage-cost pay/skip gate introduced for
                /// 「〜してもよい」 member-sacrifice costs. Returns true when a gate was
                /// present and answered (accept=true pays, false skips).
                fn answer_stage_cost_gate(game: &mut TestGame, accept: bool) -> bool {
                    match game.get_pending_choice() {
                        Choice::SelectTarget { target, .. } if target.starts_with("pay_optional_cost") => {
                            game.select_option(if accept { 1 } else { 0 });
                            true
                        }
                        _ => false,
                    }
                }

                /// Q63: Effect-debut doesn't pay member cost separately.
                #[test]
                fn fuyumari_q63_effect_debut_no_cost_payment() {
                    let db = load_real_database();
                    let mut game = TestGame::new(db);

                    let fuyumari = game.id("PL!SP-pb1-011-R");
                    let liella_member = game.id("PL!SP-sd1-006-SD");

                    game.state.player1.hand.cards.push(fuyumari);
                    game.state.player1.stage.stage[0] = liella_member;
                    game.give_energy(13);

                    game.state.player1.stage.stage[1] = -1;
                    game.play_to_stage(fuyumari, MemberArea::Center);

                    // Observed chain: the ability opens with a pay/skip gate
                    // (SelectTarget pay_optional_cost); answering card_indices [0] resolves
                    // to skip_optional_cost, so this test exercises the SKIP path (no swap,
                    // no effect). The state assertions below hold trivially on that path.
                    assert!(
                        game.has_pending_choice(),
                        "pay/skip gate for the optional stage cost expected"
                    );
                    assert_eq!(
                        game.pending_choice_type().as_deref(),
                        Some("SelectTarget"),
                        "expected SelectTarget pay_optional_cost gate"
                    );
                    game.select_indices(&[0]); // [0] = skip_optional_cost (observed via HST log)
                    assert!(
                        !game.has_pending_choice(),
                        "Exactly 1 matching card in discard → auto-resolve"
                    );

                    assert_eq!(
                        game.state.player1.energy_zone.active_count(),
                        0,
                        "All 13 energy spent on ふるまり herself (Q63)"
                    );
                    assert_eq!(
                        game.state.player1.stage.stage[0], liella_member,
                        "Liella! member returned to LeftSide (same_area)"
                    );
                    assert_eq!(
                        game.state.player1.stage.stage[1], fuyumari,
                        "ふるまり on Center"
                    );
                }

                /// Q63 variant: optional cost NOT paid → no swap.
                #[test]
                fn fuyumari_q63_optional_cost_skipped() {
                    let db = load_real_database();
                    let mut game = TestGame::new(db);

                    let fuyumari = game.id("PL!SP-pb1-011-R");
                    let liella_member = game.id("PL!SP-sd1-006-SD");

                    game.state.player1.hand.cards.push(fuyumari);
                    game.state.player1.stage.stage[0] = liella_member;
                    game.give_energy(13);

                    game.state.player1.stage.stage[1] = -1;
                    game.play_to_stage(fuyumari, MemberArea::Center);

                    // Observed: the optional stage cost opens with the same pay/skip gate;
                    // an empty card_indices answer also resolves to skip_optional_cost.
                    assert!(
                        game.has_pending_choice(),
                        "pay/skip gate for the optional stage cost expected"
                    );
                    assert_eq!(
                        game.pending_choice_type().as_deref(),
                        Some("SelectTarget"),
                        "expected SelectTarget pay_optional_cost gate"
                    );
                    game.select_indices(&[]); // empty answer = skip_optional_cost (observed)

                    assert_eq!(
                        game.state.player1.stage.stage[0], liella_member,
                        "Liella! member should remain on stage when cost is skipped"
                    );
                    assert_eq!(
                        game.state.player1.stage.stage[1], fuyumari,
                        "ふるまり on Center"
                    );
                }

                /// Q95: Player chooses which card from discard appears via same_area.
                #[test]
                fn fuyumari_q95_player_chooses_card_from_discard() {
                    let db = load_real_database();
                    let mut game = TestGame::new(db);

                    let fuyumari = game.id("PL!SP-pb1-011-R");
                    let liella_member = game.id("PL!SP-sd1-006-SD");
                    let other_member = game.id("PL!SP-sd1-008-SD");

                    game.state.player1.hand.cards.push(fuyumari);
                    game.state.player1.stage.stage[0] = liella_member;
                    game.state.player1.waitroom.cards.push(other_member);
                    game.state.player1.waitroom.cards.push(liella_member);
                    game.give_energy(13);

                    let discard_before = game.state.player1.waitroom.cards.len();

                    game.state.player1.stage.stage[1] = -1;
                    game.play_to_stage(fuyumari, MemberArea::Center);

                    // 1. Optional-cost gate: pay or skip (「〜してもよい」).
                    assert!(
                        answer_stage_cost_gate(&mut game, true),
                        "optional stage cost must present a pay/skip gate"
                    );
                    // 2. Cost target selection: exactly one Liella! member on stage → the
                    // engine auto-applies it with NO prompt (single-candidate auto-resolve).
                    // 3. Effect: the very next ask is the re-deploy choice from the waitroom
                    // (SelectCard zone=discard count=1 allow_skip=false).
                    assert!(
                        game.has_pending_choice(),
                        "re-deploy SelectCard prompt expected after paying the optional cost"
                    );
                    assert_eq!(
                        game.pending_choice_type().as_deref(),
                        Some("SelectCard"),
                        "expected SelectCard (zone=discard, member_card) for the re-deploy choice"
                    );
                    game.select_indices(&[0]);
                    assert!(
                        !game.has_pending_choice(),
                        "re-deploy choice answered; ability must complete with no further prompt"
                    );

                    assert_eq!(
                        game.state.player1.stage.stage[0], other_member,
                        "Chosen card (other_member) appears at same_area (LeftSide)"
                    );
                    assert_eq!(
                        game.state.player1.stage.stage[1], fuyumari,
                        "ふるまり on Center"
                    );
                    assert!(
                        game.state.player1.waitroom.cards.len() <= discard_before,
                        "Cost adds 1, effect removes 1 → net ≤ discard_before"
                    );
                }

                /// Edge case: Non-Liella! member on stage is NOT a valid cost target.
                /// With zero candidates the engine Q167-skips silently — either way the
                /// filler must never be sacrificed or summoned.
                #[test]
                fn fuyumari_q95_same_name_decoy_is_not_the_sacrificed_instance() {
                    let db = load_real_database();
                    let mut game = TestGame::new(db);
                    let fuyumari = game.id("PL!SP-pb1-011-R");
                    let sacrificed = game.id("PL!SP-sd1-006-SD");
                    let decoy = game.new_id("PL!SP-sd1-006-SD");

                    game.state.player1.hand.cards.push(fuyumari);
                    game.state.player1.stage.stage[0] = sacrificed;
                    game.state.player1.waitroom.cards.push(decoy);
                    game.give_energy(13);
                    game.state.player1.stage.stage[1] = -1;
                    game.play_to_stage(fuyumari, MemberArea::Center);
                    answer_stage_cost_gate(&mut game, true);
                    assert!(game.has_pending_choice());
                    let filtered = game
                        .state
                        .get_pending_choice_json()
                        .and_then(|v| v.get("filtered_indices").cloned())
                        .expect("re-deploy must expose filtered indices");
                    assert!(
                        filtered.to_string().contains("1"),
                        "Q95: only the sacrificed instance should be selectable, not the same-name decoy"
                    );
                    game.select_indices(&[1]);
                    drain_auto_prompts_fuyumari(&mut game);
                    assert_eq!(game.state.player1.stage.stage[0], sacrificed);
                    assert!(game.state.player1.waitroom.cards.contains(&decoy));
                }

                #[test]
                fn fuyumari_edge_no_valid_cost_target() {
                    let db = load_real_database();
                    let mut game = TestGame::new(db);

                    let fuyumari = game.id("PL!SP-pb1-011-R");
                    let filler = game.id("PL!-sd1-010-SD");

                    game.state.player1.hand.cards.push(fuyumari);
                    game.state.player1.hand.cards.push(filler);
                    game.state.player1.stage.stage[0] = filler;
                    game.give_energy(13);

                    game.state.player1.stage.stage[1] = -1;
                    game.play_to_stage(fuyumari, MemberArea::Center);

                    // Observed: zero valid candidates (non-Liella! filler excluded) → the
                    // optional cost auto-skips silently (KANAN_DEBUG cost_was_skipped=true);
                    // no prompt of any kind is presented, so the filler can never be offered.
                    assert!(
                        !game.has_pending_choice(),
                        "no prompt expected: zero Liella! candidates auto-skip the optional cost"
                    );

                    assert_eq!(
                        game.state.player1.stage.stage[0], filler,
                        "non-Liella! member must stay on stage (invalid cost target)"
                    );
                    assert!(
                        !game.state.player1.waitroom.cards.contains(&filler),
                        "non-Liella! member must not be sacrificed as cost"
                    );
                    assert_eq!(
                        game.state.player1.stage.stage[1], fuyumari,
                        "ふるまり on Center"
                    );
                }

                /// Edge case: exclude_self — ふるまり herself must not appear in the cost
                /// prompt; the Liella! member is sacrificed and re-deploys into her own
                /// vacated area.
                #[test]
                fn fuyumari_edge_exclude_self_from_cost() {
                    let db = load_real_database();
                    let mut game = TestGame::new(db);

                    let fuyumari = game.id("PL!SP-pb1-011-R");
                    let liella_member = game.id("PL!SP-sd1-006-SD");

                    game.state.player1.hand.cards.push(fuyumari);
                    game.state.player1.stage.stage[1] = -1;
                    game.state.player1.stage.stage[2] = liella_member;
                    game.give_energy(13);

                    game.play_to_stage(fuyumari, MemberArea::Center);

                    // The optional stage cost now ALWAYS opens with a pay/skip gate — that
                    // gate itself is not an exclusion failure. Exclusion is proven by what
                    // follows: with exclude_self honored, exactly ONE candidate remains
                    // (liella_member), so after accepting there is NO SelectCard prompt
                    // (single candidate auto-resolves). If the filter were broken, ふるまり
                    // would be offered too and a SelectCard would appear here.
                    assert!(
                        answer_stage_cost_gate(&mut game, true),
                        "optional stage cost must present a pay/skip gate"
                    );
                    assert!(
                        !game.has_pending_choice(),
                        "single valid candidate must auto-resolve; a SelectCard here means \
                         exclude_self failed to drop herself"
                    );

                    drain_auto_prompts_fuyumari(&mut game);
                    assert_eq!(
                        game.state.player1.stage.stage[2], liella_member,
                        "the sacrificed Liella! member re-deploys into her vacated area"
                    );
                    assert_eq!(
                        game.state.player1.stage.stage[1], fuyumari,
                        "ふるまり on Center"
                    );
                    assert!(
                        !game.state.player1.waitroom.cards.contains(&fuyumari),
                        "exclude_self: ふるまり never becomes a cost"
                    );
                }
                        }


            pub mod lower_cost_baton_optional_low_cost_hand_deploy_test {
                /// Tests for PL!-PR-015-PR (西木野真姫 / Maki Nishikino) — Appear ability via baton touch
                ///
                /// 登場:
                ///   このメンバーよりコストが低いメンバーからバトンタッチして登場した場合、
                ///   自分の手札からコスト4以下のメンバーカードを1枚ステージに登場させてもよい。
                use crate::helpers::*;
                use rabuka_engine::game_setup::ActionType;
                use rabuka_engine::turn::TurnEngine;
                use rabuka_engine::zones::MemberArea;

                /// Baton touch from lower-cost (cost 4 < 17) → cost≤4 member from hand appears on stage.
                #[test]
                fn lower_cost_baton_hand_deploy_baton_touch_places_cheap_member_on_stage() {
                    let db = load_real_database();
                    let mut game = TestGame::new(db);

                    let maki = game.id("PL!-PR-015-PR");
                    let cheap = game.id("PL!SP-sd1-019-SD");
                    let filler = game.id("PL!-sd1-010-SD");

                    game.state.player1.stage.stage = [-1, filler, -1];
                    game.state.player1.hand.cards.push(maki);
                    game.state.player1.hand.cards.push(cheap);
                    game.give_energy(17);

                    TurnEngine::execute_main_phase_action(
                        &mut game.state,
                        &ActionType::PlayMemberToStage,
                        Some(maki),
                        None,
                        Some(MemberArea::Center),
                        Some(true),
                    )
                    .expect("baton touch");

                    assert!(
                        game.state.player1.stage.stage.contains(&maki),
                        "Maki on stage after baton touch"
                    );

                    // move_cards (formerly appear) always offers the hand selection here.
                    assert!(
                        game.has_pending_choice(),
                        "appear hand selection prompt expected"
                    );
                    assert_eq!(
                        game.pending_choice_type().as_deref(),
                        Some("SelectCard"),
                        "expected SelectCard (cheap member from hand)"
                    );
                    game.select_indices(&[0]); // select cheap from hand
                    // Resolve any remaining choices (positioning sub-choice, etc.)
                    while game.has_pending_choice() {
                        game.select_option(0);
                    }

                    assert!(
                        game.state.player1.stage.stage.contains(&cheap),
                        "cheap member appeared on stage"
                    );
                    assert!(
                        !game.state.player1.hand.cards.contains(&cheap),
                        "cheap member removed from hand"
                    );
                }

                /// Equal-cost baton touch (17 == 17) → condition fails → no appear.
                #[test]
                fn lower_cost_baton_hand_deploy_equal_cost_no_appear() {
                    let db = load_real_database();
                    let mut game = TestGame::new(db);

                    let maki_hand = game.new_id("PL!-PR-015-PR");
                    let maki_stage = game.id("PL!-PR-015-PR");

                    game.state.player1.stage.stage = [-1, maki_stage, -1];
                    game.state.player1.hand.cards.push(maki_hand);
                    game.give_energy(17);

                    TurnEngine::execute_main_phase_action(
                        &mut game.state,
                        &ActionType::PlayMemberToStage,
                        Some(maki_hand),
                        None,
                        Some(MemberArea::Center),
                        Some(true),
                    )
                    .expect("baton touch");

                    assert!(
                        game.state.player1.stage.stage.contains(&maki_hand),
                        "new Maki on stage after baton touch"
                    );
                    assert_eq!(
                        game.state
                            .player1
                            .stage
                            .stage
                            .iter()
                            .filter(|&&c| c != -1)
                            .count(),
                        1,
                        "only 1 member on stage (old Maki replaced, no appear)"
                    );
                }

                /// Play to empty area (no baton touch) → ability not triggered.
                #[test]
                fn lower_cost_baton_hand_deploy_no_baton_touch_no_appear() {
                    let db = load_real_database();
                    let mut game = TestGame::new(db);

                    let maki = game.id("PL!-PR-015-PR");
                    let cheap = game.id("PL!SP-sd1-019-SD");

                    game.state.player1.stage.stage = [-1, -1, -1];
                    game.state.player1.hand.cards.push(maki);
                    game.state.player1.hand.cards.push(cheap);
                    game.give_energy(17);

                    game.play_to_stage_baton(maki, MemberArea::Center);

                    assert!(
                        game.state.player1.hand.cards.contains(&cheap),
                        "cheap member stays in hand (no baton touch)"
                    );
                }

                /// Baton touch lower cost, but no eligible card in hand → optional ability skips gracefully.
                #[test]
                fn lower_cost_baton_hand_deploy_no_eligible_hand_skips() {
                    let db = load_real_database();
                    let mut game = TestGame::new(db);

                    let maki = game.id("PL!-PR-015-PR");
                    let too_expensive = game.id("PL!-sd1-014-SD");
                    let filler = game.id("PL!-sd1-010-SD");

                    game.state.player1.stage.stage = [-1, filler, -1];
                    game.state.player1.hand.cards.push(maki);
                    game.state.player1.hand.cards.push(too_expensive);
                    game.give_energy(17);

                    TurnEngine::execute_main_phase_action(
                        &mut game.state,
                        &ActionType::PlayMemberToStage,
                        Some(maki),
                        None,
                        Some(MemberArea::Center),
                        Some(true),
                    )
                    .expect("baton touch");

                    assert!(
                        game.state.player1.hand.cards.contains(&too_expensive),
                        "cost-9 card stays in hand"
                    );
                }
                        }


            pub mod n_pb1_015_shizuku_test {
                use crate::helpers::*;
                use rabuka_engine::zones::MemberArea;

                /// PL!N-pb1-015-R 桜坂しずく — 登場: optional 2E → deploy a cost≤4 桜坂しずく from hand
                ///
                /// 「{{E}}{{E}}支払ってもよい：手札からコスト4以下の『桜坂しずく』のメンバーカードを1枚
                /// ステージに登場させる。」
                ///
                /// The deploy is the whole point, so this states where the target card ENDS UP rather
                /// than that it is no longer in hand. "not in hand" is satisfied by a card that was
                /// discarded, destroyed, or never in the fixture — all of which would pass while the
                /// ability did nothing.
                #[test]
                fn shizuku_pay_2e_deploys_shizuku() {
                    let db = load_real_database();
                    let mut game = TestGame::new(db);
                    let shizuku = game.id("PL!N-pb1-015-R"); // cost 13
                    let shizuku_hand = game.new_id("PL!N-bp1-015-N");
                    let filler = game.id("PL!-sd1-010-SD");
                    game.state.player1.hand.cards.push(shizuku);
                    game.state.player1.hand.cards.push(shizuku_hand);
                    game.give_energy(15);
                    for _ in 0..5 { game.state.player1.main_deck.cards.push(filler); }
                    game.state.player1.stage.stage = [-1, -1, -1];
                    game.play_to_stage(shizuku, MemberArea::Center);
                    assert!(game.has_pending_choice(), "pay 2E prompt expected");
                    game.select_option(1); // pay
                    // After pay, a SelectCard asks WHICH Shizuku to deploy.
                    let mut safety=0;
                    while game.has_pending_choice() && safety<5 { safety+=1; game.select_indices(&[0]); }
                    assert!(
                        game.state.player1.stage.stage.contains(&shizuku_hand),
                        "「ステージに登場させる」 — after paying, the 桜坂しずく member must be ON STAGE. \
                         The old assertion was `on_stage || !in_hand`, which a discarded or destroyed card \
                         satisfies just as well as a deployed one."
                    );
                    game.assert_energy(0, "13E to play 桜坂しずく plus the 2E optional deploy cost");
                    assert!(!game.has_pending_choice());
                }
                #[test]
                fn shizuku_skip_pay_no_deploy() {
                    let db = load_real_database();
                    let mut game = TestGame::new(db);
                    let shizuku = game.id("PL!N-pb1-015-R");
                    let shizuku_hand = game.new_id("PL!N-bp1-015-N");
                    let filler = game.id("PL!-sd1-010-SD");
                    game.state.player1.hand.cards.push(shizuku);
                    game.state.player1.hand.cards.push(shizuku_hand);
                    game.give_energy(15);
                    for _ in 0..5 { game.state.player1.main_deck.cards.push(filler); }
                    game.state.player1.stage.stage = [-1, -1, -1];
                    game.play_to_stage(shizuku, MemberArea::Center);
                    assert!(game.has_pending_choice());
                    game.select_option(0); // skip
                    // Bounded: an unbounded drain here would hang the suite rather than fail.
                    let mut safety = 0;
                    while game.has_pending_choice() && safety < 5 {
                        safety += 1;
                        game.select_indices(&[]);
                    }
                    assert!(game.state.player1.hand.cards.contains(&shizuku_hand), "skip should keep Shizuku in hand");
                    game.assert_energy(2, "only the 13E to play 桜坂しずく — a declined optional cost is free");
                }
                /// The hand holds no eligible 桜坂しずく, so nothing can be deployed.
                ///
                /// This test previously asserted almost nothing. Its cleanup loop was
                ///
                /// ```ignore
                /// while game.has_pending_choice() && safety<5 { let _ = game.try_select_indices(&[]); let _ = game.try_select_indices(&[0]); }
                /// ```
                ///
                /// which discarded BOTH `Result`s and attempted BOTH answers unconditionally on every
                /// iteration, so it could neither report a failure nor guarantee progress — the second
                /// call ran even when the first had already answered the prompt. The one assertion it
                /// reached, `hand contains filler`, was already true because the filler was never a
                /// candidate for the deploy.
                ///
                /// The real content of this case is that a deploy with no candidate leaves the board
                /// alone: no member staged, and the unrelated hand card untouched.
                #[test]
                fn shizuku_no_eligible_shizuku_no_deploy() {
                    let db = load_real_database();
                    let mut game = TestGame::new(db);
                    let shizuku = game.id("PL!N-pb1-015-R");
                    let filler = game.id("PL!-sd1-010-SD");
                    game.state.player1.hand.cards.push(shizuku);
                    game.state.player1.hand.cards.push(filler);
                    game.give_energy(15);
                    for _ in 0..5 { game.state.player1.main_deck.cards.push(filler); }
                    game.state.player1.stage.stage = [-1, -1, -1];
                    game.play_to_stage(shizuku, MemberArea::Center);
                    // Pay the optional 2E, then answer whatever the deploy asks. `filler` is not a
                    // 桜坂しずく, so there is no candidate: any SelectCard it offers must be declined.
                    let mut safety = 0;
                    while game.has_pending_choice() && safety < 5 {
                        safety += 1;
                        match game.pending_choice_type().as_deref() {
                            Some("SelectCard") => game.select_indices(&[]),
                            _ => game.select_option(0),
                        }
                    }
                    assert!(
                        game.state.player1.hand.cards.contains(&filler),
                        "the unrelated hand card is not something this ability may move"
                    );
                    assert_eq!(
                        game.state.player1.stage.stage.iter().filter(|&&id| id != -1).count(),
                        1,
                        "only the 桜坂しずく played this turn is on stage: with no eligible member in hand \
                         the deploy adds nothing. Counted rather than compared to a literal so the card \
                         just played is not mistaken for a second member."
                    );
                }
                #[test]
                fn shizuku_insufficient_energy_no_pay() {
                    let db = load_real_database();
                    let mut game = TestGame::new(db);
                    let shizuku = game.id("PL!N-pb1-015-R");
                    let shizuku_hand = game.new_id("PL!N-bp1-015-N");
                    let filler = game.id("PL!-sd1-010-SD");
                    game.state.player1.hand.cards.push(shizuku);
                    game.state.player1.hand.cards.push(shizuku_hand);
                    game.give_energy(1);
                    for _ in 0..5 { game.state.player1.main_deck.cards.push(filler); }
                    game.state.player1.stage.stage = [-1, -1, -1];
                    let res = game.try_play_to_stage(shizuku, MemberArea::Center);
                    assert!(res.is_err(), "should fail to play with only 1 energy, need 13");
                    // The refusal must be "cannot afford", not some unrelated failure: the 1
                    // energy is still unspent and neither card left the hand.
                    game.assert_energy_untouched_after_refusal(1, "insufficient energy to play 静月");
                    assert!(
                        game.state.player1.hand.cards.contains(&shizuku),
                        "a refused play leaves the card in hand"
                    );
                    assert!(
                        game.state.player1.hand.cards.contains(&shizuku_hand),
                        "a refused play must not move the target out of hand either"
                    );
                    assert_eq!(
                        game.state.player1.stage.stage,
                        [-1, -1, -1],
                        "a refused play must leave the stage empty"
                    );
                }
                        }


