                pub mod optional_wait_draw_discard_pl_n_bp4_023_n_test {
                    use crate::helpers::*;
                    use rabuka_engine::core::types::AbilityTrigger;
                    use rabuka_engine::zones::MemberArea;

                    const FILLER: &str = "PL!-sd1-010-SD";

                    fn fire_trigger(game: &mut TestGame, cid: i16, trigger: AbilityTrigger, trig: &str) {
                        fire_trigger_nth(game, cid, trigger, trig, 0);
                    }

                    fn fire_trigger_nth(
                        game: &mut TestGame,
                        cid: i16,
                        trigger: AbilityTrigger,
                        trig: &str,
                        nth: usize,
                    ) {
                        let ability_id = {
                            let card = game.db.get_card(cid).unwrap();
                            let ab = card
                                .resolved_abilities()
                                .filter(|a| a.triggers.as_deref() == Some(trig))
                                .nth(nth)
                                .unwrap_or_else(|| panic!("card {} lacks '{trig}' ability #{nth}", card.card_no));
                            format!("{}_{}", card.card_no, ab.full_text)
                        };
                        let card_no = game.db.get_card(cid).unwrap().card_no.to_string();
                        let pid = game.state.player1.id.clone();
                        game.state.trigger_auto_ability(
                            ability_id,
                            trigger,
                            pid.clone(),
                            Some(card_no),
                            Some(cid),
                            None,
                            None,
                        );
                        game.state.activating_card = Some(cid);
                        game.state.process_pending_auto_abilities(&pid);
                    }

                    #[test]
                    fn pl_n_bp4_023_n_optional_member_wait_gates_draw_discard() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let mia = game.id("PL!N-bp4-023-N");
                        let filler = game.id(FILLER);
                        fill_decks(&mut game, filler);
                        game.add_to_stage(MemberArea::Center, mia);
                        let niji = game.id("PL!N-PR-019-PR");
                        game.add_to_stage(MemberArea::LeftSide, niji);
                        let keep = game.id("PL!N-PR-012-PR");
                        game.add_to_hand(keep);
                        let hand_before = game.state.player1.hand.cards.len();
                        fire_trigger(&mut game, mia, AbilityTrigger::Debut, "登場");
                        assert!(
                            game.has_pending_choice(),
                            "optional wait-cost offer expected on debut"
                        );
                        match game.pending_choice_type().as_deref() {
                            Some("SelectTarget") => game.select_option(0),
                            Some("SelectCard") => game.select_indices(&[]),
                            other => panic!("unexpected {other:?}"),
                        }
                        assert_eq!(
                            game.state.player1.hand.cards.len(),
                            hand_before,
                            "declined cost → no draw/discard"
                        );
                        assert_eq!(
                            game.state.mods.get_orientation_modifier(niji),
                            None,
                            "member untouched when declined"
                        );
                        let sacrifice = game.new_id(FILLER);
                        game.add_to_hand(sacrifice);
                        fire_trigger(&mut game, mia, AbilityTrigger::Debut, "登場");
                        assert!(game.has_pending_choice(), "cost offer expected");
                        match game.pending_choice_type().as_deref() {
                            Some("SelectTarget") => game.select_option(1),
                            Some("SelectCard") => game.select_indices(&[0]),
                            other => panic!("unexpected {other:?}"),
                        }
                        for _ in 0..3 {
                            if !game.has_pending_choice() {
                                break;
                            }
                            match game.get_pending_choice() {
                                rabuka_engine::ability::types::Choice::SelectCard { zone, .. } if zone == "stage" => {
                                    let idx = game
                                        .state
                                        .player1
                                        .stage
                                        .stage
                                        .iter()
                                        .position(|&c| c == niji)
                                        .expect("Niji member still on stage");
                                    game.select_indices(&[idx]);
                                }
                                _ => {
                                    let idx = game
                                        .state
                                        .player1
                                        .hand
                                        .cards
                                        .iter()
                                        .position(|&c| c == sacrifice)
                                        .unwrap_or(0);
                                    game.select_indices(&[idx]);
                                }
                            }
                        }
                        assert_eq!(
                            game.state.mods.get_orientation_modifier(niji),
                            Some("wait"),
                            "accepting waited the Niji member"
                        );
                        assert!(
                            game.state.player1.waitroom.cards.contains(&sacrifice),
                            "the discard step put the chosen card in the waitroom"
                        );
                        assert!(game.state.player1.hand.cards.contains(&keep));
                    }
                                }


                pub mod self_wait_draw_discard_pl_n_bp7_023_n_test {
                    use crate::helpers::*;
                    use rabuka_engine::game_setup::{self, ActionType};

                    // PL!N-bp7-023-N Mia (was happy-path only)
                    // {{起動}}{{ターン1回}}このメンバーをウェイトにする：カードを2枚引き、
                    // 手札を2枚控え室に置く。 Mirrors Natsumi's hostile matrix at 2-card scale.

                    fn use_offers(game: &TestGame, cid: i16) -> usize {
                        game_setup::generate_possible_actions(&game.state)
                            .iter()
                            .filter(|a| {
                                a.action_type == ActionType::UseAbility
                                    && a.parameters.as_ref().and_then(|p| p.card_id) == Some(cid)
                            })
                            .count()
                    }

                    fn drain(game: &mut TestGame) {
                        let mut guard = 0;
                        while game.has_pending_choice() && guard < 15 {
                            guard += 1;
                            game.select_indices(&[0]);
                        }
                        assert!(
                            !game.has_pending_choice(),
                            "prompts should terminate after answering"
                        );
                    }

                    #[test]
                    fn pl_n_bp7_023_n_activation_waits_self_draws_two_discards_two() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let filler = game.new_id("PL!-sd1-010-SD");
                        fill_decks(&mut game, filler);

                        let mia = game.id("PL!N-bp7-023-N");
                        game.state.player1.stage.stage[1] = mia;

                        let d1 = game.new_id("PL!-sd1-001-SD");
                        let d2 = game.new_id("PL!S-sd1-001-SD");
                        game.state.player1.main_deck.cards.insert(0, d2);
                        game.state.player1.main_deck.cards.insert(0, d1);
                        let h1 = game.new_id("PL!-sd1-007-SD");
                        let h2 = game.new_id("PL!-sd1-004-SD");
                        game.add_to_hand(h1);
                        game.add_to_hand(h2);

                        game.activate_ability(mia);
                        assert_eq!(
                            game.state.mods.get_orientation_modifier(mia),
                            Some("wait"),
                            "activation cost waits this member"
                        );

                        let mut guard = 0;
                        while game.has_pending_choice() && guard < 10 {
                            guard += 1;
                            game.select_indices(&[0]);
                        }

                        assert!(
                            game.state.player1.hand.cards.contains(&d1) && game.state.player1.hand.cards.contains(&d2),
                            "drawn cards reached the hand"
                        );
                        assert!(
                            game.state.player1.waitroom.cards.contains(&h1)
                                && game.state.player1.waitroom.cards.contains(&h2),
                            "two hand cards discarded to the waitroom"
                        );
                        assert!(
                            game.state
                                .turn_limited_abilities_used
                                .contains_key(&(mia, 0, game.state.turn_number)),
                            "ターン1回 use recorded"
                        );
                        assert_eq!(use_offers(&game, mia), 0, "no re-offer after consuming");
                    }

                    /// Edge: already-wait Mia → wait-self cost unpayable → refused.
                    #[test]
                    fn pl_n_bp7_023_n_already_wait_refused() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let filler = game.new_id("PL!-sd1-010-SD");
                        fill_decks(&mut game, filler);

                        let mia = game.id("PL!N-bp7-023-N");
                        game.state.player1.stage.stage[1] = mia;
                        game.state.mods.add_orientation_modifier(mia, "wait");
                        game.add_to_hand(game.new_id("PL!-sd1-010-SD"));

                        assert_eq!(use_offers(&game, mia), 0, "waited Mia: not offered");
                        let result = game.try_activate_ability(mia);
                        assert!(
                            result.is_err(),
                            "wait-self on an already-wait member must be refused, got {:?}",
                            result
                        );
                    }

                    /// Edge: EMPTY starting hand → draw 2, then discard exactly those 2
                    /// (forced full-discard selection), ending empty.
                    #[test]
                    fn pl_n_bp7_023_n_empty_hand_draws_then_discards_both() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let filler = game.new_id("PL!-sd1-010-SD");
                        fill_decks(&mut game, filler);

                        let mia = game.id("PL!N-bp7-023-N");
                        game.state.player1.stage.stage[1] = mia;
                        assert!(
                            game.state.player1.hand.cards.is_empty(),
                            "test setup: hand starts empty"
                        );

                        game.activate_ability(mia);
                        drain(&mut game);

                        assert!(
                            game.state.player1.hand.cards.is_empty(),
                            "drew 2 then discarded 2: ends empty"
                        );
                        assert_eq!(
                            game.state.player1.waitroom.cards.len(),
                            2,
                            "both drawn cards reached the waitroom"
                        );
                    }

                    /// Edge: budget resets next turn.
                    #[test]
                    fn pl_n_bp7_023_n_available_again_next_turn() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let filler = game.new_id("PL!-sd1-010-SD");
                        fill_decks(&mut game, filler);

                        let mia = game.id("PL!N-bp7-023-N");
                        game.state.player1.stage.stage[1] = mia;
                        game.add_to_hand(game.new_id("PL!-sd1-010-SD"));
                        game.add_to_hand(game.new_id("PL!-sd1-010-SD"));

                        game.activate_ability(mia);
                        drain(&mut game);
                        assert_eq!(use_offers(&game, mia), 0);

                        game.state.turn_number += 1;
                        // Mia herself is waited now; the limit reset is observed through a fresh
                        // instance (per-instance budget, Kasumi pattern).
                        let mia2 = game.new_id("PL!N-bp7-023-N");
                        game.state.player1.stage.stage[0] = mia2;
                        assert_eq!(
                            use_offers(&game, mia2),
                            1,
                            "fresh instance next turn: offered"
                        );
                    }
                                }


                pub mod self_wait_draw_then_discard_test {
                    use crate::helpers::*;
                    use rabuka_engine::ability::types::Choice;
                    use rabuka_engine::zones::MemberArea;

                    fn fill_decks(game: &mut TestGame, filler: i16) {
                        game.state.player1.main_deck.cards.clear();
                        for _ in 0..30 {
                            game.state.player1.main_deck.cards.push(filler);
                        }
                        game.state.player2.main_deck.cards.clear();
                        for _ in 0..30 {
                            game.state.player2.main_deck.cards.push(filler);
                        }
                    }

                    #[test]
                    fn bp3_001_activation_waits_self_draw_then_discard() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);

                        let card = game.id("PL!-bp3-001-R"); // cost 13
                        let filler = game.id("PL!-sd1-010-SD");

                        game.give_energy(15);
                        fill_decks(&mut game, filler);
                        game.state.player1.hand.cards.push(card);
                        game.state.player1.hand.cards.push(filler);
                        game.play_to_stage(card, MemberArea::Center);
                        // Answer what cannot be declined, decline what can: a mandatory
                        // prompt left parked mid-ability produces exactly the absence
                        // the next assertion checks, so nothing fails.
                        game.drain_choices();

                        game.activate_ability(card);

                        // Cost paid: self waited.
                        assert_eq!(
                            game.state.mods.get_orientation_modifier(card),
                            Some("wait"),
                            "cost: member should be waited"
                        );
                        // Effect: drew 1, now must discard 1 from hand. The discard is
                        // mandatory ("手札を1枚控え室に置く" — no もよい), so allow_skip=false.
                        match game.get_pending_choice() {
                            Choice::SelectCard {
                                zone, allow_skip, ..
                            } => {
                                assert_eq!(zone, "hand", "discard must come from hand");
                                assert!(!allow_skip, "mandatory discard must not be skippable");
                            }
                            _other => panic!(
                                "expected SelectCard for the hand discard, got {}",
                                game.pending_choice_summary()
                            ),
                        }
                        let hand_at_prompt = game.state.player1.hand.cards.len();
                        let discard_target = game.state.player1.hand.cards[0];
                        game.select_indices(&[0]);

                        assert_eq!(
                            game.state.player1.hand.cards.len(),
                            hand_at_prompt - 1,
                            "resolve discard: prompt-time hand minus the discarded card"
                        );
                        assert!(
                            game.state.player1.waitroom.cards.contains(&discard_target),
                            "selected card must be in the waitroom"
                        );

                        // {{ターン1回}} — a second press in the same turn is rejected outright:
                        // the member is waited (activations need an active member), so the
                        // engine refuses before even reaching the use-limit bookkeeping.
                        let err = game.try_activate_ability(card).unwrap_err();
                        assert!(
                            err.contains("No activatable") || err.contains("turn") || err.contains("already"),
                            "expected second activation to be rejected, got: {}",
                            err
                        );
                    }
                                }


