                        let choice = game.get_pending_choice();
                        match choice {
                            rabuka_engine::ability::types::Choice::SelectCard { count, .. } => {
                                assert_eq!(
                                    *count, 1,
                                    "should ask for exactly 1 card, even with multiple under"
                                );
                            }
                            _ => panic!("Expected SelectCard"),
                        }

                        game.select_indices(&[0]);
