                            game.state.player1.hand.cards.push(filler);
                            game.state.player1.main_deck.cards.clear();
                            game.state.player1.main_deck.cards.push(liella);
                            game.state.player1.main_deck.cards.push(liella);
                            game.state.player1.main_deck.cards.push(filler);
