                            // PL!S-sd1-019-SD: heart02:1+heart04:1+heart05:1 = 3, Aqours
                            let live_a = game.id("PL!S-sd1-019-SD");
                            let live_b = game.id("PL!S-sd1-019-SD");
                            let live_c = game.id("PL!S-sd1-019-SD");

                            game.state.player1.stage.stage = [-1, riko, -1];
