                    assert_eq!(draw_result.draw_icons, 1);
                    assert_eq!(draw_result.blade_hearts[5], 0);
                    assert_eq!(draw_result.blade_hearts[6], 1);

                    let colorless_result = yell_card(snapshot, "PL!N-bp7-030-L");
