                pub mod self_to_waitroom_live_recovery_energy_activation_test {
                    use crate::helpers::*;
                    use rabuka_engine::zones::MemberArea;

                    const FILLER: &str = "PL!-sd1-010-SD";
                    /// Aqours, printed score **exactly 6** — the bound 「スコア6以上の」 names.
                    /// This is the only class of fixture that separates `>= 6` from `> 6`.
                    const AQOURS_EXACTLY_6: &str = "PL!S-pb1-020-L";

                    fn live_recovery_energy_activation_board_pl_s_bp3_008_r(game: &mut TestGame, active: u8) -> (i16, i16, i16) {
                        let mari = game.id("PL!S-bp3-008-R");
                        let aqours_high = game.id("PL!S-pb1-023-L");
                        let niji_low = game.id("PL!N-bp1-028-L");
                        game.add_to_stage(MemberArea::Center, mari);
                        game.add_to_discard(aqours_high);
                        game.add_to_discard(niji_low);
                        let energy = game.id("LL-E-001-SD");
                        for _ in 0..6 {
                            game.state.player1.energy_zone.cards.push(energy);
                        }
                        game.state.player1.energy_zone.set_active_count(active);
                        (mari, aqours_high, niji_low)
                    }

                    #[test]
                    fn self_to_waitroom_recovers_high_score_aqours_live_and_activates_four_pl_s_bp3_008_r() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let (mari, aqours_high, _) = live_recovery_energy_activation_board_pl_s_bp3_008_r(&mut game, 2);

                        game.activate_ability(mari);

                        assert!(
                            game.state.player1.waitroom.cards.contains(&mari),
                            "activation cost sends Mari herself to the waitroom"
                        );
                        assert_eq!(game.state.player1.stage.stage[1], -1, "Q79: area vacated");

                        assert!(game.has_pending_choice(), "live selection must be offered");
                        let idx = game
                            .state
                            .player1
                            .waitroom
                            .cards
                            .iter()
                            .position(|&c| c == aqours_high)
                            .expect("Aqours high live offered");
                        game.select_indices(&[idx]);

                        assert!(game.state.player1.hand.cards.contains(&aqours_high));
                        assert_eq!(
                            game.state.player1.energy_zone.active_count(),
                            6,
                            "Aqours score≥6 fetched → activate 4 (2+4=6)"
                        );
                    }

                    #[test]
                    fn recovering_wrong_group_live_skips_energy_activation_pl_s_bp3_008_r() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let (mari, _, niji_low) = live_recovery_energy_activation_board_pl_s_bp3_008_r(&mut game, 2);

                        game.activate_ability(mari);
                        let idx = game
                            .state
                            .player1
                            .waitroom
                            .cards
                            .iter()
                            .position(|&c| c == niji_low)
                            .expect("non-Aqours live also selectable");
                        game.select_indices(&[idx]);

                        assert!(game.state.player1.hand.cards.contains(&niji_low));
                        assert_eq!(
                            game.state.player1.energy_zone.active_count(),
                            2,
                            "『Aqours』 filter fails → NO activation"
                        );
                    }

                    #[test]
                    fn recovering_aqours_live_below_six_skips_energy_activation_pl_s_bp3_008_r() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let (mari, aqours_high, _) = live_recovery_energy_activation_board_pl_s_bp3_008_r(&mut game, 2);

                        let aqours_low = game.id("PL!S-PR-024-PR");
                        game.state
                            .player1
                            .waitroom
                            .cards
                            .retain(|c| *c != aqours_high);
                        game.add_to_discard(aqours_low);

                        game.activate_ability(mari);
                        let idx = game
                            .state
                            .player1
                            .waitroom
                            .cards
                            .iter()
                            .position(|&c| c == aqours_low)
                            .expect("low Aqours live selectable");
                        game.select_indices(&[idx]);

                        assert!(game.state.player1.hand.cards.contains(&aqours_low));
                        assert_eq!(
                            game.state.player1.energy_zone.active_count(),
                            2,
                            "スコア6以上 fails at exactly-below boundary → NO activation"
                        );
                    }

                    /// The bound itself: 「スコア6以上」 must fire at exactly 6.
                    ///
                    /// The suite's qualifying case uses `PL!S-pb1-023-L` at printed score **9**, and its
                    /// failing case uses score 5. Nothing sat on 6, so these implementations all passed
                    /// identically: `>= 6` (correct), `> 6`, `>= 7`, `>= 9`. Only a card printing exactly 6
                    /// separates them.
                    #[test]
                    fn recovering_aqours_live_scoring_exactly_six_still_activates_pl_s_bp3_008_r() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let (mari, aqours_high, niji_low) = live_recovery_energy_activation_board_pl_s_bp3_008_r(&mut game, 2);

                        // Replace the board with only the exactly-6 live, and pin its printed score AND group.
                        // Both matter: the clause is 『Aqours』のライブカード AND スコア6以上, and the suite
                        // otherwise pins the group with the score-9 card and the score with the score-5 card,
                        // never both on one card.
                        let exact = game.id(AQOURS_EXACTLY_6);
                        game.assert_card_identity(exact, AQOURS_EXACTLY_6);
                        game.assert_card_score(exact, 6);
                        game.state
                            .player1
                            .waitroom
                            .cards
                            .retain(|c| !(*c == aqours_high || *c == niji_low));
                        game.state.player1.waitroom.cards.push(exact);

                        game.activate_ability(mari);
                        // Only one live is in the waitroom and the clause matches it, so the mandatory fetch
                        // resolves on the spot and opens NO prompt. Answering nothing is therefore the correct
                        // interaction here — a prompt would mean a second card had wrongly qualified.
                        assert!(
                            !game.has_pending_choice(),
                            "precondition: exactly one live matches スコア6以上 + 『Aqours』, so count:1 resolves \
                             without asking. A prompt here means some other card was offered too."
                        );

                        assert!(
                            game.state.player1.hand.cards.contains(&exact),
                            "precondition: the score-6 live was recovered"
                        );
                        assert_eq!(
                            game.state.player1.energy_zone.active_count(),
                            6,
                            "スコア6以上 — an Aqours live printing EXACTLY 6 satisfies the bound, so 4 energy \
                             activate (2+4=6). A value of 2 means the comparison is reading the bound as \
                             exclusive (`> 6`) or as 7/9; the rest of this file only ever stages 9 and 5."
                        );
                    }

                    #[test]
                    fn self_to_waitroom_cost_paid_without_recoverable_live_pl_s_bp3_008_r() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);

                        let mari = game.id("PL!S-bp3-008-R");
                        game.add_to_stage(MemberArea::Center, mari);
                        game.add_to_discard(game.new_id(FILLER));

                        game.activate_ability(mari);
                        // Answer what cannot be declined, decline what can: a mandatory
                        // prompt left parked mid-ability produces exactly the absence
                        // the next assertion checks, so nothing fails.
                        game.drain_choices();
                        assert!(
                            game.state.player1.waitroom.cards.contains(&mari),
                            "Q123: usable — cost was paid"
                        );
                        assert!(
                            game.state.player1.hand.cards.is_empty(),
                            "nothing added when no live exists"
                        );
                        assert_eq!(
                            game.state.player1.energy_zone.active_count(),
                            0,
                            "no fetch → no activation"
                        );
                    }

                    #[test]
                    fn live_recovery_is_mandatory_and_excludes_members_pl_s_bp3_008_r() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let (mari, aqours_high, _niji_low) = live_recovery_energy_activation_board_pl_s_bp3_008_r(&mut game, 2);
                        let member_in_waitroom = game.new_id(FILLER);
                        game.add_to_discard(member_in_waitroom);

                        game.activate_ability(mari);

                        let member_idx = game
                            .state
                            .player1
                            .waitroom
                            .cards
                            .iter()
                            .position(|&c| c == member_in_waitroom)
                            .expect("member present in waitroom");

                        let member_pick = game.try_select_indices(&[member_idx]);
                        let _ = member_pick;
                        assert!(
                            !game.state.player1.hand.cards.contains(&member_in_waitroom),
                            "member card must NEVER reach the hand via this ability"
                        );

                        while game.has_pending_choice() {
                            let live_here = game
                                .state
                                .player1
                                .waitroom
                                .cards
                                .iter()
                                .position(|&c| c == aqours_high);
                            match live_here {
                                Some(idx) => {
                                    game.select_indices(&[idx]);
                                    break;
                                }
                                None => game.select_indices(&[0]),
                            }
                        }
                        assert!(
                            game.state.player1.hand.cards.contains(&aqours_high),
                            "Q123: mandatory fetch — a live card MUST reach the hand"
                        );
                        assert!(
                            !game.state.player1.hand.cards.contains(&member_in_waitroom)
                                && game.state.player1.waitroom.cards.contains(&member_in_waitroom),
                            "the member stayed in the waitroom"
                        );
                    }

                    #[test]
                    fn recovered_live_activates_only_available_energy_candidates_pl_s_bp3_008_r() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let (mari, aqours_high, _) = live_recovery_energy_activation_board_pl_s_bp3_008_r(&mut game, 1);
                        while game.state.player1.energy_zone.cards.len() > 3 {
                            game.state.player1.energy_zone.cards.pop();
                        }
                        game.activate_ability(mari);
                        let idx = game
                            .state
                            .player1
                            .waitroom
                            .cards
                            .iter()
                            .position(|&c| c == aqours_high)
                            .expect("Aqours high live offered");
                        game.select_indices(&[idx]);

                        assert_eq!(
                            game.state.player1.energy_zone.active_count(),
                            3,
                            "activate 4 requested but only 2 waited energies exist → Q167 partial \
                             resolution activates those 2 instead of aborting (1+2=3)"
                        );
                    }
                                }


                pub mod self_to_waitroom_recover_live_q79_q123_test {
                    /// Tests for PL!-sd1-005-SD 星空凛 — Activation ability (ab#0):
                    ///
                    /// {{kidou.png|起動}}このメンバーをステージから控え室に置く：
                    /// 自分の控え室からライブカードを1枚手札に加える。
                    ///
                    /// Cost: put this member from stage to waitroom (self_cost).
                    /// Effect: recover 1 live card from waitroom to hand.
                    ///
                    /// Q123: Can you activate with no live cards in waitroom? A: Yes.
                    ///       (Effect does nothing, but cost is still paid.)
                    /// Q79:  After activating, can a new member be placed in the vacated area? A: Yes.
                    use crate::helpers::*;

                    /// Q123: Activate ability when waitroom has no live cards — cost still paid.
                    #[test]
                    fn q123_self_cost_is_paid_without_recoverable_live() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db.clone());

                        let rin = game.id("PL!-sd1-005-SD");
                        let filler = game.id("PL!-sd1-010-SD");

                        // Stage: 星空凛 at center
                        game.state.player1.stage.stage = [-1, rin, -1];

                        // Hand: a card for hand count (not relevant here)
                        game.add_to_hand(filler);

                        // No live cards in waitroom
                        game.give_energy(3);

                        let stage_before = game.state.player1.stage.stage[1];
                        assert_eq!(
                            stage_before, rin,
                            "Rin should be on stage before activation"
                        );

                        game.activate_ability(rin);

                        // Self_cost moved Rin off stage → stage center should be empty
                        assert_eq!(
                            game.state.player1.stage.stage[1], -1,
                            "Rin should be removed from stage after self_cost"
                        );

                        // Rin should be in waitroom
                        assert!(
                            game.state.player1.waitroom.cards.contains(&rin),
                            "Rin should be in waitroom after self_cost"
                        );

                        // No live card was recovered (waitroom had none), but ability succeeded
                        // The effect gracefully did nothing
                    }

                    /// The sacrificed member is NOT a candidate here — the exact mirror of the member
                    /// variant.
                    ///
                    /// Two abilities in this family share the self_cost and differ only in the recovery's
                    /// `card_type`, and that one field decides whether the cost's own card is eligible:
                    ///
                    ///   * 「…控え室から**メンバーカード**を1枚」 — the sacrificed member IS a member card,
                    ///     so it qualifies and can be recovered.
                    ///     (`self_to_waitroom_recover_member_q79_test.rs`)
                    ///   * 「…控え室から**ライブカード**を1枚」 — the sacrificed member is not a live card,
                    ///     so it cannot be, whatever else is in the waitroom. This file.
                    ///
                    /// Pinning only the first would leave `card_type: live_card` unverified in the
                    /// direction that actually excludes something: a recovery that ignored the filter
                    /// would pick Rin out of a waitroom containing only her, and pass every other test in
                    /// this file.
                    ///
                    /// With Rin and one live card in the waitroom there is exactly one candidate, so the
                    /// ability resolves without asking. `drain_choices_strict` makes a prompt a failure:
                    /// two candidates would mean Rin was offered.
                    #[test]
                    fn q123_the_sacrificed_member_is_not_a_candidate_for_the_live_recovery() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);

                        let rin = game.id("PL!-sd1-005-SD");
                        let live_card = game.id("PL!-sd1-019-SD");

                        game.state.player1.stage.stage = [-1, rin, -1];
                        game.add_to_discard(live_card);
                        game.give_energy(3);

                        game.activate_ability(rin);
                        game.drain_choices_strict(&[], &[]);

                        assert!(
                            game.state.player1.hand.cards.contains(&live_card),
                            "the live card is the only 『ライブカード』 in the waitroom and is recovered"
                        );
                        assert!(
                            game.state.player1.waitroom.cards.contains(&rin),
                            "Rin is a member, and 「ライブカードを1枚」 excludes her — she stays in the \
                             waitroom; waitroom is {:?}",
                            game.state.player1.waitroom.cards
                        );
                        assert!(
                            !game.state.player1.hand.cards.contains(&rin),
                            "and specifically does not come back to hand"
                        );
                    }

                    /// Q79: After self_cost removes the member, the vacated area is empty and
                    /// can receive a new card.
                    #[test]
                    fn q79_self_cost_vacates_center_and_recovers_live() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db.clone());

                        let rin = game.id("PL!-sd1-005-SD");
                        let live_card = game.id("PL!-sd1-019-SD");

                        // Stage: 星空凛 at center
                        game.state.player1.stage.stage = [-1, rin, -1];

                        // The live card goes in the WAITROOM and nowhere else.
                        //
                        // It used to be added to the hand as well, from the same `game.id()` call, which
                        // put one card instance in two zones at once — and made the assertion below
                        // unfalsifiable, since `hand.contains(&live_card)` was already true before the
                        // ability ran. The comment claimed the hand copy was there "so waitroom has a
                        // target for recovery", but the waitroom copy is the target; the hand copy only
                        // guaranteed a pass.
                        game.add_to_discard(live_card);
                        game.give_energy(3);

                        assert!(
                            !game.state.player1.hand.cards.contains(&live_card),
                            "fixture: the live card must start in the waitroom only, or the recovery \
                             assertion below proves nothing"
                        );

                        game.activate_ability(rin);

                        // Center stage should be empty after self_cost
                        assert_eq!(
                            game.state.player1.stage.stage[1], -1,
                            "Center area should be empty after self_cost"
                        );

                        // Waitroom should have Rin (from self_cost) — live card was recovered
                        assert!(
                            game.state.player1.waitroom.cards.contains(&rin),
                            "Rin should be in waitroom"
                        );
                        assert!(
                            game.state.player1.hand.cards.contains(&live_card),
                            "Live card should be recovered to hand"
                        );

                        // The vacated center area can receive a new card (empty slot exists)
                    }
                                }


                pub mod self_to_waitroom_recover_member_own_card_is_candidate_test {
                    /// The 30-card 「このメンバーをステージから控え室に置く：自分の控え室からメンバーカードを
                    /// 1枚手札に加える」 family — the MEMBER-recovery variant, which has no test as a
                    /// subject of its own.
                    ///
                    /// `cards/abilities.json`: 起動, `cost: move_cards { self_cost: true, stage -> discard }`,
                    /// `effect: move_cards { source: discard, destination: hand, card_type: member_card }`.
                    ///
                    /// # Why the sibling variant's tests do not cover this one
                    ///
                    /// There are two families with the same 30-card-shaped cost and opposite recovery
                    /// filters, and the LIVE one is covered
                    /// (`self_to_waitroom_recover_live_q79_q123_test.rs`). Its central finding is that the
                    /// sacrificed member is NOT a candidate there — because the filter is
                    /// `card_type: live_card` and the cost put a member in the waitroom.
                    ///
                    /// Here the filter is `card_type: member_card`. The sacrificed member IS a member card
                    /// and IS in the waitroom. Nothing in the text excludes it, so it qualifies — and with
                    /// an empty waitroom it is the ONLY candidate, so the ability recovers the very card
                    /// its cost just sacrificed.
                    ///
                    /// That makes the card a self-cancelling search: 「look in my waitroom for a member」
                    /// with a self-sacrifice that can be undone. An implementation that snapshots
                    /// "cards moved by this cost" and excludes the mover — a reasonable-looking
                    /// optimisation, and the shape `ability/effects/deck.rs:234` uses for the mirrored
                    /// 「これにより…ウェイト状態にした」 wording — would find nothing here.
                    ///
                    /// # Fixtures verified
                    ///
                    /// All 30 cards are `type: メンバー` and `cost: 2`, read from `cards.json`, so the
                    /// activation is affordable and every candidate genuinely satisfies the filter. Cards
                    /// are picked from across the family's units (Printemps/BiBi, 虹ヶ咲, Liella!,
                    /// 5yncri5e!, lily white, AZALEA, CatChu!) so nothing here depends on group matching.
                    use crate::helpers::*;
                    use rabuka_engine::zones::MemberArea;

                    const SUBJECT: &str = "PL!S-bp2-016-N"; // 国木田 花丸, cost 2
                    const OTHER: &str = "PL!N-bp4-017-N"; // 宮下 愛, cost 2

                    /// Stage `subject`, put `waitroom` in the waitroom, activate, and report the subject's
                    /// id alongside the resulting hand and waitroom.
                    fn recovered_into_hand(subject: &str, waitroom: &[&str]) -> (i16, Vec<i16>, Vec<i16>) {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let me = game.id(subject);
                        for card_no in waitroom {
                            let id = game.id(card_no);
                            assert_eq!(
                                game.db.get_card(id).map(|c| c.card_type.clone()),
                                Some(rabuka_engine::card::CardType::Member),
                                "fixture: {card_no} must be a メンバー — the recovery filters on member_card"
                            );
                            game.state.player1.waitroom.cards.push(id);
                        }

                        game.state.player1.stage.stage[1] = me;
                        game.give_energy(5);
                        game.activate_ability(me);
                        // Nothing is asked. With an empty waitroom the sacrificed member is the only
                        // candidate, so the recovery resolves on its own; and the prompted case has its
                        // own test, which asserts the prompt rather than tolerating it here. Asserting
                        // the absence is stronger than a drain that answers whatever turns up
                        // (docs/EDGE_CASE_FINDINGS.md C9), and it keeps this file off the soft-guard and
                        // drain-loop ratchets.
                        game.drain_choices_strict(&[], &[]);

                        (
                            me,
                            game.state.player1.hand.cards.iter().copied().collect(),
                            game.state.player1.waitroom.cards.iter().copied().collect(),
                        )
                    }

                    /// The cost undoes itself: with an empty waitroom the sacrificed member is the only
                    /// candidate, so she comes straight back to hand.
                    #[test]
                    fn the_sacrificed_member_is_recovered_by_her_own_ability() {
                        let (me, hand, waitroom) = recovered_into_hand(SUBJECT, &[]);

                        assert!(
                            hand.contains(&me),
                            "the cost put her in the waitroom and 「自分の控え室からメンバーカードを1枚」 \
                             takes her straight back out — nothing in the text excludes the card this \
                             ability just moved; hand={hand:?}"
                        );
                        assert!(
                            waitroom.is_empty(),
                            "she left the waitroom again; waitroom={waitroom:?}"
                        );
                    }

                    /// With a second member in the waitroom there are two candidates, so the engine
                    /// must ask — and the sacrificed member must be one of the options.
                    ///
                    /// This is the test that pins candidacy rather than coincidence. Test 1 shows the
                    /// outcome; this one shows she is genuinely selectable, which is the property an
                    /// implementation excluding "the card this cost moved" would lose.
                    #[test]
                    fn the_sacrificed_member_is_offered_beside_a_pre_existing_one() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let me = game.id(SUBJECT);
                        let other = game.id(OTHER);
                        game.state.player1.waitroom.cards.push(other);
                        game.state.player1.stage.stage[1] = me;
                        game.give_energy(5);

                        game.activate_ability(me);
                        assert_eq!(
                            game.pending_choice_type().as_deref(),
                            Some("SelectCard"),
                            "two member cards are in the waitroom, so the recovery asks which"
                        );
                        let me_idx = game
                            .state
                            .player1
                            .waitroom
                            .cards
                            .iter()
                            .position(|&id| id == me)
                            .expect("the cost put her in the waitroom");
                        game.select_indices(&[me_idx]);
                        game.drain_choices_strict(&[], &[]);

                        assert!(
                            game.state.player1.hand.cards.contains(&me),
                            "picking her returns her to hand — she is a candidate, not merely present"
                        );
                        assert!(
                            game.state.player1.waitroom.cards.contains(&other),
                            "the other member stays; only one card was recovered"
                        );
                    }

                    /// A card that is NOT a member is not recovered, even though it is in the waitroom.
                    ///
                    /// Pins the filter as the thing that excludes. Without it, the two tests above pass on
                    /// an implementation that recovers any card from the waitroom.
                    #[test]
                    fn a_live_in_the_waitroom_is_not_a_candidate() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let me = game.id(SUBJECT);
                        let live = game.id("PL!-sd1-019-SD");
                        game.state.player1.waitroom.cards.push(live);
                        game.state.player1.stage.stage[1] = me;
                        game.give_energy(5);

                        game.activate_ability(me);
                        game.drain_choices_strict(&[], &[]);

                        assert!(
                            !game.state.player1.hand.cards.contains(&live),
                            "「メンバーカードを1枚」 — a live card in the waitroom is not a candidate"
                        );
                    }
                                }


                pub mod self_to_waitroom_recover_member_q79_test {
                    /// PL!-sd1-002-SD (絢瀬絵里) ab#0 — Q79
                    ///
                    /// {{kidou.png|起動}}このメンバーをステージから控え室に置く：
                    /// 自分の控え室からメンバーカードを1枚手札に加える。
                    ///
                    /// Q79: After using this ability (self_cost removes Eli from stage),
                    /// can a new member card be placed in the vacated area?
                    /// A: Yes — the self_cost empties the area, making it available.
                    ///
                    /// The two tests at the top cover the part Q79 does not: the cost puts Eli in the
                    /// waitroom, and the effect then looks for a member card in the waitroom.
                    ///
                    /// The sacrificed member is ITSELF a legal recovery target.
                    ///
                    /// 「このメンバーをステージから控え室に置く：自分の控え室からメンバーカードを1枚手札に
                    /// 加える」 puts the member in the waitroom and then looks for a member card in the
                    /// waitroom. Nothing in the text excludes the card it just put there, so the member
                    /// qualifies — and with an EMPTY waitroom it is the only candidate, so there is
                    /// nothing to choose and the ability resolves on its own.
                    ///
                    /// The net result is a round trip: stage → waitroom → hand, with the stage slot
                    /// vacated. That is not a null effect (Q79, above: the slot becomes available) but it
                    /// does mean the card can be used to move a member out of the way.
                    ///
                    /// The existing test in this file walks straight past this. Its comment says the
                    /// waitroom holds "ONLY the target member (avoids selection choice)" and then
                    /// immediately notes that a prompt appears anyway "because waitroom has 2 member cards
                    /// (target_member + Eli after self_cost)" — the sacrificed member is candidate zero,
                    /// and picking the other card means nothing ever asserts it is one.
                    #[test]
                    fn q79_the_sacrificed_member_is_itself_a_recovery_target() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);

                        let eli = game.id("PL!-sd1-002-SD");
                        let bystander = game.id("PL!-sd1-010-SD"); // stays in hand throughout

                        game.state.player1.stage.stage = [-1, eli, -1];
                        game.add_to_hand(bystander);
                        game.give_energy(5);

                        assert!(
                            game.state.player1.waitroom.cards.is_empty(),
                            "fixture: the waitroom starts empty, so the sacrificed member is the only \
                             possible candidate"
                        );

                        game.activate_ability(eli);
                        // A prompt here would mean the engine filtered the just-moved card OUT of the
                        // candidates. With one candidate there is nothing to choose, so anything asked
                        // is a bug rather than a choice.
                        game.drain_choices_strict(&[], &[]);

                        assert!(
                            game.state.player1.hand.cards.contains(&eli),
                            "「自分の控え室からメンバーカードを1枚」 — she is a member card in the \
                             waitroom now, so she comes back to hand; hand is {:?}",
                            game.state.player1.hand.cards
                        );
                        assert_eq!(
                            game.state.player1.stage.stage[1],
                            -1,
                            "the self_cost still vacates the slot — recovering her does not put her back"
                        );
                        assert!(
                            game.state.player1.waitroom.cards.is_empty(),
                            "she left the waitroom; waitroom is {:?}",
                            game.state.player1.waitroom.cards
                        );
                        assert!(
                            game.state.player1.hand.cards.contains(&bystander),
                            "and the unrelated hand card is untouched"
                        );
                    }

                    /// With a member already in the waitroom, BOTH are offered — including her.
                    ///
                    /// The companion to the test above, and the one that matters: it proves she is a
                    /// *candidate* rather than merely present in the zone. Selecting the index she
                    /// occupies in the waitroom and getting her back is only possible if the engine put
                    /// her in the candidate list.
                    #[test]
                    fn q79_the_sacrificed_member_is_offered_beside_a_pre_existing_one() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);

                        let eli = game.id("PL!-sd1-002-SD");
                        let target_member = game.id("PL!-sd1-001-SD");

                        game.state.player1.stage.stage = [-1, eli, -1];
                        game.add_to_discard(target_member);
                        game.give_energy(5);

                        game.activate_ability(eli);

                        assert_eq!(
                            game.pending_choice_type().as_deref(),
                            Some("SelectCard"),
                            "two member cards are in the waitroom, so the recovery asks which one"
                        );
                        let eli_idx = game
                            .state
                            .player1
                            .waitroom
                            .cards
                            .iter()
                            .position(|&id| id == eli)
                            .expect("the sacrificed member is in the waitroom and must be selectable");
                        game.select_indices(&[eli_idx]);
                        game.drain_choices_strict(&[], &[]);

                        assert!(
                            game.state.player1.hand.cards.contains(&eli),
                            "picking the sacrificed member returns her to hand; hand is {:?}",
                            game.state.player1.hand.cards
                        );
                        assert!(
                            game.state.player1.waitroom.cards.contains(&target_member),
                            "the other member stays in the waitroom — only one card was recovered"
                        );
                    }
                    use crate::helpers::*;
                    use rabuka_engine::zones::MemberArea;

                    #[test]
                    fn q79_self_cost_vacates_area_for_new_member() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db.clone());

                        let eli = game.id("PL!-sd1-002-SD");
                        let target_member = game.id("PL!-sd1-001-SD");
                        let new_member = game.id("PL!-sd1-003-SD");
                        let filler = game.id("PL!-sd1-010-SD");

                        // Stage: 絢瀬絵里 at center (set directly, no need for play)
                        game.state.player1.stage.stage = [-1, eli, -1];
                        // Hand: filler (discard for hand count), new_member (for Q79 placement test)
                        game.add_to_hand(filler);
                        game.add_to_hand(new_member);

                        // Waitroom: ONLY the target member (avoids selection choice)
                        game.add_to_discard(target_member);

                        // Enough energy for new_member's play cost (cost=13)
                        game.give_energy(15);

                        // Activate Eli's ability (self_cost → recover → vacates center)
                        game.activate_ability(eli);

                        // The ability creates a selection choice because waitroom has 2 member cards
                        // (target_member + Eli after self_cost). Resolve the choice first.
                        assert!(
                            game.has_pending_choice(),
                            "waitroom recover selection prompt expected"
                        );
                        assert_eq!(
                            game.pending_choice_type().as_deref(),
                            Some("SelectCard"),
                            "expected SelectCard (recover from waitroom)"
                        );
                        // Find target_member's index in waitroom to recover it
                        let idx = game
                            .state
                            .player1
                            .waitroom
                            .cards
                            .iter()
                            .position(|&id| id == target_member)
                            .expect("target_member should be in waitroom");
                        game.select_indices(&[idx]);

                        // After activation, center should be empty (self_cost removed Eli)
                        assert_eq!(
                            game.state.player1.stage.stage[1], -1,
                            "Self_cost vacated center area"
                        );

                        // Q79: A new member CAN be placed in the vacated center area
                        game.play_to_stage(new_member, MemberArea::Center);
                        assert_eq!(
                            game.state.player1.stage.stage[1], new_member,
                            "New member placed in previously vacated center area"
                        );
                    }
                                }


