                pub mod success_score_live_pl_bp6_013_n_test {
                    use crate::helpers::*;
                    use rabuka_engine::core::types::AbilityTrigger;

                    fn fire_debut(game: &mut TestGame, cid: i16) {
                        let ability_id = {
                            let card = game.db.get_card(cid).unwrap();
                            let ab = card
                                .resolved_abilities()
                                .find(|a| a.triggers.as_deref() == Some("登場"))
                                .unwrap_or_else(|| panic!("card {} lacks a 登場 ability", card.card_no));
                            format!("{}_{}", card.card_no, ab.full_text)
                        };
                        let card_no = game.db.get_card(cid).unwrap().card_no.to_string();
                        let pid = game.state.player1.id.clone();
                        game.state.trigger_auto_ability(
                            ability_id,
                            AbilityTrigger::Debut,
                            pid.clone(),
                            Some(card_no),
                            Some(cid),
                            None,
                            None,
                        );
                        game.state.activating_card = Some(cid);
                        game.state.process_pending_auto_abilities(&pid);
                    }

                    fn pl_bp6_013_n_setup_waitroom_live(game: &mut TestGame) -> (i16, i16) {
                        let filler = game.new_id("PL!-sd1-010-SD");
                        fill_decks(game, filler);
                        let me = game.id("PL!-bp6-013-N");
                        game.state.player1.stage.stage[0] = me;
                        let mus_live = game.id("PL!-sd1-020-SD");
                        game.state.player1.waitroom.cards.push(mus_live);
                        (me, mus_live)
                    }

                    #[test]
                    fn pl_bp6_013_n_success_score_nine_recovers_mus_live_to_hand() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let (me, mus_live) = pl_bp6_013_n_setup_waitroom_live(&mut game);
                        let big = game.id("PL!S-pb1-023-L");
                        game.state.player1.success_live_card_zone.cards.push(big);
                        fire_debut(&mut game, me);
                        let mut guard = 0;
                        while game.has_pending_choice() && guard < 10 {
                            guard += 1;
                            game.select_indices(&[0]);
                        }
                        assert!(
                            game.state.player1.hand.cards.contains(&mus_live),
                            "score total >= 6 -> μ's live retrieved to hand"
                        );
                    }

                    #[test]
                    fn pl_bp6_013_n_empty_success_zone_does_not_recover_live() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let (me, mus_live) = pl_bp6_013_n_setup_waitroom_live(&mut game);
                        fire_debut(&mut game, me);
                        let mut guard = 0;
                        while game.has_pending_choice() && guard < 10 {
                            guard += 1;
                            game.select_indices(&[0]);
                        }
                        assert!(
                            !game.state.player1.hand.cards.contains(&mus_live),
                            "empty success zone -> no retrieval"
                        );
                    }
                                }


                pub mod success_zone_revealed_members_pl_s_bp5_019_l_test {
                    use crate::helpers::*;
                    use rabuka_engine::core::types::AbilityTrigger;

                    const FILLER: &str = "PL!N-sd1-010-SD";

                    #[test]
                    fn pl_s_bp5_019_l_two_own_success_cards_retrieve_two_revealed_members() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let filler = game.new_id(FILLER);
                        fill_decks(&mut game, filler);
                        let live = game.id("PL!S-bp5-019-L");
                        game.add_to_hand(live);
                        game.set_live_card(live);
                        for no in ["PL!-sd1-019-SD", "PL!HS-bp2-020-L"] {
                            let s = game.new_id(no);
                            game.state.player1.success_live_card_zone.cards.push(s);
                        }
                        let m1 = game.new_id("PL!N-sd1-006-P");
                        let m2 = game.new_id("PL!N-bp1-009-R");
                        game.state.revealed_cards.clear();
                        game.state.revealed_cards.push(m1);
                        game.state.revealed_cards.push(m2);
                        fire_trigger(&mut game, live, AbilityTrigger::LiveSuccess, "ライブ成功時");
                        assert!(
                            game.has_pending_choice(),
                            "up-to-2 member selection prompt expected"
                        );
                        assert_eq!(
                            game.pending_choice_type().as_deref(),
                            Some("SelectCard"),
                            "expected SelectCard (revealed_cards, count=2)"
                        );
                        game.select_indices(&[0, 1]);
                        let mut guard = 0;
                        while game.has_pending_choice() && guard < 10 {
                            guard += 1;
                            game.select_indices(&[0]);
                        }
                        assert!(
                            game.state.player1.hand.cards.contains(&m1) && game.state.player1.hand.cards.contains(&m2),
                            "gate met -> up to 2 members retrieved to hand"
                        );
                    }

                    #[test]
                    fn p2_success_zone_gate_allows_partial_own_revealed_member_retrieval() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let filler = game.new_id(FILLER);
                        fill_decks(&mut game, filler);
                        let live = game.id("PL!S-bp5-019-L");
                        game.add_to_hand(live);
                        game.set_live_card(live);

                        game.state.player2.success_live_card_zone.cards.push(game.new_id("PL!-sd1-019-SD"));
                        game.state.player2.success_live_card_zone.cards.push(game.new_id("PL!HS-bp2-020-L"));
                        let member_a = game.new_id("PL!N-sd1-006-P");
                        let member_b = game.new_id("PL!N-bp1-009-R");
                        let non_member = game.new_id("PL!-sd1-019-SD");
                        game.state.revealed_cards.extend([member_a, non_member, member_b]);

                        fire_trigger(&mut game, live, AbilityTrigger::LiveSuccess, "ライブ成功時");
                        assert!(game.has_pending_choice());
                        assert_eq!(game.pending_choice_type().as_deref(), Some("SelectCard"));
                        let filtered = match game.state.get_pending_choice() {
                            Some(rabuka_engine::ability::types::Choice::SelectCard {
                                filtered_indices: Some(indices),
                                ..
                            }) => indices.clone(),
                            _ => panic!("expected filtered SelectCard choice"),
                        };
                        assert_eq!(filtered, vec![0, 2]);
                        game.select_indices(&[0]);

                        assert!(game.state.player1.hand.cards.contains(&member_a));
                        assert!(!game.state.player1.hand.cards.contains(&member_b));
                        assert!(game.state.revealed_cards.contains(&member_b));
                        assert!(game.state.revealed_cards.contains(&non_member));
                        assert_eq!(game.state.player2.success_live_card_zone.cards.len(), 2);
                    }

                    #[test]
                    fn pl_s_bp5_019_l_zero_or_one_success_card_does_not_retrieve() {
                        for success_count in 0..=1 {
                            let db = load_real_database();
                            let mut game = TestGame::new(db);
                            let filler = game.new_id(FILLER);
                            let live = game.id("PL!S-bp5-019-L");
                            let member = game.new_id("PL!N-sd1-006-P");
                            fill_decks(&mut game, filler);
                            game.add_to_hand(live);
                            game.set_live_card(live);
                            for _ in 0..success_count {
                                game.state
                                    .player1
                                    .success_live_card_zone
                                    .cards
                                    .push(game.new_id("PL!-sd1-019-SD"));
                            }
                            game.state.revealed_cards.push(member);

                            fire_trigger(&mut game, live, AbilityTrigger::LiveSuccess, "ライブ成功時");

                            assert!(!game.has_pending_choice(), "success_count={success_count}");
                            assert!(!game.state.player1.hand.cards.contains(&member));
                            assert!(game.state.revealed_cards.contains(&member));
                        }
                    }
                                }


