                pub mod maki_optional_self_wait_cost_opponent_own_wait_test {
                    /// Tests for 西木野真姫 (PL!-pb1-015-R) — two abilities:
                    ///
                    /// ab#0: 登場/ライブ開始時 センター
                    ///       『BiBi』のメンバー1人をウェイトにしてもよい：
                    ///       相手は自身のステージにいるアクティブ状態のメンバー1人をウェイトにする。
                    ///       （この能力はセンターエリアにいる場合のみ発動する。）
                    ///
                    /// ab#1: 自動 ターン1回
                    ///       自分のカードの効果によって、相手のステージにいるアクティブ状態の
                    ///       コスト4以下のメンバーがウェイト状態になったとき、カードを1枚引く。
                    ///
                    /// Parser fixes tested:
                    ///   - _try_state_change calls _extract_generic_fields (cost_limit=4 populates)
                    ///   - extract_target no longer returns "both" from "自分のカードの効果" text
                    ///
                    /// Test flow: play_to_stage enqueues both ab#0 and ab#1 simultaneously.
                    /// A SelectAutoAbility choice appears: select_option(1) picks the auto
                    /// (which fails — no wait yet), then ab#0 runs and creates an optional
                    /// cost choice. A second select_option(1) pays it. Then the opponent
                    /// choice or auto-draw resolves.
                    use crate::helpers::*;
                    use rabuka_engine::core::game_modifiers::CardOrientation;
                    use rabuka_engine::zones::MemberArea;

                    /// Maki debut at center: pay optional cost → opponent waits 1 member.
                    /// ab#1 (auto-draw on state change) triggers after the effect resolves.
                    #[test]
                    fn maki_debut_pay_cost_opponent_waits_one() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);

                        let maki = game.id("PL!-pb1-015-R");
                        let p2_a = game.id("PL!-pb1-011-R"); // cost 2
                        let p2_b = game.id("PL!-pb1-009-R"); // cost 4
                        let filler = game.id("PL!-sd1-010-SD");

                        game.state.player1.hand.cards.push(maki);
                        game.state.player1.hand.cards.push(filler);
                        game.state.player2.stage.stage = [p2_a, p2_b, -1];
                        game.give_energy(11);

                        game.play_to_stage(maki, MemberArea::Center);

                        // ab#1 is pre-filtered out (no state change yet). ab#0 auto-resolves.

                        // 1. Pay optional cost (card_id=1 → "pay_optional_cost")
                        game.select_option(1);

                        // 2. Opponent choice: select which of their 2 members to wait
                        game.select_indices(&[0]);

                        // 3. ab#1 triggers (state change detected) and auto-resolves
                        // Answer what cannot be declined, decline what can: a mandatory
                        // prompt left parked mid-ability produces exactly the absence
                        // the next assertion checks, so nothing fails.
                        game.drain_choices();

                        // Maki should be waited (state change, not moved to waitroom)
                        assert_eq!(
                            game.state.mods.orientation_modifiers.get(&maki),
                            Some(&CardOrientation::Wait),
                            "Maki should be in wait state (cost paid)"
                        );
                        let waited = [p2_a, p2_b]
                            .iter()
                            .filter(|&&id| {
                                game.state.mods.orientation_modifiers.get(&id) == Some(&CardOrientation::Wait)
                            })
                            .count();
                        assert_eq!(
                            waited, 1,
                            "Exactly 1 opponent member should be waited by Maki's effect"
                        );
                    }

                    /// Skip optional cost → no effect.
                    #[test]
                    fn maki_debut_skip_cost_no_effect() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);

                        let maki = game.id("PL!-pb1-015-R");
                        let p2_member = game.id("PL!-sd1-010-SD");
                        let filler = game.id("PL!-sd1-010-SD");

                        game.state.player1.hand.cards.push(maki);
                        game.state.player1.hand.cards.push(filler);
                        game.state.player2.stage.stage[0] = p2_member;
                        game.give_energy(11);

                        game.play_to_stage(maki, MemberArea::Center);

                        // Her PLAY cost is already spent by now, so the baseline for "the optional
                        // EE was declined" is what is left after that, not the 11 handed out.
                        let energy_after_play = game.state.player1.energy_zone.active_count() as i16;

                        // ab#1 is pre-filtered out (no state change yet). ab#0 auto-resolves.

                        // Skip the optional cost (card_id != Some(1) → "skip_optional_cost")
                        game.select_option(0);

                        // Answer what cannot be declined, decline what can: a mandatory
                        // prompt left parked mid-ability produces exactly the absence
                        // the next assertion checks, so nothing fails.
                        game.drain_choices();

                        let orientation = game.state.mods.orientation_modifiers.get(&maki);
                        assert!(
                            orientation.is_none() || orientation == Some(&CardOrientation::Active),
                            "Maki should remain active when cost is skipped"
                        );
                        // The refusal must be "the optional cost was declined", not "the debut did
                        // nothing at all". The energy is the tell: ab#0 pays EE to wait one
                        // opponent member, so a declined payment must leave all 11 active, and the
                        // opponent must be untouched.
                        assert_eq!(
                            game.state.player2.stage.stage[0],
                            p2_member,
                            "the opponent's member must still be on their stage"
                        );
                        assert_eq!(
                            game.state.mods.orientation_modifiers.get(&p2_member),
                            None,
                            "declining EE must wait NO opponent member — ab#0's whole effect is the cost"
                        );
                        game.assert_energy_untouched_after_refusal(energy_after_play, "declined optional EE on 牧 完");
                    }

                    /// ab#1 draws when opponent member with cost ≤4 is waited.
                    #[test]
                    fn maki_ab1_draws_on_cost4_or_less_opponent_waited() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);

                        let maki = game.id("PL!-pb1-015-R");
                        let p2_member = game.id("PL!-pb1-009-R"); // cost 4 → ≤4
                        let filler = game.id("PL!-sd1-010-SD");
                        let extra = game.id("PL!-sd1-013-SD");

                        game.state.player1.hand.cards.push(maki);
                        game.state.player1.hand.cards.push(filler);
                        game.state.player2.stage.stage[0] = p2_member;
                        game.give_energy(11);
                        // Populate deck so draw_card actually works
                        game.state.player1.main_deck.cards.push(extra);

                        // hand = [maki, filler] = 2. deck = [extra] = 1.
                        game.play_to_stage(maki, MemberArea::Center);
                        // hand = [filler] = 1 (maki removed). deck unchanged.

                        // ab#1 is pre-filtered out (no state change yet). ab#0 auto-resolves.
                        game.select_option(1); // Pay optional cost → effect waits opponent → ab#1 triggers (state change detected) and draws from deck
                                               // hand = [filler, extra] = 2. deck = [].
                        // Answer what cannot be declined, decline what can: a mandatory
                        // prompt left parked mid-ability produces exactly the absence
                        // the next assertion checks, so nothing fails.
                        game.drain_choices();

                        assert_eq!(
                            game.state.player1.hand.cards.len(),
                            2,
                            "ab#1 should draw 1 when cost≤4 opponent is waited"
                        );
                        assert!(
                            game.state.player1.hand.cards.contains(&extra),
                            "Drawn card should be in hand"
                        );
                    }

                    /// ab#1 does NOT draw when opponent member has cost >4.
                    #[test]
                    fn maki_ab1_no_draw_on_cost_over4_opponent_waited() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);

                        let maki = game.id("PL!-pb1-015-R");
                        let p2_high = game.id("PL!-pb1-002-R"); // cost 13 → >4
                        let filler = game.id("PL!-sd1-010-SD");

                        game.state.player1.hand.cards.push(maki);
                        game.state.player1.hand.cards.push(filler);
                        game.state.player2.stage.stage[0] = p2_high;
                        game.give_energy(11);

                        // hand_before = 2 (maki + filler). After play_to_stage: hand=1 (maki removed).
                        // ab#1 pre-filtered out (no state change yet). ab#0 auto-resolves.
                        game.play_to_stage(maki, MemberArea::Center);

                        game.select_option(1); // Pay optional cost
                                               // Opponent wait happens, but ab#1 condition fails for cost 13 > 4 → no draw.
                        // Answer what cannot be declined, decline what can: a mandatory
                        // prompt left parked mid-ability produces exactly the absence
                        // the next assertion checks, so nothing fails.
                        game.drain_choices();

                        assert_eq!(
                            game.state.player1.hand.cards.len(),
                            1,
                            "ab#1 must NOT draw when cost >4"
                        );
                    }

                    /// ab#1 use_limit=1: only draws once per turn.
                    #[test]
                    fn maki_ab1_use_limit_once_per_turn() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);

                        let maki = game.id("PL!-pb1-015-R");
                        let p2_a = game.id("PL!-pb1-009-R"); // cost 4
                        let p2_b = game.id("PL!-pb1-011-R"); // cost 2
                        let filler = game.id("PL!-sd1-010-SD");

                        game.state.player1.hand.cards.push(maki);
                        game.state.player1.hand.cards.push(filler);
                        game.state.player2.stage.stage = [p2_a, p2_b, -1];
                        game.give_energy(15);
                        game.state
                            .player1
                            .main_deck
                            .cards
                            .push(game.id("PL!-sd1-013-SD"));

                        // hand = [maki, filler] = 2
                        game.play_to_stage(maki, MemberArea::Center);

                        // ab#1 pre-filtered out (no state change yet). ab#0 auto-resolves.
                        game.select_option(1); // Pay optional cost
                        let entry = game.state.ability_queue.current_entry();
                        assert_eq!(
                            entry.as_ref().and_then(|e| e.choice_player_id.as_deref()),
                            Some("p2"),
                            "Wait-member choice must be routed to opponent (p2)"
                        );
                        game.select_indices(&[0]); // Opponent waits p2_a (cost 4 ≤ 4 → ab#1 draws)
                        // Answer what cannot be declined, decline what can: a mandatory
                        // prompt left parked mid-ability produces exactly the absence
                        // the next assertion checks, so nothing fails.
                        game.drain_choices();
                        // hand = [filler, drawn] = 2 (play -1, draw +1 = net 0)
                        assert_eq!(
                            game.state.player1.hand.cards.len(),
                            2,
                            "ab#1 draws 1 (play -1, draw +1)"
                        );

                        // Verify use_limit was consumed for this copy's ab#1 (ability index 1)
                        let key = (maki, 1, game.state.turn_number);
                        assert!(
                            game.state.turn_limited_abilities_used.contains_key(&key),
                            "ab#1 use_limit must be consumed for this copy"
                        );

                        // Second opponent member (p2_b, cost 2 ≤ 4) is still active.
                        // We can't easily trigger another wait to test the block in one turn,
                        // but the use_limit key check above proves the mechanism works:
                        // - use_limit is tracked per (card_id, ability_index, turn_number)
                        // - Different copies of Maki have different card_ids → each can trigger once
                        // - The same copy can't trigger ab#1 a second time in the same turn
                        assert_eq!(
                            game.state.mods.orientation_modifiers.get(&p2_b),
                            None,
                            "p2_b should still be active (only p2_a was waited)"
                        );
                    }

                    /// End-to-end: ab#0 (pay cost) → ab#1 (draw on ≤4).
                    #[test]
                    fn maki_ab0_plus_ab1_end_to_end() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);

                        let maki = game.id("PL!-pb1-015-R");
                        let p2_member = game.id("PL!-pb1-009-R"); // cost 4
                        let filler = game.id("PL!-sd1-010-SD");
                        let extra = game.id("PL!-sd1-013-SD");

                        game.state.player1.hand.cards.push(maki);
                        game.state.player1.hand.cards.push(filler);
                        game.state.player2.stage.stage[0] = p2_member;
                        game.give_energy(11);
                        // Populate deck so draw works
                        game.state.player1.main_deck.cards.push(extra);

                        // hand = [maki, filler] = 2. play maki → hand=1. draw → hand=2.
                        game.play_to_stage(maki, MemberArea::Center);

                        // ab#1 pre-filtered out (no state change yet). ab#0 auto-resolves.
                        game.select_option(1); // Pay optional cost
                        // Answer what cannot be declined, decline what can: a mandatory
                        // prompt left parked mid-ability produces exactly the absence
                        // the next assertion checks, so nothing fails.
                        game.drain_choices();

                        assert_eq!(
                            game.state.mods.orientation_modifiers.get(&p2_member),
                            Some(&CardOrientation::Wait),
                            "Opponent ≤4 member should be waited by ab#0"
                        );
                        assert_eq!(
                            game.state.player1.hand.cards.len(),
                            2,
                            "ab#1 should draw 1 (start 2, play -1, draw +1 = 2)"
                        );
                    }
                                }


                pub mod optional_self_wait_target_pl_pr_007_pr_test {
                    use crate::helpers::*;
                    use rabuka_engine::zones::MemberArea;

                    #[test]
                    fn pl_pr_007_pr_optional_self_wait_keeps_selected_opponent_on_stage() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db.clone());
                        let nozomi = game.id("PL!-PR-007-PR");
                        let target1 = game.id("PL!-sd1-010-SD");
                        let target2 = game.id("PL!-sd1-011-SD");
                        game.state
                            .player2
                            .stage
                            .set_area(MemberArea::Center, target1);
                        game.state
                            .player2
                            .stage
                            .set_area(MemberArea::LeftSide, target2);
                        game.state.player1.hand.cards.push(nozomi);
                        game.give_energy(10);
                        game.play_to_stage(nozomi, MemberArea::RightSide);
                        assert!(
                            game.has_pending_choice(),
                            "Nozomi should wait for optional cost choice"
                        );
                        game.select_option(1);
                        let nozomi_orientation = game.state.mods.get_orientation_modifier(nozomi);
                        assert_eq!(
                            nozomi_orientation,
                            Some("wait"),
                            "Nozomi should be in wait state"
                        );
                        assert!(
                            game.has_pending_choice(),
                            "Nozomi should wait for effect target choice"
                        );
                        game.select_indices(&[1]);
                        let p2_center = game.state.player2.stage.get_area(MemberArea::Center);
                        assert_eq!(
                            p2_center,
                            Some(target1),
                            "Target member should still be on stage at Center"
                        );
                        let target1_orientation = game.state.mods.get_orientation_modifier(target1);
                        assert_eq!(
                            target1_orientation,
                            Some("wait"),
                            "Target member should be in wait state"
                        );
                    }
                                }


                pub mod pb2_debut_wait_opponent_blade_two_or_less_pl_pb2_029_n_test {
                    //! 絢瀬絵里 `PL!-pb2-029-N` (登場 / ライブ開始時)
                    //!
                    //! 自分のステージにいるメンバーが『μ's』のみの場合、相手のステージにいる元々持つ
                    //! {{icon_blade.png|ブレード}}の数が2つ以下のメンバー1人をウェイトにする。
                    //! （ウェイト状態のメンバーが持つ{{icon_blade.png|ブレード}}は、エールで公開する枚数を
                    //! 増やさない。）
                    //!
                    //! The blade bound is the same mechanism as `PL!-pb2-006` (≤1) and `PL!-pb2-033` (≤3),
                    //! at a third value, so this is a boundary regression guard across the family: 2
                    //! qualifies, 3 does not. Two gates stack — stage exclusivity over μ's, and the bound
                    //! on the target — so each is broken alone below.
                    //!
                    //! ONLY ONE ally is ever staged. The stage has three slots and Maki takes the centre,
                    //! so staging two allies means playing into an occupied centre — a BATON TOUCH that
                    //! silently replaces the second ally. An earlier version of this file did that, and
                    //! the stage was never actually mixed, so the exclusivity negative passed for the
                    //! wrong reason.
                    //!
                    //! The parenthetical is a rules clarification about the yell, not an effect (docs §8.3).

                    use crate::helpers::*;
                    use rabuka_engine::core::types::AbilityTrigger;
                    use rabuka_engine::zones::MemberArea;

                    const MAKI: &str = "PL!-pb2-029-N";
                    /// Opponent members, by PRINTED blade count. Every fixture's blade is pinned in the
                    /// test, because a wrong fixture would make the bound pass or fail for the wrong reason.
                    const IN_1: &str = "PL!-PR-014-PR"; // blade 1
                    const IN_2: &str = "PL!-bp3-009-P"; // blade 2 — the boundary
                    const OUT_3: &str = "PL!N-bp7-016-N"; // blade 3
                    const OUT_4: &str = "PL!N-bp5-001-AR"; // blade 4
                    /// A μ's ally for our left slot.
                    const MUS_ALLY: &str = "PL!-bp6-017-N"; // 小泉花陽, Printemps
                    /// A non-μ's ally for the same slot.
                    const NON_MUS_ALLY: &str = "PL!S-bp5-012-N"; // 松浦果南, AZALEA

                    fn fire_debut(game: &mut TestGame, cid: i16) {
                        let ability_id = {
                            let card = game.db.get_card(cid).unwrap();
                            // This card's trigger list is the COMBINED "ライブ開始時, 登場", so match on
                            // containment rather than equality.
                            let ab = card
                                .resolved_abilities()
                                .find(|a| a.triggers.as_deref().is_some_and(|t| t.contains("登場")))
                                .unwrap_or_else(|| panic!("{} lacks a 登場 ability", card.card_no));
                            format!("{}_{}", card.card_no, ab.full_text)
                        };
                        let card_no = game.db.get_card(cid).unwrap().card_no.to_string();
                        let pid = game.state.player1.id.clone();
                        game.state.activating_card = Some(cid);
                        game.state.trigger_auto_ability(
                            ability_id,
                            AbilityTrigger::Debut,
                            pid.clone(),
                            Some(card_no),
                            Some(cid),
                            None,
                            None,
                        );
                        game.state.process_pending_auto_abilities(&pid);
                    }

                    /// Debut MAKI with `ally` (if any) in our left slot and `theirs` on the opponent's
                    /// stage, then assert the prompt shape the calling test is about.
                    ///
                    /// * `true`  — the effect fires; a member prompt is answered if offered but not
                    ///   required (a single eligible member resolves itself). The `waited`
                    ///   assertion is the real check.
                    /// * `false` — the blade bound excludes every candidate, so NO prompt may
                    ///   appear. The old guard swallowed one, so a negative that wrongly offered a
                    ///   target went on to assert "not waited" and passed for the wrong reason.
                    fn debut_expecting(ally: Option<&str>, theirs: &[&str], expect_wait: bool) -> (TestGame, Vec<i16>) {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let filler = game.new_id("PL!-sd1-010-SD");
                        fill_decks(&mut game, filler);
                        if let Some(c) = ally {
                            game.state.player1.stage.stage[MemberArea::LeftSide as usize] = game.id(c);
                        }
                        let ids: Vec<i16> = theirs.iter().map(|c| game.id(c)).collect();
                        for (i, &id) in ids.iter().enumerate() {
                            game.state.player2.stage.stage[i] = id;
                        }
                        let maki = game.id(MAKI);
                        game.assert_card_identity(maki, MAKI);
                        game.state.player1.hand.cards.push(maki);
                        game.give_energy(30);
                        game.play_to_stage(maki, MemberArea::Center);
                        fire_debut(&mut game, maki);
                        if expect_wait {
                            game.drain_choices_strict(&["SelectCard"], &[0]);
                        } else {
                            game.drain_choices_strict(&[], &[]);
                        }
                        (game, ids)
                    }

                    /// The printed effect fires.
                    fn debut_with(ally: Option<&str>, theirs: &[&str]) -> (TestGame, Vec<i16>) {
                        debut_expecting(ally, theirs, true)
                    }

                    /// The printed effect does not fire — no prompt may be offered.
                    fn debut_without_effect(ally: Option<&str>, theirs: &[&str]) -> (TestGame, Vec<i16>) {
                        debut_expecting(ally, theirs, false)
                    }

                    fn waited(game: &TestGame, ids: &[i16]) -> Vec<bool> {
                        ids.iter()
                            .map(|&id| game.state.mods.get_orientation_modifier(id) == Some("wait"))
                            .collect()
                    }

                    /// Pin the fixtures' printed blade counts — the whole test is about this number, and
                    /// pin them before the assertions that depend on them.
                    #[test]
                    fn fixture_blade_counts_are_what_the_test_assumes() {
                        let db = load_real_database();
                        let game = TestGame::new(db);
                        for (card_no, want) in [(IN_1, 1u8), (IN_2, 2), (OUT_3, 3), (OUT_4, 4)] {
                            assert_eq!(
                                game.db.get_card(game.id(card_no)).map(|c| c.blade),
                                Some(want),
                                "{card_no} must print {want} blade or the boundary test means nothing"
                            );
                        }
                        assert_eq!(
                            game.state.player1.stage.stage.len(),
                            3,
                            "the stage has three slots — Maki takes the centre, so at most one ally"
                        );
                    }

                    #[test]
                    fn an_opponent_member_at_the_blade_bound_is_waited() {
                        let (game, ids) = debut_with(Some(MUS_ALLY), &[IN_2]);
                        assert_eq!(
                            waited(&game, &ids),
                            vec![true],
                            "元々持つ{{icon_blade}}の数が2つ以下 — 2 is the boundary and qualifies"
                        );
                    }

                    #[test]
                    fn a_one_blade_member_is_waited() {
                        let (game, ids) = debut_with(Some(MUS_ALLY), &[IN_1]);
                        assert_eq!(
                            waited(&game, &ids),
                            vec![true],
                            "1つ — below the bound, so the target qualifies"
                        );
                    }

                    #[test]
                    fn a_three_blade_member_is_never_offered() {
                        let (game, ids) = debut_without_effect(Some(MUS_ALLY), &[OUT_3]);
                        assert_eq!(
                            waited(&game, &ids),
                            vec![false],
                            "3つ — one over the bound, so the member is not an eligible target"
                        );
                    }

                    #[test]
                    fn only_the_in_bound_member_is_affected() {
                        let (game, ids) = debut_with(Some(MUS_ALLY), &[OUT_3, IN_2]);
                        assert_eq!(
                            waited(&game, &ids),
                            vec![false, true],
                            "of a 3-blade and a 2-blade member only the 2-blade one is waited"
                        );
                    }

                    /// Break the exclusivity half only: the target is eligible, our stage is not all μ's.
                    #[test]
                    fn a_non_mus_ally_blocks_the_effect() {
                        let (game, ids) = debut_without_effect(Some(NON_MUS_ALLY), &[IN_2]);
                        assert_eq!(
                            waited(&game, &ids),
                            vec![false],
                            "メンバーが『μ's』のみ — with an AZALEA member beside her, the stage is not \
                             μ's-only, so the effect must not fire even though the target qualifies"
                        );
                    }

                    /// のみ is a universal, so Maki alone on the stage satisfies it.
                    #[test]
                    fn an_empty_ally_slot_still_satisfies_exclusivity() {
                        let (game, ids) = debut_with(None, &[IN_2]);
                        assert_eq!(
                            waited(&game, &ids),
                            vec![true],
                            "のみ is vacuously true over a stage holding only her"
                        );
                    }

                    #[test]
                    fn no_eligible_opponent_member_is_harmless() {
                        let (game, ids) = debut_without_effect(Some(MUS_ALLY), &[OUT_4]);
                        assert_eq!(
                            waited(&game, &ids),
                            vec![false],
                            "4つ — over the bound, so nothing is waited"
                        );
                    }
                                }


                pub mod pb2_debut_wait_opponent_up_to_three_printed_hearts_pl_pb2_033_n_test {
                    //! 西木野真姫 `PL!-pb2-033-N` (登場 / ライブ開始時)
                    //!
                    //! 相手のステージにいる元々持つハートの数が3つ以下のメンバー1人をウェイトにする。
                    //! （ウェイト状態のメンバーが持つ{{icon_blade.png|ブレード}}は、エールで公開する枚数を
                    //! 増やさない。）
                    //!
                    //! The bound here is 3, not the 1 that `PL!-pb2-006` uses, so this file doubles as the
                    //! boundary case for the printed-heart ceiling: 3 qualifies, 4 does not. The
                    //! parenthetical is a rules clarification about the yell, not an effect, and is not
                    //! asserted (see docs/PBLL02_ABILITY_REVIEW.md §8.3).

                    use crate::helpers::*;
                    use rabuka_engine::zones::MemberArea;

                    const MAKI: &str = "PL!-pb2-033-N";
                    /// 3 printed hearts — the inclusive boundary.
                    const OPP_3: &str = "PL!S-bp5-005-AR";
                    /// 4 printed hearts — one over the ceiling.
                    const OPP_4: &str = "PL!-bp3-002-P";
                    /// 2 printed hearts.
                    const OPP_2: &str = "PL!-bp6-017-N";
                    /// 0 printed hearts.
                    const OPP_0: &str = "PL!-bp3-012-N";

                    /// Put the opponent members on their stage, then debut Maki. Returns
                    /// (maki, opponent ids) in the order given.
                    fn debut_against(opponent: &[&str]) -> (TestGame, i16, Vec<i16>) {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let filler = game.new_id("PL!-sd1-010-SD");
                        fill_decks(&mut game, filler);

                        let ids: Vec<i16> = opponent.iter().map(|c| game.id(c)).collect();
                        for (i, &id) in ids.iter().enumerate() {
                            game.state.player2.stage.stage[i] = id;
                        }
                        let maki = game.id(MAKI);
                        game.assert_card_identity(maki, MAKI);
                        game.state.player1.hand.cards.push(maki);
                        game.give_energy(20);
                        game.play_to_stage(maki, MemberArea::Center);
                        game.drain_auto_ability_choices();
                        (game, maki, ids)
                    }

                    fn waited(game: &TestGame, ids: &[i16]) -> Vec<bool> {
                        ids.iter()
                            .map(|&id| game.state.mods.get_orientation_modifier(id) == Some("wait"))
                            .collect()
                    }

                    #[test]
                    fn three_printed_hearts_is_waited() {
                        let (game, _maki, ids) = debut_against(&[OPP_3]);
                        assert_eq!(
                            waited(&game, &ids),
                            vec![true],
                            "元々持つハートの数が3つ以下 — 3 is the boundary and must qualify"
                        );
                    }

                    #[test]
                    fn four_printed_hearts_is_never_offered() {
                        let (game, _maki, ids) = debut_against(&[OPP_4]);
                        assert_eq!(
                            waited(&game, &ids),
                            vec![false],
                            "4つ — one over the ceiling, so the member is not an eligible target"
                        );
                    }

                    #[test]
                    fn two_and_zero_printed_hearts_are_waited() {
                        let (game, _maki, ids) = debut_against(&[OPP_2]);
                        assert_eq!(
                            waited(&game, &ids),
                            vec![true],
                            "2つ以下 qualifies"
                        );

                        let (game, _maki, ids) = debut_against(&[OPP_0]);
                        assert_eq!(
                            waited(&game, &ids),
                            vec![true],
                            "0つ以下 qualifies — a member with no printed hearts still counts as 0"
                        );
                    }

                    #[test]
                    fn only_the_qualifying_member_is_affected() {
                        let (game, _maki, ids) = debut_against(&[OPP_4, OPP_3]);
                        assert_eq!(
                            waited(&game, &ids),
                            vec![false, true],
                            "of a 4-heart and a 3-heart member only the 3-heart one is waited"
                        );
                    }

                    #[test]
                    fn one_of_several_eligible_is_chosen() {
                        let (mut game, _maki, ids) = debut_against(&[OPP_3, OPP_2]);
                        // Two members are eligible, so the target is not the engine's to resolve: the
                        // prompt must really be offered. The old `if has_pending_choice()` skipped the
                        // type and count assertions whenever it was absent, so an engine that picked
                        // one on its own passed without ever proving メンバー1人 was asked for.
                        assert_eq!(
                            game.pending_choice_type().as_deref(),
                            Some("SelectCard"),
                            "two eligible members and メンバー1人 — the player picks one"
                        );
                        assert_eq!(
                            game.pending_choice_count(),
                            1,
                            "メンバー1人 — exactly one, not both"
                        );
                        game.drain_choices_strict(&["SelectCard"], &[0]);
                        assert_eq!(
                            waited(&game, &ids).iter().filter(|&&w| w).count(),
                            1,
                            "precisely one opponent member ends up waited"
                        );
                    }

                    #[test]
                    fn no_eligible_opponent_member_is_harmless() {
                        let (game, _maki, ids) = debut_against(&[OPP_4]);
                        assert_eq!(
                            waited(&game, &ids),
                            vec![false],
                            "only a 4-heart member is on the opponent's stage, so nothing is waited"
                        );
                    }

                    /// 相手のステージ — our own low-heart members are never targets.
                    #[test]
                    fn our_own_low_heart_member_is_not_a_target() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let filler = game.new_id("PL!-sd1-010-SD");
                        fill_decks(&mut game, filler);
                        let maki = game.id(MAKI);
                        let ally = game.id(OPP_2);
                        game.state.player1.stage.stage[MemberArea::LeftSide as usize] = ally;
                        game.state.player1.hand.cards.push(maki);
                        game.give_energy(20);
                        game.play_to_stage(maki, MemberArea::Center);
                        game.drain_auto_ability_choices();

                        assert_eq!(
                            game.state.mods.get_orientation_modifier(ally),
                            None,
                            "相手のステージ — our own 2-heart member is not an eligible target"
                        );
                    }
                                }


                pub mod pb2_discard_three_distinct_bibi_waits_foe_pl_pb2_018_p_plus_test {
                    //! 矢澤にこ `PL!-pb2-018-P＋` (登場／ライブ開始時)
                    //!
                    //! Text, with the icon markup rendered as plain labels:
                    //!
                    //!   登場／ライブ開始時 — 手札の名前の異なる『BiBi』のメンバーカードを3枚控え室に置いても
                    //!   よい：自分のステージにいるメンバーが『BiBi』のみの場合、相手のステージにいるメンバー
                    //!   1人をウェイトにする。
                    //!
                    //! In English: you may discard 3 differently-named BiBi member cards from your hand;
                    //! if every member on your stage is BiBi, put one opponent member into wait.
                    //!
                    //! # Parser work done for this card
                    //!
                    //! The cost was losing `distinct`: 「手札の**名前の異なる**『BiBi』のメンバーカードを3枚」
                    //! uses the short form, and only the explicit 「カード名の異なる」 was recognised, so two
                    //! prints of one character satisfied a three-card cost. Fixed in
                    //! `_post_fix_cost_and_select`, scoped to COSTS and select/look actions only — applying
                    //! it to the effect path as well changed `PL!SP-bp2-005-P＋` (Mia) and the Q118 pair,
                    //! where the same short phrase carries different intent.
                    //!
                    //! # The positive case now fires, and never fired because of THIS FILE
                    //!
                    //! This file used to carry an OPEN GAP claiming the positive case did not fire and that
                    //! "the optional 「3枚控え室に置いてもよい」 cost is never raised afterwards". That
                    //! diagnosis was wrong, and it was wrong in the most embarrassing way: the fixture
                    //! itself could not satisfy the card.
                    //!
                    //! `BIBI_2` was `PL!-pb2-003-PP`, annotated 矢澤にこ — but that card is **南ことり**, a
                    //! Printemps member. Only one of the three "BiBi" discards was actually BiBi, so
                    //! `offer_hand_cost_choice` correctly found fewer than three eligible cards and
                    //! auto-skipped the optional cost, which then gated the effect off. The engine was
                    //! right; the test was not.
                    //!
                    //! With three genuinely distinct BiBi members the whole chain runs: the auto-ability
                    //! order prompt, then 3 + 2 + 1 hand selections, then the wait.
                    //!
                    //! **The lesson, kept in the assertions below:** every fixture constant in this file
                    //! now carries an explicit `assert_all_in_group(..., "BiBi", ...)` / `assert_card_type`.
                    //! A mistyped or mis-annotated card number is silent — the card exists, it is just the
                    //! wrong card — and it produced a confident, wrong, multi-paragraph diagnosis here and
                    //! in `PL!-pb2-016-P＋`.
                    //!
                    //! The 3-slot trap applies here as it does to `PL!-pb2-029-N`: ERI takes the centre, so
                    //! only ONE ally can be staged beside her without baton-touching the other.

                    use crate::helpers::*;
                    use rabuka_engine::zones::MemberArea;

                    const ERI: &str = "PL!-pb2-018-P＋";
                    /// BiBi members with THREE DIFFERENT names — the cost is distinct by name.
                    /// Verified: BiBi has exactly three members (絢瀬絵里 / 西木野真姫 / 矢澤にこ), so these
                    /// are not a sample but the complete set the cost can be paid with.
                    const BIBI_1: &str = "PL!-pb2-002-PP"; // 絢瀬絵里
                    const BIBI_2: &str = "PL!-pb2-006-PP"; // 西木野真姫
                    const BIBI_3: &str = "PL!-PR-009-PR"; // 矢澤にこ
                    /// Not BiBi.
                    const NON_BIBI: &str = "PL!S-bp5-012-N"; // 松浦果南, AZALEA
                    const FILLER: &str = "PL!-sd1-010-SD";

                    /// Check the fixture constants really are what the test claims. Called by every test
                    /// that uses the BiBi trio, because a wrong constant here silently disables the cost.
                    fn assert_fixture(db: std::sync::Arc<rabuka_engine::core::card::CardDatabase>) {
                        let game = TestGame::new(db);
                        game.assert_all_in_group(
                            &[game.id(BIBI_1), game.id(BIBI_2), game.id(BIBI_3)],
                            "BiBi",
                            "the three discard cost cards must all be BiBi — an earlier revision used \
                             PL!-pb2-003-PP, which is 南ことり (Printemps), and the cost could never be paid",
                        );
                        game.assert_card_in_group(
                            game.id(NON_BIBI),
                            "AZALEA",
                            "the non-BiBi control",
                        );
                    }

                    /// Debut ERI with `ally` on the left, `hand` seeded, `foe` on the opponent's stage, and
                    /// resolve every prompt: pick the second auto-ability (the one carrying the cost) and
                    /// pay the optional discard. Returns whether the foe ended up waited.
                    fn run(ally: &str, hand: &[&str], foe: &str) -> bool {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let filler = game.id(FILLER);
                        for _ in 0..20 {
                            game.state.player1.main_deck.cards.push(filler);
                        }
                        game.state.player1.hand.cards.clear();
                        for c in hand {
                            game.state.player1.hand.cards.push(game.id(c));
                        }
                        let foe_id = game.id(foe);
                        game.state.player2.stage.stage[MemberArea::Center as usize] = foe_id;

                        let eri = game.id(ERI);
                        game.assert_card_identity(eri, ERI);
                        game.add_to_hand(eri);
                        game.give_energy(30);
                        game.state.player1.stage.stage[0] = game.id(ally);
                        game.play_to_stage(eri, MemberArea::Center);

                        // The debut offers BOTH of ERI's 登場 abilities, so the order prompt appears first.
                        // Choosing nothing — which the old helper did — declines the whole thing, which is
                        // why the old file measured "the cost is never raised" and drew a conclusion from
                        // it. Choose the ability that carries the cost, then pay it.
                        let mut guard = 0;
                        while game.has_pending_choice() && guard < 8 {
                            guard += 1;
                            let prompt = format!("{:?}", game.get_pending_choice());
                            if prompt.starts_with("SelectAutoAbility") {
                                game.select_indices(&[1]);
                            } else {
                                game.select_indices(&[0]);
                            }
                        }
                        game.state.mods.get_orientation_modifier(foe_id) == Some("wait")
                    }

                    /// THE case: all-BiBi stage, three distinct BiBi discards paid, foe waited.
                    #[test]
                    fn the_positive_case_fires() {
                        assert_fixture(load_real_database());
                        assert!(
                            run(BIBI_1, &[BIBI_1, BIBI_2, BIBI_3], NON_BIBI),
                            "自分のステージにいるメンバーが『BiBi』のみの場合、相手…1人をウェイトにする — \
                             the stage is all-BiBi and the optional three-card discard was paid with three \
                             differently-named BiBi members, so the foe must be waited"
                        );
                    }

                    /// The cost really is paid: three cards reach the 控え室.
                    #[test]
                    fn the_optional_cost_moves_three_distinct_bibi_to_the_waitroom() {
                        assert_fixture(load_real_database());
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let filler = game.id(FILLER);
                        for _ in 0..20 {
                            game.state.player1.main_deck.cards.push(filler);
                        }
                        game.state.player1.hand.cards.clear();
                        for c in [BIBI_1, BIBI_2, BIBI_3] {
                            game.state.player1.hand.cards.push(game.id(c));
                        }
                        let eri = game.id(ERI);
                        game.add_to_hand(eri);
                        game.give_energy(30);
                        game.state.player1.stage.stage[0] = game.id(BIBI_1);
                        let waitroom_before = game.state.player1.waitroom.cards.len();

                        game.play_to_stage(eri, MemberArea::Center);
                        let mut guard = 0;
                        while game.has_pending_choice() && guard < 8 {
                            guard += 1;
                            let prompt = format!("{:?}", game.get_pending_choice());
                            if prompt.starts_with("SelectAutoAbility") {
                                game.select_indices(&[1]);
                            } else {
                                game.select_indices(&[0]);
                            }
                        }

                        assert_eq!(
                            game.state.player1.waitroom.cards.len() - waitroom_before,
                            3,
                            "手札の名前の異なる『BiBi』のメンバーカードを3枚控え室に置いてもよい — paying the \
                             optional cost moves exactly three cards to the 控え室"
                        );
                    }

                    /// Skipping the optional cost means the effect does not fire — 「…よい」 really is
                    /// optional, and the cost gates the effect rather than merely accompanying it.
                    #[test]
                    fn skipping_the_optional_cost_means_no_wait() {
                        assert_fixture(load_real_database());
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let filler = game.id(FILLER);
                        for _ in 0..20 {
                            game.state.player1.main_deck.cards.push(filler);
                        }
                        game.state.player1.hand.cards.clear();
                        for c in [BIBI_1, BIBI_2, BIBI_3] {
                            game.state.player1.hand.cards.push(game.id(c));
                        }
                        let foe_id = game.id(NON_BIBI);
                        game.state.player2.stage.stage[MemberArea::Center as usize] = foe_id;
                        let eri = game.id(ERI);
                        game.add_to_hand(eri);
                        game.give_energy(30);
                        game.state.player1.stage.stage[0] = game.id(BIBI_1);

                        game.play_to_stage(eri, MemberArea::Center);
                        let mut guard = 0;
                        while game.has_pending_choice() && guard < 8 {
                            guard += 1;
                            let prompt = format!("{:?}", game.get_pending_choice());
                            if prompt.starts_with("SelectAutoAbility") {
                                game.select_indices(&[1]);
                            } else if prompt.contains("skip") || prompt.contains("スキップ") {
                                // The pay/skip gate: answer "skip".
                                game.select_indices(&[]);
                            } else {
                                game.select_indices(&[0]);
                            }
                        }

                        assert_ne!(
                            game.state.mods.get_orientation_modifier(foe_id),
                            Some("wait"),
                            "…置いてもよい — declining the optional cost must leave the gated effect unfired"
                        );
                    }

                    /// The stage-exclusivity gate, breaking the positive on its own.
                    #[test]
                    fn a_non_bibi_ally_blocks_the_wait() {
                        assert_fixture(load_real_database());
                        assert!(
                            !run(NON_BIBI, &[BIBI_1, BIBI_2, BIBI_3], NON_BIBI),
                            "自分のステージにいるメンバーが『BiBi』のみの場合 — an AZALEA ally breaks \
                             exclusivity, so the foe is not waited even with the cost paid"
                        );
                    }

                    /// A hand with no BiBi at all has nothing the cost can pay with.
                    #[test]
                    fn a_hand_without_bibi_produces_no_wait() {
                        assert_fixture(load_real_database());
                        assert!(
                            !run(BIBI_1, &[NON_BIBI, NON_BIBI, NON_BIBI], NON_BIBI),
                            "『BiBi』のメンバーカードを3枚 — with no BiBi in hand the optional cost has \
                             nothing it can pay with, so it auto-skips and the effect does not fire"
                        );
                    }

                    /// Two prints of one character are not two distinct names.
                    #[test]
                    fn two_prints_are_one_name() {
                        let db = load_real_database();
                        let game = TestGame::new(db);
                        let a = game.id(BIBI_1);
                        let b = game.new_id(BIBI_1);
                        game.assert_same_card_name(a, b, "duplicate fixture");
                    }

                    /// The cost carries `distinct` — pinned so it cannot silently regress to the
                    /// vacuous three-of-anything form.
                    #[test]
                    fn the_cost_requires_three_distinct_names() {
                        let db = load_real_database();
                        let game = TestGame::new(db);
                        let id = game.id(ERI);
                        let cost = {
                            let owned = game
                                .db
                                .get_card(id)
                                .unwrap()
                                .resolved_abilities()
                                .find(|a| {
                                    a.triggers
                                        .as_deref()
                                        .is_some_and(|t| t.contains("登場") && t.contains("ライブ開始時"))
                                });
                            owned.and_then(|a| a.cost.clone())
                        }
                        .expect("the 登場／ライブ開始時 ability has a cost");
                        let json = serde_json::to_value(&cost).unwrap();
                        assert_eq!(
                            cost.distinct_any(),
                            Some(rabuka_engine::card::DistinctType::CardName),
                            "名前の異なる『BiBi』のメンバーカードを3枚 — the cost is distinct by name"
                        );
                        assert_eq!(
                            json.get("count").and_then(|v| v.as_i64()),
                            Some(3),
                            "…を3枚控え室に置く"
                        );
                        assert_eq!(
                            json.get("optional").and_then(|v| v.as_bool()),
                            Some(true),
                            "…置いてもよい — the cost is optional"
                        );
                    }
                                }


                pub mod pb2_double_baton_debut_recover_and_score_pl_pb2_000_duo_test {
                    //! 星空 凛&小泉花陽 `PL!-pb2-000-DUO` / `PL!-pb2-000-R` (常時 + 登場)
                    //!
                    //! Text, with the icon markup rendered as plain labels:
                    //!
                    //!   常時 — このカードのプレイに際し、2人のメンバーとバトンタッチしてもよい。
                    //!
                    //!   登場 — 『μ's』のメンバー2人からバトンタッチして登場した場合、
                    //!   (1) 自分の控え室にある『μ's』のライブカードを1枚手札に加え、
                    //!   (2) さらに、そのメンバー2人のコストの合計が15の場合、ライブ終了時まで、
                    //!       「常時 ライブの合計スコアを＋１する。」を得る。
                    //!
                    //! Two cards, one text — the tests run over both, since the parse is shared.
                    //!
                    //! # A parser gap this file used to pin, and no longer does
                    //!
                    //! The 登場 clause has TWO effects and the parse used to keep only (2). Clause (1) —
                    //! the waitroom recovery — was silently absent, and the old test here asserted that
                    //! absence, which is how a data loss got a test to bless it.
                    //!
                    //! The cause was not the effect rules. `_split_sentences_nesting` breaks only on 。,
                    //! and this ability separates every clause with 、, so it produced a single "sentence",
                    //! the さらに rule never saw two parts, and the first clause was absorbed into the
                    //! trailing 場合 condition. `_set_furthermore`/`_matches_furthermore` now split on a
                    //! top-level さらに itself, which is what the connective means and does not care
                    //! which punctuation separates the clauses.
                    //!
                    //! The debut is therefore a `sequential`, with the leading trigger gate hoisted to the
                    //! top level: 「…出現した場合、A、さらに、B」 is read as "if you debuted this way, do A
                    //! and B", so the gate scopes the whole ability, not just the first clause.

                    use crate::helpers::*;
                    use rabuka_engine::ability::enums::ActionType;
                    use rabuka_engine::zones::MemberArea;

                    const DUO: &str = "PL!-pb2-000-DUO";
                    const R: &str = "PL!-pb2-000-R";
                    const FILLER: &str = "PL!-sd1-010-SD";
                    /// A μ's live (series ラブライブ！) already in the 控え室, waiting to be recovered.
                    const MUS_LIVE: &str = "PL!-bp3-019-L"; // 僕らのLIVE
                    /// A non-μ's live in the same 控え室, which the 『μ's』 group filter must exclude.
                    const NON_MUS_LIVE: &str = "PL!-sd1-021-SD";
                    /// Two μ's members for the two-member touch the 登場 gate requires.
                    const MUS_MEMBER_1: &str = "PL!-PR-001-PR"; // 高坂穂乃果, Printemps
                    const MUS_MEMBER_2: &str = "PL!-PR-002-PR"; // 絢瀬絵里, BiBi

                    /// The 登場 effect, for `card`.
                    fn debut_effect(game: &TestGame, card: &str) -> rabuka_engine::card::AbilityEffect {
                        game.db
                            .get_card(game.id(card))
                            .unwrap()
                            .resolved_abilities()
                            .find(|a| a.triggers.as_deref() == Some("登場"))
                            .and_then(|a| a.effect.as_ref().map(|e| (**e).clone()))
                            .expect("登場 ability has an effect")
                    }

                    /// The debut's two steps, in printed order.
                    fn debut_steps(game: &TestGame, card: &str) -> Vec<rabuka_engine::card::AbilityEffect> {
                        let eff = debut_effect(game, card);
                        assert_eq!(
                            eff.action,
                            ActionType::Sequential,
                            "the 登場 clause has TWO effects, so it must be a sequence, not a bare gain_ability"
                        );
                        eff.compound
                            .actions
                            .as_ref()
                            .expect("a sequential carries its steps")
                            .iter()
                            .map(|b| (**b).clone())
                            .collect()
                    }

                    #[test]
                    fn the_constant_is_an_optional_two_member_baton_touch_on_play() {
                        let db = load_real_database();
                        let game = TestGame::new(db);
                        for card in [DUO, R] {
                            let id = game.id(card);
                            let card_ref = game.db.get_card(id).unwrap();
                            let eff = card_ref
                                .resolved_abilities()
                                .find(|a| a.triggers.as_deref() == Some("常時"))
                                .and_then(|a| a.effect.as_ref().map(|e| e.clone()))
                                .expect("常時 ability has an effect");
                            assert_eq!(
                                eff.action,
                                ActionType::PlayBatonTouch,
                                "このカードのプレイに際し、2人のメンバーとバトンタッチしてもよい"
                            );
                            assert_eq!(eff.count, Some(2), "2人のメンバー");
                            assert_eq!(eff.optional, Some(true), "してもよい — the touch is optional");
                        }
                    }

                    /// Clause (1), the recovery. This is the step the old parse dropped entirely.
                    #[test]
                    fn the_debut_recovers_a_mus_live_card_from_the_waitroom() {
                        let db = load_real_database();
                        let game = TestGame::new(db);
                        for card in [DUO, R] {
                            let steps = debut_steps(&game, card);
                            assert_eq!(steps.len(), 2, "two printed effects, two steps: {card}");

                            let recover = &steps[0];
                            assert_eq!(
                                recover.action,
                                ActionType::MoveCards,
                                "自分の控え室にある『μ's』のライブカードを1枚手札に加え"
                            );
                            // This codebase spells 控え室 as the `discard` zone, and `zone_cards` maps
                            // `Zone::Discard` and `Zone::Waitroom` to the SAME `player.waitroom.cards`
                            // slice — so "discard" here means the waitroom, not a discard pile. Assert that
                            // the source really reads the waitroom rather than pinning the spelling, which
                            // a future rename would change without changing the mechanic.
                            use rabuka_engine::ability::enums::Zone;
                            let player = &game.state.player1;
                            let source_name = recover.source.map(|z| z.to_str().to_string()).unwrap_or_default();
                            let source = Zone::from_str(&source_name).expect("the recovery names a source zone");
                            assert!(
                                matches!(source, Zone::Discard | Zone::Waitroom),
                                "控え室 is the waitroom, got {source:?}"
                            );
                            assert_eq!(
                                rabuka_engine::ability::util::zone_cards(player, &source_name),
                                player.waitroom.cards.as_slice(),
                                "控え室 must resolve to the waitroom cards"
                            );
                            assert_eq!(
                                recover.destination,
                                Some(Zone::Hand),
                                "手札に加え"
                            );
                            assert_eq!(recover.count, Some(1), "1枚");
                            let groups: Vec<String> = recover
                                .group_names_any()
                                .map(|g| g.to_vec())
                                .unwrap_or_default();
                            assert_eq!(groups, vec!["μ's".to_string()], "『μ's』のライブカード");
                            assert!(
                                recover.card_type_any().is_some_and(|t| t.as_card_str() == "live_card"),
                                "ライブカード, not any card in the waitroom"
                            );
                        }
                    }

                    /// Clause (2), the score gain, and the thing that makes the debut a sequence rather
                    /// than a single action.
                    #[test]
                    fn the_debut_gains_a_constant_live_total_score_plus_one() {
                        let db = load_real_database();
                        let game = TestGame::new(db);
                        for card in [DUO, R] {
                            let steps = debut_steps(&game, card);
                            let gain = &steps[1];
                            assert_eq!(
                                gain.action,
                                ActionType::GainAbility,
                                "…得る — the debut GAINS an ability"
                            );
                            let gained = gain
                                .gained_effect_any()
                                .expect("the gained 常時 is structured, not just text");
                            assert_eq!(gained.action, ActionType::ModifyScore, "ライブの合計スコアを＋１する");
                            assert_eq!(
                                gained.target_any().as_deref(),
                                Some("live_total"),
                                "ライブの合計スコア — a live total, not the card's own score"
                            );
                            assert_eq!(gained.value_any(), Some(1), "＋１する");
                            assert_eq!(gained.duration_any().as_deref(), Some("live_end"), "ライブ終了時まで");

                            // 「さらに、そのメンバー2人のコストの合計が15の場合」 gates only this step.
                            let cond = gain
                                .condition
                                .as_deref()
                                .expect("そのメンバー2人のコストの合計が15の場合 is the gate");
                            assert_eq!(cond.get_comparison_type(), Some("cost"), "コストの合計");
                            assert_eq!(cond.get_aggregate(), Some("total"), "合計");
                            assert_eq!(cond.get_cost_total(), Some(15), "合計が15");
                        }
                    }

                    /// The baton gate scopes the WHOLE debut, so it is hoisted onto the sequence rather
                    /// than left on the recovery step alone. Otherwise the score gain would fire for a
                    /// member that never debuted by a two-member baton touch.
                    #[test]
                    fn the_debut_is_gated_on_a_two_member_mus_baton_touch() {
                        let db = load_real_database();
                        let game = TestGame::new(db);
                        for card in [DUO, R] {
                            let eff = debut_effect(&game, card);
                            let cond = eff
                                .condition
                                .as_deref()
                                .expect("『μ's』のメンバー2人からバトンタッチして登場した場合 gates the debut");
                            assert_eq!(
                                cond.get_movement(),
                                Some("baton_touch"),
                                "the debut is gated on HAVING BEEN baton touched"
                            );
                            let ev = cond
                                .get_trigger_event()
                                .expect("the gate carries a trigger_event");
                            // `TriggerEvent` is a typed struct, not a map.
                            let ev_json = serde_json::to_value(&ev).unwrap();
                            assert_eq!(
                                ev_json.get("type").and_then(|v| v.as_str()),
                                Some("baton_touch")
                            );
                            assert_eq!(
                                ev_json.get("min_count").and_then(|v| v.as_i64()),
                                Some(2),
                                "メンバー2人 — TWO members, not one"
                            );
                            assert_eq!(
                                ev_json.get("tense").and_then(|v| v.as_str()),
                                Some("past"),
                                "バトンタッチして登場した — the touch already happened"
                            );
                            let groups: Vec<String> = cond
                                .get_group_names()
                                .map(|g| g.to_vec())
                                .unwrap_or_default();
                            assert_eq!(groups, vec!["μ's".to_string()], "『μ's』のメンバー2人");
                        }
                    }

                    // # The runtime trigger IS covered now
                    //
                    // This file previously said the recovery was verified as data only, and recorded the
                    // end-to-end behaviour as a known gap, because the 登場 gate is
                    // 『μ's〇のメンバー2人からバトンタッチして登場した場合 and
                    // `play_to_stage_baton` cannot build that fixture: the engine only takes the
                    // double-baton route when the action carries two area INDICES, and with one it places
                    // the card into an empty area and records no touch at all. The helper did not exist, so
                    // the gap was real — but it was a missing helper, not a missing feature.
                    // `play_to_stage_double_baton` in the test helpers closes it, and the runtime tests
                    // below now run the whole chain: two recorded touches, the recovery, and the cost-15
                    // gate correctly withholding the live-end score bonus.

                    /// The debut, run for real through a genuine two-member baton touch.
                    ///
                    /// The 登場 gate is 「『μ's』のメンバー2人からバトンタッチして登場した場合」, so the fixture has
                    /// to touch exactly two μ's members. `play_to_stage_baton` cannot do that: the engine
                    /// only takes the double-baton route when the action carries two area INDICES, and with
                    /// one it simply places the card into an empty area, recording no touch at all. That is
                    /// why this file previously recorded the runtime behaviour as unverifiable — the helper
                    /// needed did not exist. `play_to_stage_double_baton` is it.
                    #[test]
                    fn the_recovery_moves_a_mus_live_out_of_the_waitroom() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);

                        let duo = game.id(DUO);
                        game.assert_card_identity(duo, DUO);

                        let mus_live = game.id(MUS_LIVE);
                        let other_live = game.id(NON_MUS_LIVE);
                        game.assert_card_in_group(mus_live, "μ's", "the card the recovery must take");
                        game.state.player1.waitroom.cards.push(mus_live);
                        game.state.player1.waitroom.cards.push(other_live);

                        let m1 = game.id(MUS_MEMBER_1);
                        let m2 = game.id(MUS_MEMBER_2);
                        game.assert_all_in_group(&[m1, m2], "μ's", "the two members the gate requires");

                        let filler = game.id(FILLER);
                        game.give_energy(40);
                        game.state.player1.stage.set_area(MemberArea::LeftSide, m1);
                        game.state.player1.stage.set_area(MemberArea::RightSide, m2);
                        game.state.player1.hand.cards.push(duo);
                        for _ in 0..4 {
                            game.state.player1.hand.cards.push(filler);
                        }
                        fill_decks(&mut game, filler);

                        game.play_to_stage_double_baton(
                            duo,
                            MemberArea::LeftSide,
                            MemberArea::RightSide,
                            MemberArea::Center,
                        );

                        // First, the fixture itself: the play really was a two-member touch, and the gate's
                        // `min_count = 2` really was satisfied. Without this the rest could pass for the
                        // wrong reason — the original attempt to write this test did exactly that.
                        assert_eq!(
                            game.state.baton_touch_arriving_card_ids.len(),
                            2,
                            "『μ's』のメンバー2人からバトンタッチして登場した場合 — the debut is gated on TWO \
                             recorded touches, and only the double-baton path records two"
                        );
                        assert!(
                            !game.state.player1.stage.stage.contains(&m1)
                                && !game.state.player1.stage.stage.contains(&m2),
                            "both touched members must have left the stage"
                        );
                        let mut g = 0;
                        while game.has_pending_choice() && g < 5 {
                            game.select_indices(&[0]);
                            g += 1;
                        }

                        // Then the printed clause: 自分の控え室にある『μ's』のライブカードを1枚手札に加え
                        assert!(
                            game.state.player1.hand.cards.contains(&mus_live),
                            "自分の控え室にある『μ's』のライブカードを1枚手札に加え — the μ's live must reach hand"
                        );
                        assert!(
                            game.state.player1.waitroom.cards.contains(&other_live),
                            "the group filter is 『μ's』 — a non-μ's live in the 控え室 must be left alone"
                        );
                    }

                    /// The cost-15 half of the clause. 「そのメンバー2人のコストの合計が15の場合」 gates ONLY the
                    /// ライブ終了時まで gain, not the recovery, so this is the case that separates the two
                    /// steps in the sequence: 4 + 4 = 8, which is not 15, so the gained 常時 must not appear.
                    #[test]
                    fn the_live_end_score_bonus_needs_a_cost_total_of_fifteen() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);

                        let duo = game.id(DUO);
                        let mus_live = game.id(MUS_LIVE);
                        game.state.player1.waitroom.cards.push(mus_live);
                        let m1 = game.id(MUS_MEMBER_1);
                        let m2 = game.id(MUS_MEMBER_2);
                        game.assert_all_in_group(&[m1, m2], "μ's", "fixture");

                        let filler = game.id(FILLER);
                        game.give_energy(40);
                        game.state.player1.stage.set_area(MemberArea::LeftSide, m1);
                        game.state.player1.stage.set_area(MemberArea::RightSide, m2);
                        game.state.player1.hand.cards.push(duo);
                        for _ in 0..4 {
                            game.state.player1.hand.cards.push(filler);
                        }
                        fill_decks(&mut game, filler);

                        game.play_to_stage_double_baton(
                            duo,
                            MemberArea::LeftSide,
                            MemberArea::RightSide,
                            MemberArea::Center,
                        );
                        let mut g = 0;
                        while game.has_pending_choice() && g < 5 {
                            game.select_indices(&[0]);
                            g += 1;
                        }

                        let cost_total = game
                            .db
                            .get_card(m1)
                            .and_then(|c| c.cost)
                            .unwrap_or(0)
                            + game.db.get_card(m2).and_then(|c| c.cost).unwrap_or(0);
                        assert_eq!(
                            cost_total, 8,
                            "precondition: the two touched members cost 4 + 4, which is not the printed 15"
                        );
                        assert_eq!(
                            game.state.mods.p1_constant_total_score_bonus,
                            0,
                            "そのメンバー2人のコストの合計が15の場合、ライブ終了時まで、\
                             「常時 ライブの合計スコアを＋１する。」を得る — with a cost total of 8 the gated \
                             half of the debut must not be granted, while the UNGATED recovery still runs"
                        );
                        assert!(
                            game.state.player1.hand.cards.contains(&mus_live),
                            "the recovery is not gated on the cost total — it still runs"
                        );
                    }

                    /// The same debut on the other card, so the shared parse is exercised on both.
                    #[test]
                    fn the_single_card_debut_also_recovers() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);

                        let r = game.id(R);
                        game.assert_card_identity(r, R);
                        let mus_live = game.id(MUS_LIVE);
                        game.state.player1.waitroom.cards.push(mus_live);
                        let m1 = game.id(MUS_MEMBER_1);
                        let m2 = game.id(MUS_MEMBER_2);

                        let filler = game.id(FILLER);
                        game.give_energy(40);
                        game.state.player1.stage.set_area(MemberArea::LeftSide, m1);
                        game.state.player1.stage.set_area(MemberArea::RightSide, m2);
                        game.state.player1.hand.cards.push(r);
                        for _ in 0..4 {
                            game.state.player1.hand.cards.push(filler);
                        }
                        fill_decks(&mut game, filler);

                        game.play_to_stage_double_baton(
                            r,
                            MemberArea::LeftSide,
                            MemberArea::RightSide,
                            MemberArea::Center,
                        );
                        let mut g = 0;
                        while game.has_pending_choice() && g < 5 {
                            game.select_indices(&[0]);
                            g += 1;
                        }

                        assert!(
                            game.state.player1.hand.cards.contains(&mus_live),
                            "PL!-pb2-000-R carries the same 登場 text and the same parse, so the recovery runs"
                        );
                    }

                    fn fill_decks(game: &mut TestGame, filler: i16) {
                        for _ in 0..20 {
                            game.state.player1.main_deck.cards.push(filler);
                            game.state.player2.main_deck.cards.push(filler);
                        }
                    }
                                }


                pub mod pb2_double_baton_touch_liella_blades_pl_sp_pb2_000_duo_test {
                    //! 嵐 千砂都＆鬼塚夏美 `PL!SP-pb2-000-DUO` (常時 / 登場)
                    //!
                    //! Text, with the icon markup rendered as plain labels:
                    //!
                    //!   常時 — このカードのプレイに際し、2人のメンバーとバトンタッチしてもよい。
                    //!
                    //!   登場 — バトンタッチして登場した場合、このバトンタッチによって控え室に置かれた
                    //!   『Liella!』のメンバーカード1枚につき、カードを1枚引く。ブレードハートを持たない
                    //!   『Liella!』のメンバーカード1枚につき、ライブ終了時まで、ブレード×2を得る。
                    //!
                    //! # This card had NO test at all
                    //!
                    //! `test_inventory.py` reported the expansion at 48/48 ability coverage for a long
                    //! time, and this card is one of the reasons that number was misleading. It shares BOTH
                    //! its abilities with `PL!SP-pb2-000-R`, which has eleven test files, and coverage is
                    //! OR-ed by card-number BASE — so `PL!SP-pb2-000-DUO` was credited with its sibling's
                    //! tests while nothing anywhere named it. The inventory now reports card VARIANTS with
                    //! no test separately; this card was the first entry on that list.
                    //!
                    //! # The 常時 is shared with another card, and the parse shows it
                    //!
                    //! `PL!SP-bp4-004-P` (平安名すみれ) has the identical 「このカードのプレイに際し、2人の
                    //! メンバーとバトンタッチしてもよい」, so both cards sit on one deduplicated ability node.
                    //! That is correct — same printed text — but it is why a base-level coverage count cannot
                    //! tell you whether a given physical card is exercised.
                    //!
                    //! Both cards are covered here, so the shared ability is asserted against each.

                    use crate::helpers::*;
                    use rabuka_engine::ability::enums::{ActionType, Zone};
                    use rabuka_engine::zones::MemberArea;

                    const DUO: &str = "PL!SP-pb2-000-DUO"; // 嵐 千砂都＆鬼塚夏美
                    const R: &str = "PL!SP-pb2-000-R";
                    const SUMIRE: &str = "PL!SP-bp4-004-P"; // 平安名すみれ, same 常時 text
                    const FILLER: &str = "PL!-sd1-010-SD"; // 高坂穂乃果
                    /// Two Liella! members, so the 登場 has per-unit work to do.
                    /// Two 『Liella!』 MEMBERS for the two-member touch.
                    ///
                    /// These were `PL!SP-PR-001-PR` and `PL!SP-PR-002-PR`, which look right and are not:
                    /// both are ENERGY cards (`type=エネルギー`, `unit=None`). They carry the
                    /// ラブライブ！スーパースター!! series, so `assert_all_in_group(..., "Liella!")` passed —
                    /// a group assertion cannot see the wrong card TYPE, and the printed clause is
                    /// 「『Liella!』のメンバーカード」. The per-unit count came out 0, which was recorded as an
                    /// open engine defect for a long time.
                    const TOUCH_A: &str = "PL!SP-PR-005-PR"; // 嵐 千砂都, 5yncri5e!
                    const TOUCH_B: &str = "PL!SP-PR-003-PR"; // 澁谷かのん, CatChu!

                    fn fill_decks(game: &mut TestGame, filler: i16) {
                        for _ in 0..20 {
                            game.state.player1.main_deck.cards.push(filler);
                            game.state.player2.main_deck.cards.push(filler);
                        }
                    }

                    fn the_constant_effect(game: &TestGame, card: &str) -> rabuka_engine::card::AbilityEffect {
                        game.db
                            .get_card(game.id(card))
                            .unwrap()
                            .resolved_abilities()
                            .find(|a| a.triggers.as_deref() == Some("常時"))
                            .unwrap_or_else(|| panic!("{card} lacks a 時常 ability"))
                            .effect
                            .as_ref()
                            .map(|e| (**e).clone())
                            .unwrap_or_else(|| panic!("{card}'s 常時 has no effect"))
                    }

                    /// The 常時: an OPTIONAL two-member touch on play.
                    #[test]
                    fn the_constant_is_an_optional_two_member_touch_on_both_cards() {
                        let db = load_real_database();
                        let game = TestGame::new(db);
                        for card in [DUO, R, SUMIRE] {
                            let eff = the_constant_effect(&game, card);
                            assert_eq!(
                                eff.action,
                                ActionType::PlayBatonTouch,
                                "このカードのプレイに際し、2人のメンバーとバトンタッチしてもよい"
                            );
                            assert_eq!(eff.count, Some(2), "2人のメンバー — TWO members");
                            assert_eq!(eff.optional, Some(true), "してもよい — the touch is optional");
                        }
                    }

                    /// The 登場 is a two-step sequence, and both steps are per-unit over the 控え室.
                    #[test]
                    fn the_debut_is_a_two_step_per_unit_sequence() {
                        let db = load_real_database();
                        let game = TestGame::new(db);
                        for card in [DUO, R] {
                            let eff = {
                                let owned = game
                                    .db
                                    .get_card(game.id(card))
                                    .unwrap()
                                    .resolved_abilities()
                                    .find(|a| a.triggers.as_deref() == Some("登場"));
                                owned
                                    .and_then(|a| a.effect.as_ref().map(|e| (**e).clone()))
                                    .unwrap_or_else(|| panic!("{card} lacks a 登場 ability"))
                            };
                            assert_eq!(
                                eff.action,
                                ActionType::Sequential,
                                "…カードを1枚引く。…得る — the 登場 clause has TWO effects"
                            );
                            let steps = eff.compound.actions.as_ref().expect("a sequential carries steps");
                            assert_eq!(steps.len(), 2, "{card}: draw step, then blade step");

                            // Step 1: draw 1 per Liella! member this baton touch sent to the 控え室.
                            let draw = &steps[0];
                            assert_eq!(draw.action, ActionType::DrawCard, "カードを1枚引く");
                            assert_eq!(draw.count, Some(1), "1枚");
                            assert_eq!(draw.source, Some(Zone::Deck), "自分のデッキ");
                            assert_eq!(draw.destination, Some(Zone::Hand), "手札に");
                            assert_eq!(draw.per_unit_any(), Some(true), "…1枚につき — a per-unit count");
                            assert_eq!(draw.per_unit_count_any(), Some(1));
                            assert_eq!(draw.per_unit_type_any(), Some("discard"), "控え室");
                            assert_eq!(
                                draw.group_names_any().map(|g| g.to_vec()),
                                Some(vec!["Liella!".to_string()]),
                                "『Liella!』のメンバーカード"
                            );
                            // Gated on having debuted by a baton touch.
                            let cond = draw.condition.as_deref().expect("バトンタッチして登場した場合");
                            assert_eq!(cond.get_movement(), Some("baton_touch"));
                            let ev = cond.get_trigger_event().expect("the gate carries a trigger_event");
                            let ev = serde_json::to_value(&ev).unwrap();
                            assert_eq!(ev.get("type").and_then(|v| v.as_str()), Some("baton_touch"));
                            assert_eq!(
                                ev.get("tense").and_then(|v| v.as_str()),
                                Some("past"),
                                "バトンタッチして登場した — the touch already happened"
                            );

                            // Step 2: 2 blades until live end per BLADE-LESS Liella! member in the 控え室.
                            let blades = &steps[1];
                            assert_eq!(blades.action, ActionType::GainResource, "ブレードを得る");
                            assert_eq!(blades.count, Some(2), "ブレード×2");
                            assert_eq!(blades.resource_any(), Some("blade"), "ブレード");
                            assert_eq!(blades.duration_any(), Some("live_end"), "ライブ終了時まで");
                            assert_eq!(blades.per_unit_any(), Some(true), "…1枚につき");
                            assert_eq!(blades.per_unit_count_any(), Some(1));
                            assert_eq!(blades.per_unit_type_any(), Some("discard"), "控え室");
                            assert_eq!(
                                blades.card_property_any(),
                                Some("has_blade_heart"),
                                "card_property is what the effect counts on"
                            );
                            assert_eq!(blades.negation_any().unwrap_or(false), true,
                                "ブレードハートを**持たない** — the property is NEGATED, which is the whole \\
                                 point of this clause: blade-less members pay, bladed ones do not"
                            );
                            assert_eq!(
                                blades.group_names_any().map(|g| g.to_vec()),
                                Some(vec!["Liella!".to_string()]),
                                "『Liella!』のメンバーカード"
                            );
                        }
                    }

                    /// The double-baton debut, run for real. It draws TWO, which is the printed value.
                    ///
                    /// This test spent a long time asserting the opposite and calling it an open engine
                    /// defect, with two "narrowed candidate causes" written up. **Both candidate causes
                    /// were wrong and there is no engine defect.** The per-unit machinery was correct
                    /// throughout; the fixture was two ENERGY cards where the clause names member cards.
                    ///
                    /// `PL!SP-PR-001-PR` / `PL!SP-PR-002-PR` carry the ラブライブ！スーパースター!! series,
                    /// so `assert_all_in_group(..., "Liella!")` passed — a group assertion cannot see the
                    /// wrong card TYPE. The clause is 「『Liella!』の**メンバーカード**」, the per-unit filter
                    /// is `member_card` + `Liella!`, and two energy cards fail the first half. `count_matching`
                    /// returned 0, correctly.
                    ///
                    /// What the two dead-end investigations did establish, and it is worth keeping:
                    ///
                    /// * The gate is **not** the problem. `evaluate_baton_touch_condition` was
                    ///   instrumented and reaches the end without an early return:
                    ///   `bt_count=2`, `baton_touch_replaced_member_id` present and in the owner's 控え室.
                    /// * The tracked batch is **not** empty. `execute_draw` reports
                    ///   `tracked=Some([.., ..])` with both displaced cards in it. The speculation that
                    ///   `recently_moved_cards` is only populated by the selection path was wrong for this
                    ///   play path — the batch arrives — and it was the reason a speculative
                    ///   `accumulate_recently_moved` call was written and then reverted.
                    ///
                    /// So the lesson is not about the engine. It is that a fixture which fails a *clause*
                    /// has to be checked against every noun in that clause: the group, the card TYPE, the
                    /// count, the unit of measure. I asserted the group and the count, and the type was
                    /// wrong the whole time.
                    #[test]
                    fn a_double_baton_debut_draws_one_per_member_it_displaced() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);

                        let duo = game.id(DUO);
                        game.assert_card_identity(duo, DUO);
                        let a = game.id(TOUCH_A);
                        let b = game.id(TOUCH_B);
                        game.assert_all_in_group(&[a, b], "Liella!", "the touched members set the per-unit count");
                        // The group assertion ALONE is not enough here, and that is the point. An energy
                        // card in the Liella! series satisfies it, while the clause wants
                        // 「『Liella!』のメンバーカード」. The previous fixture was two energy cards and every
                        // group check passed.
                        for id in [a, b] {
                            assert_eq!(
                                game.db.get_card(id).unwrap().card_type,
                                rabuka_engine::card::CardType::Member,
                                "『Liella!』のメンバーカード — the touched cards must be MEMBERS, whatever their \
                                 series says; an energy card in the same series passes the group check and \
                                 fails the clause"
                            );
                        }

                        let filler = game.id(FILLER);
                        game.give_energy(40);
                        game.state.player1.stage.set_area(MemberArea::LeftSide, a);
                        game.state.player1.stage.set_area(MemberArea::RightSide, b);
                        game.state.player1.hand.cards.push(duo);
                        for _ in 0..6 {
                            game.state.player1.hand.cards.push(filler);
                        }
                        fill_decks(&mut game, filler);

                        // Measured on the DECK, not the hand. The debut consumes the card being played, so a
                        // hand delta conflates the play with the draws and can even underflow. The deck
                        // loses a card only to a draw.
                        let deck_before = game.state.player1.main_deck.cards.len();
                        let waitroom_before = game.state.player1.waitroom.cards.len();

                        game.play_to_stage_double_baton(
                            duo,
                            MemberArea::LeftSide,
                            MemberArea::RightSide,
                            MemberArea::Center,
                        );
                        let mut g = 0;
                        while game.has_pending_choice() && g < 6 {
                            game.select_indices(&[0]);
                            g += 1;
                        }

                        assert_eq!(
                            game.state.baton_touch_arriving_card_ids.len(),
                            2,
                            "precondition: the engine recorded two touches"
                        );
                        assert_eq!(
                            game.state.player1.waitroom.cards.len() - waitroom_before,
                            2,
                            "このバトンタッチによって控え室に置かれた — both members reached the 控え室, so the \\
                             per-unit clause has two to count"
                        );
                        assert_eq!(
                            deck_before - game.state.player1.main_deck.cards.len(),
                            2,
                            "このバトンタッチによって控え室に置かれた『Liella!』のメンバーカード1枚につき、\
                             カードを1枚引く — one draw per displaced Liella! member card, so TWO"
                        );
                    }

                    /// The second half of the same clause, which is the one that reads 「持たない」.
                    ///
                    /// 「ブレードハートを持たない『Liella!』のメンバーカード1枚につき、ライブ終了時まで、
                    /// ブレード×2を得る」. The property is NEGATED, and the two displaced members are
                    /// blade-less members, so both steps of the sequence fire on the same play.
                    #[test]
                    fn the_blade_half_also_reads_the_displaced_members() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);

                        let duo = game.id(DUO);
                        let a = game.id(TOUCH_A);
                        let b = game.id(TOUCH_B);
                        for id in [a, b] {
                            assert_eq!(
                                game.db.get_card(id).unwrap().card_type,
                                rabuka_engine::card::CardType::Member
                            );
                        }

                        let filler = game.id(FILLER);
                        game.give_energy(40);
                        game.state.player1.stage.set_area(MemberArea::LeftSide, a);
                        game.state.player1.stage.set_area(MemberArea::RightSide, b);
                        game.state.player1.hand.cards.push(duo);
                        for _ in 0..6 {
                            game.state.player1.hand.cards.push(filler);
                        }
                        fill_decks(&mut game, filler);

                        game.play_to_stage_double_baton(
                            duo,
                            MemberArea::LeftSide,
                            MemberArea::RightSide,
                            MemberArea::Center,
                        );
                        let mut g = 0;
                        while game.has_pending_choice() && g < 6 {
                            game.select_indices(&[0]);
                            g += 1;
                        }

                        // 「持たない」 — the two members are members with no blade heart, so the step's
                        // `negation: true` on `card_property: has_blade_heart` is satisfied for both.
                        let blade_hearted = game
                            .db
                            .get_card(a)
                            .and_then(|c| c.blade_heart.as_ref().map(|h| !h.hearts.is_empty()))
                            .unwrap_or(false);
                        assert!(
                            !blade_hearted,
                            "precondition: 『Liella!〇のメンバーカード in the 控え室 must be BLADE-LESS for \
                             「ブレードハートを持たない」 to pay out"
                        );
                    }
                                }


                pub mod pb2_live_start_bibi_only_waits_opponent_cost_two_pl_pb2_024_n_test {
                    //! 西木野真姫 `PL!-pb2-024-N` (ライブ開始時)
                    //!
                    //! 自分のステージにいるメンバーが『BiBi』のみの場合、相手のステージにいるコスト2以下の
                    //! メンバー1人をウェイトにする。
                    //!
                    //! Two independent gates: stage exclusivity over BiBi, and a cost ceiling on the
                    //! target. Each negative below breaks exactly one of them.

                    use crate::helpers::*;
                    use rabuka_engine::core::types::AbilityTrigger;
                    use rabuka_engine::zones::MemberArea;

                    const MAKI: &str = "PL!-pb2-024-N";
                    /// BiBi members with no ability, so nothing else contributes.
                    const BIBI_A: &str = "PL!-bp3-015-N";
                    const BIBI_B: &str = "PL!-bp5-018-N";
                    /// Not BiBi.
                    const NON_BIBI: &str = "PL!S-bp5-012-N";
                    /// Opponent members. The cost is the whole point of this card, so both are pinned:
                    /// `PL!SP-pb1-014-N` (cost 2) and `PL!SP-bp1-014-N` (cost 4) are different cards
                    /// with the same number and the same name, and picking the wrong one makes the
                    /// positive case pass or fail for the wrong reason.
                    const OPP_CHEAP: &str = "PL!SP-pb1-014-N"; // 嵐 千砂都, cost 2
                    const OPP_DEAR: &str = "PL!SP-bp1-014-N"; // 嵐 千砂都, cost 4

                    fn fire_live_start(game: &mut TestGame, cid: i16) {
                        let ability_id = {
                            let card = game.db.get_card(cid).unwrap();
                            let ab = card
                                .resolved_abilities()
                                .find(|a| a.triggers.as_deref() == Some("ライブ開始時"))
                                .unwrap_or_else(|| panic!("card {} lacks a ライブ開始時 ability", card.card_no));
                            format!("{}_{}", card.card_no, ab.full_text)
                        };
                        let card_no = game.db.get_card(cid).unwrap().card_no.to_string();
                        let pid = game.state.player1.id.clone();
                        game.state.trigger_auto_ability(
                            ability_id,
                            AbilityTrigger::LiveStart,
                            pid.clone(),
                            Some(card_no),
                            Some(cid),
                            None,
                            None,
                        );
                        game.state.activating_card = Some(cid);
                        game.state.process_pending_auto_abilities(&pid);
                    }

                    /// Stage `own` for player 1, `theirs` for player 2, fire ライブ開始時, and return
                    /// the opponent ids plus the game.
                    ///
                    /// `expect_wait` is what the calling test is about, and the prompt shape is
                    /// asserted from it rather than sniffed:
                    ///
                    /// * `true`  — the printed effect fires. A member-selection prompt is permitted
                    ///   and answered if offered, but NOT required: with a single eligible opponent
                    ///   member the engine resolves the target itself, and the test's real check is
                    ///   the `waited` assertion that follows. The old guard was not merely redundant
                    ///   here, it was a lie about shape — it implied a prompt where there is none.
                    /// * `false` — the printed effect does not fire, so NO prompt may appear. The
                    ///   old guard consumed one, so a negative that wrongly offered a target went
                    ///   on to assert "not waited" and passed for the wrong reason.
                    ///
                    /// An empty `allowed` list makes `drain_choices_strict` fail on any prompt.
                    fn run_expecting(own: &[&str], theirs: &[&str], expect_wait: bool) -> (TestGame, Vec<i16>) {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let filler = game.new_id("PL!-sd1-010-SD");
                        fill_decks(&mut game, filler);
                        for (i, c) in own.iter().enumerate() {
                            game.state.player1.stage.stage[i] = game.id(c);
                        }
                        let ids: Vec<i16> = theirs.iter().map(|c| game.id(c)).collect();
                        for (i, &id) in ids.iter().enumerate() {
                            game.state.player2.stage.stage[i] = id;
                        }
                        let maki = game.id(MAKI);
                        game.assert_card_identity(maki, MAKI);
                        // The target gate is a cost test, so the target needs a printed cost. The group
                        // pin is NOT applied here: one negative deliberately stages a non-BiBi member.
                        for c in theirs {
                            let id = game.id(c);
                            assert!(
                                game.db.get_card(id).and_then(|c| c.cost).is_some(),
                                "{c} must be a member with a printed cost",
                            );
                        }
                        game.state.player1.stage.stage[2] = maki;
                        fire_live_start(&mut game, maki);
                        if expect_wait {
                            game.drain_choices_strict(&["SelectCard"], &[0]);
                        } else {
                            game.drain_choices_strict(&[], &[]);
                        }
                        (game, ids)
                    }

                    /// The printed effect fires — a target prompt is expected.
                    fn run(own: &[&str], theirs: &[&str]) -> (TestGame, Vec<i16>) {
                        run_expecting(own, theirs, true)
                    }

                    /// The printed effect does not fire — no prompt may be offered.
                    fn run_no_effect(own: &[&str], theirs: &[&str]) -> (TestGame, Vec<i16>) {
                        run_expecting(own, theirs, false)
                    }

                    fn waited(game: &TestGame, ids: &[i16]) -> Vec<bool> {
                        ids.iter()
                            .map(|&id| game.state.mods.get_orientation_modifier(id) == Some("wait"))
                            .collect()
                    }

                    #[test]
                    fn all_bibi_stage_waits_a_cost_two_opponent_member() {
                        let db = load_real_database();
                        let probe = TestGame::new(db.clone());
                        // Pin the ally group: stage exclusivity is the first gate, so a fixture that is
                        // not actually BiBi would make this pass for the wrong reason.
                        for c in [BIBI_A, BIBI_B] {
                            probe.assert_card_in_group(probe.id(c), "BiBi", "own-stage fixture");
                        }

                        let (game, ids) = run(&[BIBI_A, BIBI_B], &[OPP_CHEAP]);
                        assert_eq!(
                            game.db.get_card(ids[0]).and_then(|c| c.cost),
                            Some(2),
                            "precondition: the target is exactly on the コスト2以下 ceiling"
                        );
                        assert_eq!(
                            waited(&game, &ids),
                            vec![true],
                            "『BiBi』のみ and コスト2以下 — both gates hold, so the target is waited"
                        );
                    }

                    #[test]
                    fn all_bibi_stage_leaves_a_cost_four_opponent_member_alone() {
                        let (game, ids) = run_no_effect(&[BIBI_A, BIBI_B], &[OPP_DEAR]);
                        assert_eq!(
                            game.db.get_card(ids[0]).and_then(|c| c.cost),
                            Some(4),
                            "precondition: the target is just over the ceiling"
                        );
                        assert_eq!(
                            waited(&game, &ids),
                            vec![false],
                            "コスト4 — over the コスト2以下 ceiling, so not an eligible target"
                        );
                    }

                    /// Break the exclusivity half only: the target is cheap and eligible, but our own
                    /// stage is not purely BiBi.
                    #[test]
                    fn a_non_bibi_ally_blocks_the_effect() {
                        let (game, ids) = run_no_effect(&[BIBI_A, NON_BIBI], &[OPP_CHEAP]);
                        assert_eq!(
                            waited(&game, &ids),
                            vec![false],
                            "メンバーが『BiBi』のみ — a μ's and an AZALEA member on our stage break \
                             exclusivity even though the target is eligible"
                        );
                    }

                    /// のみ over a genuinely EMPTY own stage: vacuously true, so the wait happens.
                    ///
                    /// This test previously asserted `observed || !observed`, which is `assert!(true)`
                    /// and could not fail under any engine — and it did not even build the scenario its
                    /// name claimed, because it staged MAKI in slot 0, leaving a one-BiBi-member stage.
                    /// The stage really is empty here: MAKI lives in the live card zone for a
                    /// ライブ開始時, and the ability is triggered directly.
                    ///
                    /// The reading is pinned as `true` because のみ is a universal and the repository
                    /// already works this way: see `pb2_debut_wait_opponent_blade_two_or_less_pl_pb2_029_n_test.rs::an_empty_ally_slot_still_satisfies_exclusivity`,
                    /// which pins the same vacuous reading for 「『μ's』のみ」.
                    ///
                    /// **If the rules are ever ruled the other way this test goes red, and that is the
                    /// point** — it is a report on an open question, not a shrug. See
                    /// docs/PBLL02_ABILITY_REVIEW.md §8.3 item 1.
                    #[test]
                    fn an_empty_own_stage_satisfies_bibi_only_vacuously() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let filler = game.new_id("PL!-sd1-010-SD");
                        fill_decks(&mut game, filler);
                        let opp = game.id(OPP_CHEAP);
                        game.state.player2.stage.stage[0] = opp;
                        let maki = game.id(MAKI);
                        assert_eq!(
                            game.state.player1.stage.stage,
                            [-1, -1, -1],
                            "precondition: our own stage is genuinely empty, which is the case this test is about"
                        );
                        fire_live_start(&mut game, maki);
                        game.drain_choices_strict(&["SelectCard"], &[0]);
                        assert_eq!(
                            game.state.mods.get_orientation_modifier(opp),
                            Some("wait"),
                            "『のみ』 is a universal, so an empty stage satisfies it vacuously and the cost-2 \
                             opponent member is waited"
                        );
                    }

                    /// The cost ceiling is a real gate: an opponent member ABOVE コスト2 is not waited.
                    ///
                    /// This previously asserted that MAKI — our own card — had no orientation
                    /// modifier. The ability targets the OPPONENT, so it could never have touched her
                    /// and the assertion said nothing about the engine. The negative now breaks the
                    /// cost gate on a card the ability actually selects.
                    #[test]
                    fn an_opponent_member_above_the_cost_bound_is_not_waited() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let filler = game.new_id("PL!-sd1-010-SD");
                        fill_decks(&mut game, filler);
                        let bibi_a = game.id(BIBI_A);
                        let opp = game.id(OPP_DEAR);
                        game.assert_card_cost(opp, 4);
                        game.state.player1.stage.stage[0] = bibi_a;
                        game.state.player2.stage.stage[0] = opp;
                        let maki = game.id(MAKI);
                        fire_live_start(&mut game, maki);
                        // Negative: the cost gate excludes her, so the ability must offer nothing at
                        // all. The old guard swallowed one prompt if it appeared, which is exactly
                        // the failure this test exists to rule out.
                        game.drain_choices_strict(&[], &[]);
                        assert_eq!(
                            game.state.mods.get_orientation_modifier(opp),
                            None,
                            "コスト2以下 — 嵐 千砂都 (cost 4) is above the bound, so she is not waited even \
                             though our stage is exclusively BiBi"
                        );
                    }
                                }


                pub mod pb2_live_start_wait_opponent_low_printed_hearts_pl_pb2_006_pp_test {
                    //! 西木野真姫 `PL!-pb2-006-PP` / `-R` (ライブ開始時, and the identical-effect 起動)
                    //!
                    //! {{live_start.png|ライブ開始時}}このメンバーをウェイトにし、手札を1枚控え室に置いてもよい：
                    //! 相手のステージにいる元々持つハートの数が1つ以下のメンバー1人をウェイトにする。
                    //!
                    //! Three things to pin, each on its own axis:
                    //!   * 「元々持つ」 — the printed heart total, not the current one.
                    //!   * 「1つ以下」 — an inclusive ceiling, so 0 and 1 qualify and 2 does not.
                    //!   * 「メンバー1人」 — exactly one, and only on the OPPONENT's stage.
                    //!
                    //! The cost is the optional sequential from rule 9.4.2.2: declining must skip the
                    //! whole cost, including the self-wait.

                    use crate::helpers::*;
                    use rabuka_engine::core::types::AbilityTrigger;
                    use rabuka_engine::zones::MemberArea;

                    const MAKI: &str = "PL!-pb2-006-PP";
                    /// 0 printed hearts — qualifies.
                    const OPP_0: &str = "PL!-bp3-012-N";
                    /// 1 printed heart — the inclusive boundary, qualifies.
                    const OPP_1: &str = "PL!-PR-014-PR";
                    /// 2 printed hearts — one over the ceiling, must not qualify.
                    const OPP_2: &str = "PL!-bp6-017-N";

                    fn fire_live_start(game: &mut TestGame, cid: i16) {
                        let ability_id = {
                            let card = game.db.get_card(cid).unwrap();
                            let ab = card
                                .resolved_abilities()
                                .find(|a| a.triggers.as_deref() == Some("ライブ開始時"))
                                .unwrap_or_else(|| panic!("card {} lacks a ライブ開始時 ability", card.card_no));
                            format!("{}_{}", card.card_no, ab.full_text)
                        };
                        let card_no = game.db.get_card(cid).unwrap().card_no.to_string();
                        let pid = game.state.player1.id.clone();
                        game.state.trigger_auto_ability(
                            ability_id,
                            AbilityTrigger::LiveStart,
                            pid.clone(),
                            Some(card_no),
                            Some(cid),
                            None,
                            None,
                        );
                        game.state.activating_card = Some(cid);
                        game.state.process_pending_auto_abilities(&pid);
                    }

                    /// Build: our Maki centre, opponent stages given by (card_no, slot), hand seeded.
                    fn setup(opponent: &[&str]) -> (TestGame, i16, Vec<i16>) {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let filler = game.new_id("PL!-sd1-010-SD");
                        fill_decks(&mut game, filler);
                        let me = game.id(MAKI);
                        game.assert_card_identity(me, MAKI);
                        game.state.player1.stage.stage[MemberArea::Center as usize] = me;
                        let ids: Vec<i16> = opponent.iter().map(|c| game.id(c)).collect();
                        for (i, &id) in ids.iter().enumerate() {
                            game.state.player2.stage.stage[i] = id;
                        }
                        // Enough hand to pay: the ability card is not a hand card, so seed spares.
                        for _ in 0..3 {
                            game.state.player1.hand.cards.push(filler);
                        }
                        (game, me, ids)
                    }

                    /// Pay the optional cost, leaving whatever target prompt follows on the table.
                    fn fire_and_pay(game: &mut TestGame, me: i16) {
                        fire_live_start(game, me);
                        // First prompt is the cost's hand discard; the hand has only identical filler
                        // so index 0 is unambiguous.
                        assert_eq!(
                            game.pending_choice_type().as_deref(),
                            Some("SelectCard"),
                            "the cost step is a hand discard"
                        );
                        game.select_indices(&[0]);
                    }

                    #[test]
                    fn a_zero_printed_heart_opponent_member_is_waited() {
                        let (mut game, me, ids) = setup(&[OPP_0]);
                        fire_and_pay(&mut game, me);

                        assert_eq!(
                            game.state.mods.get_orientation_modifier(ids[0]),
                            Some("wait"),
                            "元々持つハートの数が0 — 0つ以下 qualifies, so the opponent member is waited"
                        );
                    }

                    #[test]
                    fn a_one_printed_heart_opponent_member_is_waited() {
                        let (mut game, me, ids) = setup(&[OPP_1]);
                        fire_and_pay(&mut game, me);

                        assert_eq!(
                            game.state.mods.get_orientation_modifier(ids[0]),
                            Some("wait"),
                            "1つ以下 is an INCLUSIVE ceiling, so exactly 1 printed heart qualifies"
                        );
                    }

                    #[test]
                    fn a_two_printed_heart_opponent_member_is_never_offered() {
                        let (mut game, me, ids) = setup(&[OPP_2]);
                        fire_and_pay(&mut game, me);

                        assert_eq!(
                            game.state.mods.get_orientation_modifier(ids[0]),
                            None,
                            "2つ — one over the ceiling, so this member is not an eligible target and \
                             must be left active"
                        );
                    }

                    /// The heart filter and the 1人 count together: with a 0-heart and a 2-heart member
                    /// on board, only the 0-heart one is selectable, and only it is waited.
                    #[test]
                    fn only_the_qualifying_member_is_affected() {
                        let (mut game, me, ids) = setup(&[OPP_0, OPP_2]);
                        fire_and_pay(&mut game, me);

                        assert_eq!(
                            game.state.mods.get_orientation_modifier(ids[0]),
                            Some("wait"),
                            "the 0-heart member is eligible and is waited"
                        );
                        assert_eq!(
                            game.state.mods.get_orientation_modifier(ids[1]),
                            None,
                            "the 2-heart member is over the ceiling and stays active"
                        );
                    }

                    /// 「メンバー1人」 — one only. With several eligible members the player must choose.
                    #[test]
                    fn exactly_one_is_chosen_from_several_eligible() {
                        let (mut game, me, ids) = setup(&[OPP_0, OPP_1]);
                        fire_and_pay(&mut game, me);

                        assert_eq!(
                            game.pending_choice_type().as_deref(),
                            Some("SelectCard"),
                            "two eligible members and メンバー1人 — the player picks one"
                        );
                        assert_eq!(
                            game.pending_choice_count(),
                            1,
                            "メンバー1人 — exactly one selection, not both"
                        );
                        game.select_indices(&[0]);

                        let waited = ids
                            .iter()
                            .filter(|&&id| game.state.mods.get_orientation_modifier(id) == Some("wait"))
                            .count();
                        assert_eq!(waited, 1, "precisely one opponent member ends up waited");
                    }

                    /// 「相手のステージ」 — our own members are never targets, even low-heart ones.
                    #[test]
                    fn our_own_low_heart_member_is_not_a_target() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let filler = game.new_id("PL!-sd1-010-SD");
                        fill_decks(&mut game, filler);
                        let me = game.id(MAKI);
                        let ally = game.id(OPP_0); // 0 printed hearts, on OUR side
                        game.state.player1.stage.stage[MemberArea::Center as usize] = me;
                        game.state.player1.stage.stage[MemberArea::LeftSide as usize] = ally;
                        for _ in 0..3 {
                            game.state.player1.hand.cards.push(filler);
                        }

                        fire_and_pay(&mut game, me);

                        assert_eq!(
                            game.state.mods.get_orientation_modifier(ally),
                            None,
                            "相手のステージ — our own 0-heart member is not an eligible target"
                        );
                    }

                    /// No eligible opponent member: the effect resolves without a target prompt.
                    #[test]
                    fn no_eligible_opponent_member_is_harmless() {
                        let (mut game, me, ids) = setup(&[OPP_2]);
                        fire_and_pay(&mut game, me);

                        assert_eq!(
                            game.state.mods.get_orientation_modifier(ids[0]),
                            None,
                            "only a 2-heart member is on the opponent's stage, so nothing is waited"
                        );
                    }

                    /// Declining the optional cost skips the WHOLE cost, self-wait included.
                    #[test]
                    fn declining_skips_the_self_wait_and_the_target_prompt() {
                        let (mut game, me, ids) = setup(&[OPP_0]);
                        let hand_before = game.state.player1.hand.cards.len();

                        fire_live_start(&mut game, me);
                        assert_eq!(
                            game.pending_choice_type().as_deref(),
                            Some("SelectCard"),
                            "the optional cost offers a hand discard"
                        );
                        assert!(
                            game.get_pending_choice().allow_skip(),
                            "置いてもよい — the discard must be skippable"
                        );
                        game.select_indices(&[]);

                        assert_eq!(
                            game.state.mods.get_orientation_modifier(me),
                            None,
                            "rule 9.4.2.2 — declining skips the whole cost, so she is not waited"
                        );
                        assert_eq!(
                            game.state.mods.get_orientation_modifier(ids[0]),
                            None,
                            "declining means no opponent member is waited either"
                        );
                        assert_eq!(
                            game.state.player1.hand.cards.len(),
                            hand_before,
                            "declining must not discard a card"
                        );
                    }
                                }


                pub mod pb2_psychic_fire_four_clauses_pl_pb2_042_l_test {
                    //! PSYCHIC FIRE `PL!-pb2-042-L` (自動, ターン1回)
                    //!
                    //! Text, with the icon markup rendered as plain labels:
                    //!
                    //!   自動／ターン1回 — 自分がエールしたとき、エールにより公開された自分のカードの中に
                    //!   「矢澤にこ」と「西木野真姫」と「絢瀬絵里」のメンバーカードがあり、**かつ**
                    //!   自分のセンターエリアにコスト11以上の『BiBi』のメンバーがいる場合、相手のステージに
                    //!   いる元々持つハートの数が4つ以下のメンバー1人をウェイトにする。
                    //!
                    //! **The four negative tests below are LIVE evidence, not vacuous.** This header used
                    //! to say the opposite — that they asserted "no wait" and passed only because the
                    //! positive did not fire, with an instruction to "treat the fixture pins as the real
                    //! content until `all_clauses_met_waits_the_foe` passes". That warning went stale in
                    //! the dangerous direction the moment the positive was fixed (see its doc comment:
                    //! CLOSED 2026-10-02), and it had exactly the effect
                    //! `characterization/strict_engine_bug_expected_fail_test.rs` warns about in its own
                    //! header: a reader told these tests prove nothing will dismiss a real regression as
                    //! "the known vacuous one" instead of reading the failure. The positive fires
                    //! (`foe waited = true`), so each negative below is the positive with exactly one
                    //! clause broken — which is what makes it evidence that THAT clause is load-bearing.
                    //!
                    //! What is NOT a decode problem: `bytecode_no_silent_decode_fallbacks` reports no
                    //! fallback for this ability, so all four clauses reach the engine intact.
                    //!
                    //! The four clauses, and the two the parser had been dropping (docs §8.3 item 15):
                    //!   * 「「矢澤にこ」と「西木野真姫」と「絢瀬絵里」」 — the と-joined name list. The
                    //!     parser's name-list regex did not allow `」と「`, so it matched only the LAST
                    //!     entry and this clause was really "絢瀬絵里 was revealed". FIXED.
                    //!   * 「自分のセンターエリアに」 — the centre clause was inheriting
                    //!     `location: revealed_cards` from the clause before it, so it looked for an
                    //!     11-cost BiBi member among the cards the yell revealed rather than on the
                    //!     stage. FIXED.
                    //!
                    //! The remaining clauses are the centre cost bound (11以上) and the target's printed
                    //! heart bound (4以下), the latter the same mechanism as `PL!-pb2-006` (≤1) and
                    //! `PL!-pb2-033` (≤3).

                    use crate::helpers::*;
                    use rabuka_engine::core::types::AbilityTrigger;
                    use rabuka_engine::zones::MemberArea;

                    const PSYCHIC: &str = "PL!-pb2-042-L";
                    // The condition filters on CHARACTER names, not card numbers. Kept separate from
                    // the card consts above because the two are different things and conflating them
                    // is how a test ends up asserting a card number where the data holds a name.
                    const NICO_NAME: &str = "矢澤にこ";
                    const MAKI_NAME: &str = "西木野真姫";
                    const ERI_NAME: &str = "絢瀬絵里";
                    /// The three named characters, all BiBi, all revealed.
                    const NICO: &str = "PL!-PR-017-PR"; // 矢澤にこ, cost 2
                    const MAKI: &str = "PL!-pb2-006-PP"; // 西木野真姫, cost 2
                    const ERI: &str = "PL!-pb2-002-PP"; // 絢瀬絵里, cost 4
                    /// A 17-cost BiBi member — clears コスト11以上 in the CENTRE.
                    const CENTRE_DEAR: &str = "PL!-PR-015-PR"; // 西木野真姫, cost 17
                    /// A 2-cost BiBi member — under the コスト11以上 bound.
                    ///
                    /// Read together with `open_gap_bibi_group_matching_is_by_unit_string_not_by_game_group`,
                    /// this case is pinned correctly; the bound itself is not tightly pinned, see the note
                    /// on that test.
                    const CENTRE_CHEAP: &str = "PL!-pb2-006-PP"; // cost 2
                    /// An 11+-cost member that is NOT BiBi — clears the cost bound, fails the group.
                    const CENTRE_NON_BIBI: &str = "PL!-pb1-026-N";
                    /// Opponent members by printed heart total.
                    const OPP_2: &str = "PL!-bp6-017-N"; // 2 printed hearts
                    const OPP_5: &str = "PL!N-bp4-019-N"; // 5 printed hearts — over the bound
                    const FILLER: &str = "PL!-sd1-010-SD";

                    /// Stage `centre` in the CENTRE, reveal `revealed`, put `foe` on the opponent's
                    /// stage, fire the 自動, and report whether the foe was waited.
                    fn run(centre: &str, revealed: &[&str], foe: &str) -> bool {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let filler = game.id(FILLER);
                        for _ in 0..20 {
                            game.state.player1.main_deck.cards.push(filler);
                        }
                        let foe_id = game.id(foe);
                        game.state.player2.stage.stage[MemberArea::Center as usize] = foe_id;
                        let centre_id = game.id(centre);
                        game.state.player1.stage.stage[MemberArea::Center as usize] = centre_id;
                        for c in revealed {
                            game.state.revealed_cards.push(game.id(c));
                        }
                        game.state.player1.stage.stage[MemberArea::LeftSide as usize] = -1;

                        let psychic = game.id(PSYCHIC);
                        game.assert_card_identity(psychic, PSYCHIC);
                        game.state.player1.live_card_zone.cards.push(psychic);

                        let ability_id = {
                            let card = game.db.get_card(psychic).unwrap();
                            let ab = card
                                .resolved_abilities()
                                .find(|a| a.triggers.as_deref() == Some("自動"))
                                .unwrap_or_else(|| panic!("{PSYCHIC} lacks a 自動 ability"));
                            format!("{}_{}", card.card_no, ab.full_text)
                        };
                        let card_no = game.db.get_card(psychic).unwrap().card_no.to_string();
                        let pid = game.state.player1.id.clone();
                        game.state.activating_card = Some(psychic);
                        game.state.trigger_auto_ability(
                            ability_id,
                            AbilityTrigger::Auto,
                            pid.clone(),
                            Some(card_no),
                            Some(psychic),
                            None,
                            None,
                        );
                        game.state.process_pending_auto_abilities(&pid);
                        let _ = game.drain_auto_ability_choices();

                        game.state.mods.get_orientation_modifier(foe_id) == Some("wait")
                    }

                    /// Fixtures the clauses rest on, pinned so a data change cannot make them vacuous.
                    #[test]
                    fn fixtures_are_what_the_clauses_assume() {
                        let db = load_real_database();
                        let game = TestGame::new(db);

                        for card_no in [NICO, MAKI, ERI] {
                            let id = game.id(card_no);
                            game.assert_card_in_group(id, "BiBi", "one of the three named characters");
                        }
                        assert!(
                            game.db.get_card(game.id(CENTRE_DEAR)).and_then(|c| c.cost).unwrap_or(0) >= 11,
                            "the centre fixture must clear コスト11以上"
                        );
                        assert!(
                            game.db.get_card(game.id(CENTRE_CHEAP)).and_then(|c| c.cost).unwrap_or(99) < 11,
                            "the centre control must be under コスト11以上"
                        );
                        for (card_no, want) in [(OPP_2, 2u8), (OPP_5, 5)] {
                            let total = game
                                .db
                                .get_card(game.id(card_no))
                                .and_then(|c| c.base_heart.as_ref().map(|b| b.hearts.values_sum()))
                                .unwrap_or(0);
                            assert_eq!(
                                total, want,
                                "{card_no} must print {want} hearts — the 4つ以下 bound is the point"
                            );
                        }
                    }

                    /// The positive. **CLOSED 2026-10-02.** This used to be a known non-firing bug, and
                    /// while it was open the test asserted `!fired` — pinning the broken behaviour with a
                    /// failure message that said the opposite ("the effect should fire and does not").
                    ///
                    /// The cause was parser defect D4 (`docs/PARSER_DEFECTS.md`): the effect node
                    /// inherited `position: "center"` and the three quoted character names from the gating
                    /// condition, so the action was re-gated on its own condition's terms and the
                    /// conjunction could never be satisfied from the printed text. With the condition
                    /// context kept on the condition and off the effect, all four clauses are met and the
                    /// foe is waited.
                    ///
                    /// The parse is now: a `location_condition` on `revealed_cards` naming
                    /// 矢澤にこ/西木野真姫/絢瀬絵里, ANDed with a `comparison_condition` carrying
                    /// `position: "center"`, `cost_limit: 11` (`>=`), `group_names: ["BiBi"]`, plus a
                    /// top-level `yell_trigger: true` — the compound the printed text describes.
                    #[test]
                    fn all_clauses_met_waits_the_foe() {
                        let fired = run(CENTRE_DEAR, &[NICO, MAKI, ERI], OPP_2);
                        println!(
                            "all four clauses met -> foe waited = {fired} (characters revealed, 17-cost \
                             BiBi in centre, foe at 2 printed hearts)"
                        );
                        assert!(
                            fired,
                            "OPEN GAP: …「矢澤にこ」と「西木野真姫」と「絢瀬絵里」…かつ センターエリアに\
                             コスト11以上の『BiBi』のメンバー…かつ 元々持つハートの数が4つ以下のメンバー1人を\
                             ウェイトにする — the effect should fire and does not"
                        );
                    }

                    /// THE test for the と-joined name list. Dropping any one of the three must stop the
                    /// effect — with only 絢瀬絵里 required (the pre-fix parse) the first two would not
                    /// have mattered at all.
                    #[test]
                    fn dropping_any_one_of_the_three_named_characters_stops_it() {
                        for missing in [NICO, MAKI, ERI] {
                            let revealed: Vec<&str> = [NICO, MAKI, ERI]
                                .iter()
                                .copied()
                                .filter(|c| *c != missing)
                                .collect();
                            assert!(
                                !run(CENTRE_DEAR, &revealed, OPP_2),
                                "「矢澤にこ」と「西木野真姫」と「絢瀬絵里」 — with {} not revealed the \
                                 condition is not met",
                                missing
                            );
                        }
                    }

                    /// THE test for the centre-clause location leak: the cost-qualified BiBi must be found
                    /// on the STAGE. While the clause carried `revealed_cards`, putting a cost-17 BiBi
                    /// among the revealed cards satisfied it and a centre member of the right cost did not.
                    ///
                    /// Renamed from `the_eleven_cost_bibi_…`: there is no eleven-cost BiBi in this test. It
                    /// stages a cost-2 member in the centre and puts the cost-17 in the reveal, so the
                    /// "eleven" was doing no work and naming a bound this test never exercises.
                    #[test]
                    fn the_cost_qualified_bibi_must_be_in_the_centre_not_the_reveal() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let filler = game.id(FILLER);
                        for _ in 0..20 {
                            game.state.player1.main_deck.cards.push(filler);
                        }
                        let foe_id = game.id(OPP_2);
                        game.state.player2.stage.stage[MemberArea::Center as usize] = foe_id;
                        // A cost-2 BiBi in the CENTRE, and a cost-17 BiBi among the REVEALED cards.
                        let cheap = game.id(CENTRE_CHEAP);
                        game.state.player1.stage.stage[MemberArea::Center as usize] = cheap;
                        for c in [NICO, MAKI, ERI, CENTRE_DEAR] {
                            game.state.revealed_cards.push(game.id(c));
                        }
                        let psychic = game.id(PSYCHIC);
                        game.state.player1.live_card_zone.cards.push(psychic);

                        let ability_id = {
                            let card = game.db.get_card(psychic).unwrap();
                            let ab = card
                                .resolved_abilities()
                                .find(|a| a.triggers.as_deref() == Some("自動"))
                                .unwrap();
                            format!("{}_{}", card.card_no, ab.full_text)
                        };
                        let card_no = game.db.get_card(psychic).unwrap().card_no.to_string();
                        let pid = game.state.player1.id.clone();
                        game.state.activating_card = Some(psychic);
                        game.state.trigger_auto_ability(
                            ability_id, AbilityTrigger::Auto, pid.clone(), Some(card_no), Some(psychic), None, None,
                        );
                        game.state.process_pending_auto_abilities(&pid);
                        let _ = game.drain_auto_ability_choices();

                        assert_ne!(
                            game.state.mods.get_orientation_modifier(foe_id),
                            Some("wait"),
                            "自分のセンターエリアにコスト11以上の『BiBi』のメンバー — the 17-cost BiBi is in \
                             the REVEALED set, not the centre, so the condition must not be met"
                        );
                    }

                    /// Extra copies of a named character do not change anything.
                    ///
                    /// Each of the three name clauses parses as its own `location_condition` with
                    /// `count: 1` and `operator: ">="`, and the text says 「…のメンバーカードがあり」 —
                    /// each name must be PRESENT, not accounted for. Two readings of the same three
                    /// clauses would both satisfy the tests above and are distinguished only here:
                    ///
                    ///   * present-at-least-once, which is what the parse says; and
                    ///   * an exact multiset, i.e. exactly one にこ, exactly one 真姫, exactly one 絵里,
                    ///     which would fail on a duplicate and which the `>=` operator rules out.
                    ///
                    /// `dropping_any_one_of_the_three_named_characters_stops_it` cannot catch that
                    /// difference: it removes a name entirely, and both readings agree a missing name
                    /// fails. Two にこ revealed alongside one 真姫 and one 絵里 must still wait the foe.
                    #[test]
                    fn extra_copies_of_a_named_character_still_satisfy_its_clause() {
                        assert!(
                            run(CENTRE_DEAR, &[NICO, NICO, MAKI, ERI], OPP_2),
                            "count: 1 with operator >= per name — 「矢澤にこ」と「西木野真姫」と「絢瀬絵里」の\
                             メンバーカードがあり is a presence test, so a second にこ is redundant, not fatal"
                        );
                        // The control, and the reason the pair above is worth having. THREE cards, two
                        // distinct names, no 絵里: the same card count as a passing reveal, so a rule
                        // that read 「3 member cards among the reveal」 would pass this and is wrong.
                        // `dropping_any_one_of_the_three_named_characters_stops_it` cannot catch that:
                        // it drops to TWO cards, where every candidate rule agrees.
                        assert!(
                            !run(CENTRE_DEAR, &[NICO, NICO, MAKI], OPP_2),
                            "three cards is not the clause — all THREE NAMES must be present. A duplicate \
                             of one name does not make up for a missing one"
                        );
                    }

                    /// The cost bound on the centre clause.
                    #[test]
                    fn a_cheap_centre_bibi_does_not_satisfy_the_cost_bound() {
                        assert!(
                            !run(CENTRE_CHEAP, &[NICO, MAKI, ERI], OPP_2),
                            "コスト11以上 — a cost-2 BiBi in the centre is under the bound"
                        );
                    }

                    /// Remaining coverage gap, recorded rather than filled: the コスト11以上 bound is pinned
                    /// by cost 17 (passes) and cost 2 (fails), which admits any threshold in `3..=17`.
                    ///
                    /// Closing it needs a `unit: "BiBi"` member costing exactly 11 (or 10, for the nearest
                    /// miss). Note what this is NOT: a group-matching defect.
                    ///
                    /// `PL!-bp3-003-P` (南ことり, cost 11 — exactly the bound) looks like the card this
                    /// needs, and it was used here to claim an off-by-one on the bound and then a
                    /// group-matching bug. Both were wrong. 南ことり is a μ's member whose `unit` field
                    /// says `"Printemps"`; `PL!-pb2-002-PP` (絢瀬絵里) is a genuinely different character
                    /// whose `unit` says `"BiBi"`. Group membership is matched on that string, so the
                    /// engine is CORRECT to exclude 南ことり from a 『BiBi』 clause. Two characters in two
                    /// groups, not one character in two printings.
                    ///
                    /// So the bound stays loosely pinned until a `unit: "BiBi"` card at cost 11 turns up.
                    ///

                    /// The group on the centre clause.
                    #[test]
                    fn a_cheap_centre_non_bibi_does_not_satisfy_the_group() {
                        assert!(
                            !run(CENTRE_NON_BIBI, &[NICO, MAKI, ERI], OPP_2),
                            "『BiBi』のメンバー — a non-BiBi centre member must not satisfy the clause"
                        );
                    }

                    /// The heart bound on the target, the same mechanism as 006 (≤1) and 033 (≤3).
                    #[test]
                    fn an_opponent_member_with_five_printed_hearts_is_not_waited() {
                        assert!(
                            !run(CENTRE_DEAR, &[NICO, MAKI, ERI], OPP_5),
                            "元々持つハートの数が4つ以下 — 5 printed hearts is over the bound"
                        );
                    }
                                }


                pub mod pb2_replacement_appear_wait_low_hearts_pl_pb2_002_pp_test {
                    //! 絢瀬絵里 `PL!-pb2-002-PP` / `-R` (常時) — replacement appearance rule
                    //!
                    //! {{jyouji.png|常時}}このメンバーの正面のエリアには、元々持つハートの数が4つ以下の
                    //! メンバーは、ウェイト状態で登場する。
                    //!
                    //! A REPLACEMENT rule: it changes how other members APPEAR, it does not fire on an
                    //! event. That is why it is resolved ONCE at placement
                    //! (`GameState::replacement_appear_wait_applies`, called from
                    //! `handle_play_member_to_stage`) instead of in the constant scan — a constant would
                    //! re-apply every recalculation and the member could never leave wait. The last test
                    //! pins exactly that, and is the one that fails under a constant implementation.

                    use crate::helpers::*;
                    use rabuka_engine::zones::MemberArea;

                    const ERI: &str = "PL!-pb2-002-PP";
                    /// 0 printed hearts — inside the bound.
                    const IN_BOUND_0: &str = "PL!-bp3-012-N";
                    /// 4 printed hearts — exactly the bound, inclusive.
                    const IN_BOUND_4: &str = "PL!-bp3-002-P";
                    /// 5 printed hearts — one over the bound. A member with no ability of its own, so
                    /// the only thing that could wait it is this rule.
                    const OVER_BOUND_5: &str = "PL!N-bp4-019-N";

                    /// Stand ERI in a side slot, play `victim` into `victim_slot`, report orientation.
                    /// ERI goes to the RIGHT slot so `victim_slot: 0` is genuinely empty — playing into
                    /// an occupied slot is a baton touch, which is a different scenario entirely.
                    fn orientation_after_appear(victim: &str, victim_slot: usize) -> Option<String> {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let filler = game.new_id("PL!-sd1-010-SD");
                        fill_decks(&mut game, filler);

                        let eri = game.id(ERI);
                        game.assert_card_identity(eri, ERI);
                        game.state.player1.hand.cards.push(eri);
                        game.give_energy(40);
                        game.play_to_stage(eri, MemberArea::RightSide);
                        assert_eq!(
                            game.state.mods.get_orientation_modifier(eri),
                            None,
                            "precondition: the host arrives active — a member is never in front of itself"
                        );

                        let v = game.id(victim);
                        game.state.player1.hand.cards.push(v);
                        game.give_energy(40);
                        game.play_to_stage(v, MemberArea::ALL[victim_slot]);

                        game.state
                            .mods
                            .get_orientation_modifier(v)
                            .map(|s| s.to_string())
                    }

                    #[test]
                    fn without_the_rule_a_member_appears_active() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let filler = game.new_id("PL!-sd1-010-SD");
                        fill_decks(&mut game, filler);
                        let v = game.id(IN_BOUND_0);
                        game.state.player1.hand.cards.push(v);
                        game.give_energy(10);
                        game.play_to_stage(v, MemberArea::Center);

                        assert_eq!(
                            game.state.mods.get_orientation_modifier(v),
                            None,
                            "precondition: with no replacement rule in play a member appears active"
                        );
                    }

                    #[test]
                    fn a_zero_heart_member_entering_the_front_appears_in_wait() {
                        assert_eq!(
                            orientation_after_appear(IN_BOUND_0, 1).as_deref(),
                            Some("wait"),
                            "ハートの数が4つ以下 — 0 qualifies, so the member appears in wait"
                        );
                    }

                    #[test]
                    fn a_four_heart_member_entering_the_front_appears_in_wait() {
                        assert_eq!(
                            orientation_after_appear(IN_BOUND_4, 1).as_deref(),
                            Some("wait"),
                            "4つ以下 is an INCLUSIVE bound, so exactly 4 qualifies"
                        );
                    }

                    #[test]
                    fn a_five_heart_member_enters_active() {
                        assert_eq!(
                            orientation_after_appear(OVER_BOUND_5, 1),
                            None,
                            "5つ — one over the bound, so the member is unaffected"
                        );
                    }

                    /// The bound reads PRINTED hearts (元々持つ), so a member whose current hearts have
                    /// been raised is still judged on its printed total.
                    #[test]
                    fn the_bound_reads_printed_hearts() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let filler = game.new_id("PL!-sd1-010-SD");
                        fill_decks(&mut game, filler);
                        let eri = game.id(ERI);
                        game.state.player1.hand.cards.push(eri);
                        game.give_energy(40);
                        game.play_to_stage(eri, MemberArea::RightSide);

                        let v = game.id(OVER_BOUND_5);
                        game.state.player1.hand.cards.push(v);
                        game.give_energy(40);
                        game.state
                            .mods
                            .add_heart_modifier(v, rabuka_engine::card::HeartColor::Heart04, 9);
                        game.play_to_stage(v, MemberArea::Center);

                        assert_eq!(
                            game.state.mods.get_orientation_modifier(v),
                            None,
                            "元々持つ — the bound reads the PRINTED total, so a member whose current \
                             hearts were raised is still judged on its printed 5"
                        );
                    }

                    /// 正面のエリア is read as the CENTRE area, so a side-slot arrival is unaffected.
                    #[test]
                    fn a_member_entering_a_side_slot_is_unaffected() {
                        assert_eq!(
                            orientation_after_appear(IN_BOUND_0, 0),
                            None,
                            "正面のエリア — the rule covers the centre area, so a member entering the \
                             left slot appears active"
                        );
                    }

                    /// The rule must already be on the BOARD when the other member appears.
                    #[test]
                    fn a_member_that_appeared_before_the_rule_is_unaffected() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let filler = game.new_id("PL!-sd1-010-SD");
                        fill_decks(&mut game, filler);
                        let v = game.id(IN_BOUND_0);
                        game.state.player1.hand.cards.push(v);
                        game.give_energy(10);
                        game.play_to_stage(v, MemberArea::Center);

                        let eri = game.id(ERI);
                        game.state.player1.hand.cards.push(eri);
                        game.give_energy(40);
                        game.play_to_stage(eri, MemberArea::RightSide);

                        assert_eq!(
                            game.state.mods.get_orientation_modifier(v),
                            None,
                            "the rule governs APPEARANCE — a member already on stage when the rule \
                             arrives is not retroactively put in wait"
                        );
                    }

                    /// THE test that separates a replacement from a constant.
                    #[test]
                    fn the_member_can_still_be_activated_afterwards() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let filler = game.new_id("PL!-sd1-010-SD");
                        fill_decks(&mut game, filler);
                        let eri = game.id(ERI);
                        game.state.player1.hand.cards.push(eri);
                        game.give_energy(40);
                        game.play_to_stage(eri, MemberArea::RightSide);

                        let v = game.id(IN_BOUND_0);
                        game.state.player1.hand.cards.push(v);
                        game.give_energy(40);
                        game.play_to_stage(v, MemberArea::Center);
                        assert_eq!(
                            game.state.mods.get_orientation_modifier(v),
                            Some("wait"),
                            "precondition: the member appeared in wait"
                        );

                        game.state.mods.add_orientation_modifier(v, "active");
                        game.state.recalculate_constants();
                        assert_ne!(
                            game.state.mods.get_orientation_modifier(v),
                            Some("wait"),
                            "the rule is a REPLACEMENT, not a constant — once the member is activated it \
                             must not be put straight back to wait by the next recalculation"
                        );
                    }
                                }


                pub mod pl_s_bp6_015_n_debut_opponent_cost2_wait_test {
                    /// PL!S-bp6-015-N (西木野真姫) 登場: wait one opponent member of cost 2 or less.
                    ///
                    /// Every test here is the same shape: a コスト2以下 filter decides whether the
                    /// opponent's member is waited. So the two things that can silently break it are
                    /// the COST of the fixture member and the wait itself, and both are now pinned:
                    /// the print identity, the cost the filter reads, and an exact `wait` / not-wait
                    /// result rather than a double negative.
                    use crate::helpers::*;
                    use rabuka_engine::zones::MemberArea;

                    const YOSHIKO: &str = "PL!S-bp6-015-N"; // 津島善子— the 登場 source
                    const OPP_COST_2: &str = "PL!N-bp7-017-N"; // cost 2 → inside the gate
                    const OPP_COST_13: &str = "PL!-sd1-003-SD"; // cost 13 → outside the gate

                    /// 真姫 in hand, `opp` as p2's only stage member, a filled deck, 15 energy.
                    fn setup(opp: &str) -> (TestGame, i16, i16) {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let yoshiko = game.id(YOSHIKO);
                        let opp_member = game.id(opp);
                        game.assert_card_identity(yoshiko, YOSHIKO);
                        game.state.player2.stage.stage = [opp_member, -1, -1];
                        game.state.player1.hand.cards.push(yoshiko);
                        game.give_energy(15);
                        for _ in 0..5 {
                            let f = game.id("PL!-sd1-010-SD");
                            game.state.player1.main_deck.cards.push(f);
                        }
                        (game, yoshiko, opp_member)
                    }

                    fn orientation_of(game: &TestGame, cid: i16) -> Option<String> {
                        game.state
                            .mods
                            .get_orientation_modifier(cid)
                            .map(|m| m.to_string())
                    }

                    #[test]
                    fn s_bp6_015_wait_opponent_cost2_succeeds() {
                        let (mut game, yoshiko, opp_low2) = setup(OPP_COST_2);
                        game.assert_card_cost(opp_low2, 2);

                        game.play_to_stage(yoshiko, MemberArea::Center);

                        assert_eq!(
                            orientation_of(&game, opp_low2).as_deref(),
                            Some("wait"),
                            "コスト2以下のメンバーの1人をウェイト状態にする — the cost-2 opponent \
                             member qualifies"
                        );
                    }

                    #[test]
                    fn s_bp6_015_wait_opponent_cost_high_no_wait() {
                        let (mut game, yoshiko, opp_high) = setup(OPP_COST_13);
                        game.assert_card_cost(opp_high, 13);

                        game.play_to_stage(yoshiko, MemberArea::Center);

                        // Exactly no modifier: a cost-13 member is not a candidate at all, so the
                        // choice must never have been offered and the card must be pristine. The
                        // old `is_none() || != Some("wait")` said the same thing but read as if it
                        // allowed other states, and never checked the cost that decides it.
                        assert_eq!(
                            orientation_of(&game, opp_high),
                            None,
                            "コスト2以下 only — a cost-13 opponent member gets no orientation modifier"
                        );
                        assert_eq!(
                            game.state.player2.stage.stage[0],
                            opp_high,
                            "the opponent's member must still be on their stage"
                        );
                    }

                    #[test]
                    fn s_bp6_015_wait_opponent_empty_no_effect() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let yoshiko = game.id(YOSHIKO);
                        game.assert_card_identity(yoshiko, YOSHIKO);
                        game.state.player2.stage.stage = [-1, -1, -1];
                        game.state.player1.hand.cards.push(yoshiko);
                        game.give_energy(15);
                        for _ in 0..5 {
                            let f = game.id("PL!-sd1-010-SD");
                            game.state.player1.main_deck.cards.push(f);
                        }

                        game.play_to_stage(yoshiko, MemberArea::Center);

                        assert!(
                            !game.has_pending_choice(),
                            "an empty opponent stage has no candidate, so no choice may be offered"
                        );
                    }

                    #[test]
                    fn s_bp6_015_wait_opponent_multiple_cost2_choose_one() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let yoshiko = game.id(YOSHIKO);
                        let opp1 = game.id(OPP_COST_2);
                        let opp2 = game.new_id(OPP_COST_2);
                        game.assert_card_identity(opp1, OPP_COST_2);
                        game.assert_card_cost(opp1, 2);
                        game.assert_same_card_name(opp1, opp2, "two copies of the same cost-2 print");
                        assert_ne!(opp1, opp2, "two separate card instances");
                        game.state.player2.stage.stage = [opp1, opp2, -1];
                        game.state.player1.hand.cards.push(yoshiko);
                        game.give_energy(15);
                        for _ in 0..5 {
                            let f = game.id("PL!-sd1-010-SD");
                            game.state.player1.main_deck.cards.push(f);
                        }

                        game.play_to_stage(yoshiko, MemberArea::Center);

                        // Two qualifying members → the printed 「1人」 must offer a choice.
                        assert!(game.has_pending_choice(), "expected SelectCard for multiple cost2 targets");
                        assert_eq!(game.pending_choice_type().as_deref(), Some("SelectCard"));
                        game.select_indices(&[0]);
                        game.drain_choices_strict(&["SelectCard", "SelectAutoAbility"], &[]);

                        // Exactly one, and it must be the one that was chosen.
                        let waited1 = orientation_of(&game, opp1).as_deref() == Some("wait");
                        let waited2 = orientation_of(&game, opp2).as_deref() == Some("wait");
                        assert_eq!(
                            [waited1, waited2],
                            [true, false],
                            "1人 — exactly the chosen member (index 0) is waited, the other is not"
                        );
                    }
                                }


                pub mod riko_center_gated_live_start_low_blade_opponent_wait_test {
                    /// Tests for 桜内梨子 (PL!S-bp5-002-R+) — LiveStart center ability.
                    ///
                    /// ライブ開始時/センター: 自分のステージの右サイドエリアと左サイドエリアにいる
                    /// メンバーのコストが同じ場合、相手のステージにいる元々持つブレードの数が
                    /// 3つ以下のすべてのメンバーをウェイトにする。
                    ///
                    /// Condition: location_condition, position=left_side, position_compare=right_side,
                    ///            operator="=", require_position_cards=true
                    /// Effect: change_state(wait, opponent_stage_members_with_blade<=3)
                    ///
                    /// require_position_cards=true means empty slots DON'T count as cost 0 —
                    /// both left and right must have members for the equality check to activate.
                    use crate::helpers::*;

                    /// Advance from Main (turn 1) to LiveCardSetFirstAttacker.
                    fn advance_to_live_card_set(game: &mut TestGame) {
                        game.pass();
                        game.pass();
                        game.pass();
                        game.pass();
                        game.pass();
                    }

                    /// Advance from LiveCardSet to LiveStart (after set_live_card).
                    fn advance_to_live_start(game: &mut TestGame) {
                        game.pass();
                        game.pass();
                    }

                    fn riko(game: &TestGame) -> i16 {
                        game.id("PL!S-bp5-002-R+") // cost=11, blade=2
                    }

                    fn aqours_cost4(game: &TestGame) -> i16 {
                        game.id("PL!S-bp2-002-R") // cost=4, blade=0
                    }

                    fn aqours_cost2(game: &TestGame) -> i16 {
                        game.id("PL!S-PR-025-PR") // cost=2, blade=1
                    }

                    fn filler_live(game: &TestGame) -> i16 {
                        game.id("PL!-sd1-020-SD")
                    }

                    fn filler_hand(game: &TestGame) -> i16 {
                        game.id("PL!-sd1-010-SD") // blade=1
                    }

                    /// Setup: fill decks, give energy, place Riko at center.
                    fn setup_riko_at_center(game: &mut TestGame) {
                        for _ in 0..15 {
                            game.state.player1.main_deck.cards.push(filler_hand(game));
                            game.state.player2.main_deck.cards.push(filler_hand(game));
                        }
                        game.give_energy(15);
                        game.state.player1.stage.stage = [-1, riko(game), -1];
                    }

                    fn run_live_start(game: &mut TestGame) {
                        let live = filler_live(game);
                        game.state.player1.hand.cards.push(live);
                        advance_to_live_card_set(game);
                        game.set_live_card(live);
                        advance_to_live_start(game);
                        // Answer what cannot be declined, decline what can: a mandatory
                        // prompt left parked mid-ability produces exactly the absence
                        // the next assertion checks, so nothing fails.
                        game.drain_choices();
                    }

                    // ===================================================================
                    // Positive: both positions occupied with same cost → ability fires
                    // ===================================================================

                    #[test]
                    fn riko_equal_cost_both_occupied_triggers() {
                        let mut game = TestGame::new(load_real_database());
                        setup_riko_at_center(&mut game);

                        game.state.player1.stage.stage[0] = aqours_cost4(&game); // cost=4
                        game.state.player1.stage.stage[2] = aqours_cost4(&game); // cost=4

                        let opp = filler_hand(&game);
                        game.state.player2.stage.stage[1] = opp;

                        run_live_start(&mut game);

                        assert!(
                            game.state.mods.get_orientation_modifier(opp) == Some("wait"),
                            "Low-blade opponent member should be wait when costs are equal"
                        );
                    }

                    #[test]
                    fn riko_equal_cost_waits_all_repeated_opponent_instances() {
                        let mut game = TestGame::new(load_real_database());
                        setup_riko_at_center(&mut game);
                        game.state.player1.stage.stage[0] = aqours_cost4(&game);
                        game.state.player1.stage.stage[2] = aqours_cost4(&game);
                        let opponent_a = game.new_id("PL!S-bp2-002-R");
                        let opponent_b = game.new_id("PL!S-bp2-002-R");
                        game.state.player2.stage.stage[0] = opponent_a;
                        game.state.player2.stage.stage[1] = opponent_b;

                        run_live_start(&mut game);

                        assert_ne!(opponent_a, opponent_b);
                        assert_eq!(
                            game.state.mods.get_orientation_modifier(opponent_a),
                            Some("wait")
                        );
                        assert_eq!(
                            game.state.mods.get_orientation_modifier(opponent_b),
                            Some("wait")
                        );
                    }

                    // ===================================================================
                    // Negative: different costs → no trigger
                    // ===================================================================

                    #[test]
                    fn riko_different_costs_no_trigger() {
                        let mut game = TestGame::new(load_real_database());
                        setup_riko_at_center(&mut game);

                        game.state.player1.stage.stage[0] = aqours_cost4(&game); // cost=4
                        game.state.player1.stage.stage[2] = aqours_cost2(&game); // cost=2

                        let opp = filler_hand(&game);
                        game.state.player2.stage.stage[1] = opp;

                        run_live_start(&mut game);

                        assert!(
                            game.state.mods.get_orientation_modifier(opp) != Some("wait"),
                            "Should NOT trigger when costs differ"
                        );
                    }

                    // ===================================================================
                    // require_position_cards: left empty → no trigger
                    // ===================================================================

                    #[test]
                    fn riko_left_empty_no_trigger() {
                        let mut game = TestGame::new(load_real_database());
                        setup_riko_at_center(&mut game);

                        // Left empty, right has a card
                        game.state.player1.stage.stage[2] = aqours_cost4(&game);

                        let opp = filler_hand(&game);
                        game.state.player2.stage.stage[1] = opp;

                        run_live_start(&mut game);

                        assert!(
                            game.state.mods.get_orientation_modifier(opp) != Some("wait"),
                            "Should NOT trigger when left side is empty"
                        );
                    }

                    // ===================================================================
                    // require_position_cards: right empty → no trigger
                    // ===================================================================

                    #[test]
                    fn riko_right_empty_no_trigger() {
                        let mut game = TestGame::new(load_real_database());
                        setup_riko_at_center(&mut game);

                        game.state.player1.stage.stage[0] = aqours_cost4(&game);
                        // Right empty

                        let opp = filler_hand(&game);
                        game.state.player2.stage.stage[1] = opp;

                        run_live_start(&mut game);

                        assert!(
                            game.state.mods.get_orientation_modifier(opp) != Some("wait"),
                            "Should NOT trigger when right side is empty"
                        );
                    }

                    // ===================================================================
                    // require_position_cards: both empty → no trigger
                    // ===================================================================

                    #[test]
                    fn riko_both_empty_no_trigger() {
                        let mut game = TestGame::new(load_real_database());
                        setup_riko_at_center(&mut game);

                        let opp = filler_hand(&game);
                        game.state.player2.stage.stage[1] = opp;

                        run_live_start(&mut game);

                        assert!(
                            game.state.mods.get_orientation_modifier(opp) != Some("wait"),
                            "Should NOT trigger when both sides are empty"
                        );
                    }

                    // ===================================================================
                    // Same cost (cost=2) on both sides → triggers
                    // ===================================================================

                    #[test]
                    fn riko_same_cost_different_cards_triggers() {
                        let mut game = TestGame::new(load_real_database());
                        setup_riko_at_center(&mut game);

                        game.state.player1.stage.stage[0] = aqours_cost2(&game); // cost=2
                        game.state.player1.stage.stage[2] = aqours_cost2(&game); // cost=2

                        let opp = filler_hand(&game);
                        game.state.player2.stage.stage[1] = opp;

                        run_live_start(&mut game);

                        assert!(
                            game.state.mods.get_orientation_modifier(opp) == Some("wait"),
                            "Should trigger when both cost=2"
                        );
                    }
                                }


                pub mod self_discard_target_wait_pl_bp6_010_n_test {
                    use crate::helpers::*;
                    use crate::test_modules::support::bp7_wait_immunity_helpers::*;
                    use rabuka_engine::zones::MemberArea;

                    #[test]
                    fn pl_bp6_010_n_cost_limit_wait_blocked_by_wait_immunity() {
                        let db = load_real_database();
                        let mut g = TestGame::new(db.clone());
                        let p2_kanan = p2_establish_wait_immunity(&mut g);
                        let honoka = g.id("PL!-bp6-010-N");
                        g.state.player1.hand.cards.push(honoka);
                        g.give_energy(10);
                        g.play_to_stage(honoka, MemberArea::RightSide);
                        g.activate_ability(honoka);
                        while g.has_pending_choice() {
                            g.select_indices(&[0]);
                        }
                        assert!(
                            !is_waited(&g, p2_kanan),
                            "穂乃果's cost-limit wait must be blocked by wait-immunity"
                        );
                    }

                    #[test]
                    fn pl_bp6_010_n_self_discard_waits_selected_target_keeps_stage() {
                        let db = load_real_database();
                        let mut g = TestGame::new(db.clone());
                        let honoka = g.id("PL!-bp6-010-N");
                        let target1 = g.id("PL!-sd1-010-SD");
                        let target2 = g.id("PL!-sd1-013-SD");
                        g.state.player2.stage.set_area(MemberArea::Center, target1);
                        g.state
                            .player2
                            .stage
                            .set_area(MemberArea::LeftSide, target2);
                        g.state.player1.hand.cards.push(honoka);
                        g.give_energy(10);
                        g.play_to_stage(honoka, MemberArea::RightSide);
                        g.activate_ability(honoka);
                        let p1_right = g.state.player1.stage.get_area(MemberArea::RightSide);
                        assert_eq!(p1_right, None, "Honoka should have left stage (self_cost)");
                        assert!(
                            g.state.player1.waitroom.cards.contains(&honoka),
                            "Honoka should be in waitroom"
                        );
                        assert!(
                            g.has_pending_choice(),
                            "Should prompt for change_state target selection"
                        );
                        g.select_indices(&[1]);
                        let p2_center = g.state.player2.stage.get_area(MemberArea::Center);
                        assert_eq!(p2_center, Some(target1), "Target should remain on stage");
                        let target1_ori = g.state.mods.get_orientation_modifier(target1);
                        assert_eq!(target1_ori, Some("wait"), "Target should be in wait state");
                        let target2_ori = g.state.mods.get_orientation_modifier(target2);
                        assert_eq!(
                            target2_ori, None,
                            "Unselected target should have no orientation modifier"
                        );
                    }
                                }


                pub mod self_wait_and_nijigasaki_activation_test {
                    use crate::helpers::*;
                    use rabuka_engine::core::types::AbilityTrigger;
                    use rabuka_engine::game_setup::{self, ActionType};

                    const FILLER: &str = "PL!-sd1-010-SD";

                    fn trigger_auto(game: &mut TestGame, cid: i16, trigger: AbilityTrigger, trigger_str: &str) {
                        let card = game.db.get_card(cid).unwrap();
                        let ab = card
                            .resolved_abilities()
                            .find(|a| a.triggers.as_deref() == Some(trigger_str))
                            .expect("card should have the requested trigger ability");
                        let pid = game.state.player1.id.clone();
                        game.state.trigger_auto_ability(
                            format!("{}_{}", card.card_no, ab.full_text),
                            trigger,
                            pid.clone(),
                            Some(card.card_no.to_string()),
                            Some(cid),
                            None,
                            None,
                        );
                        game.state.activating_card = Some(cid);
                        game.state.process_pending_auto_abilities(&pid);
                    }

                    fn use_ability_offers(game: &TestGame, cid: i16) -> usize {
                        game_setup::generate_possible_actions(&game.state)
                            .into_iter()
                            .filter(|a| {
                                a.action_type == ActionType::UseAbility
                                    && a.parameters.as_ref().and_then(|p| p.card_id) == Some(cid)
                            })
                            .count()
                    }

                    fn is_active(game: &TestGame, cid: i16) -> bool {
                        rabuka_engine::ability::util::orientation_matches_state(
                            game.state.mods.get_orientation_modifier(cid),
                            "active",
                        )
                    }

                    fn is_waited(game: &TestGame, cid: i16) -> bool {
                        game.state.mods.get_orientation_modifier(cid) == Some("wait")
                    }

                    #[test]
                    fn kanata_n_bp3_006_debut_active_self_becomes_waited() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let kanata = game.id("PL!N-bp3-006-R");
                        game.state.player1.stage.stage[1] = kanata;

                        assert_ne!(
                            game.state.mods.get_orientation_modifier(kanata),
                            Some("wait"),
                            "freshly placed member starts active"
                        );
                        trigger_auto(&mut game, kanata, AbilityTrigger::Debut, "登場");
                        assert_eq!(
                            game.state.mods.get_orientation_modifier(kanata),
                            Some("wait"),
                            "debut resolves with self-wait"
                        );
                    }

                    #[test]
                    fn wondermates_n_sd2_025_live_start_waited_nijigasaki_activates_and_retains_ability_offer() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let kanata = game.id("PL!N-bp1-006-R＋"); // 虹ヶ咲, 起動
                        let wondermates = game.id("PL!N-sd2-025-P");
                        let outsider = game.id(FILLER); // μ's — not a legal target

                        // Kanata waits (as if she used a self-wait effect earlier).
                        game.state.player1.stage.stage = [kanata, wondermates, outsider];
                        game.state.mods.add_orientation_modifier(kanata, "wait");
                        game.state.mods.add_orientation_modifier(outsider, "wait");

                        let filler = game.id(FILLER);
                        fill_decks(&mut game, filler);
                        // Fund Kanata so her 起動 is genuinely payable (2E draw; discard needs
                        // a hand card): the usability assert below must mean something.
                        game.give_energy(2);
                        game.add_to_hand(game.new_id(FILLER));
                        trigger_auto(
                            &mut game,
                            wondermates,
                            AbilityTrigger::LiveStart,
                            "ライブ開始時",
                        );
                        while game.has_pending_choice() {
                            game.select_indices(&[0]);
                        }

                        assert!(
                            is_active(&game, kanata),
                            "ワンダーメイツ activates the waited 虹ヶ咲 member"
                        );
                        assert!(
                            is_waited(&game, outsider),
                            "non-虹ヶ咲 members are not touched"
                        );
                        assert!(
                            use_ability_offers(&game, kanata) >= 1,
                            "her 起動 remains usable this turn"
                        );
                    }
                                }


