                // ====================================================================
                // Issue 13 (Manual Guide): PL!N-bp3-011-R (ミア・テイラー)
                // Multi-part IF-THEN: 3 independent checks for blade.
                // ====================================================================

                /// Heart01..heart06 icons a card PRINTS (its own `base_heart`), which is what
                /// ミア・テイラー's 登場 compares: 「そのメンバーが持つハートと、このメンバーが
                /// 持つハートの中に同じ色のハートがある場合」.
                fn printed_notes(game: &TestGame, card_id: i16) -> Vec<(rabuka_engine::core::card::HeartColor, u8)> {
                    let card = game.db.get_card(card_id).expect("card is in the database");
                    let hearts = card
                        .base_heart
                        .as_ref()
                        .unwrap_or_else(|| panic!("{} prints hearts", card.card_no));
                    hearts
                        .hearts
                        .iter()
                        .filter(|(color, count)| *count > 0 && (1..=6).contains(&color.index()))
                        .map(|(color, count)| (*color, *count))
                        .collect()
                }

                /// Blade ミア's 登場 grants for one chosen member: one per heart of MIA's own
                /// that has a SAME-COLOURED heart on the chosen member — i.e. for each colour
                /// ミア prints, her whole count of that colour counts once the target holds the
                /// colour at all. Verified against the engine: 三船栞子 (heart01, heart03×1,
                /// heart04×2) against ミア (heart03×2, heart06×1) shares only heart03, and the
                /// engine grants 2 — MIA's two heart03 icons, not the target's one.
                ///
                /// The card's second sentence extends the same treatment to members with an
                /// equal COST and to an equal printed blade count; those clauses are about
                /// OTHER members on the opponent's stage, and this fixture stages exactly one,
                /// so the heart comparison is the whole story here.
                ///
                /// Derived from card data, so a data change shows up as a failing number
                /// instead of passing a `>= 0` (true of every blade modifier in the game).
                fn expected_shared_color_blade(game: &TestGame, mia: i16, target: i16) -> usize {
                    let mine = printed_notes(game, mia);
                    let theirs = printed_notes(game, target);
                    mine.iter()
                        .filter(|(color, _)| theirs.iter().any(|(c, _)| c == color))
                        .map(|(_, count)| *count as usize)
                        .sum()
                }

                #[test]
                fn issue13_mia_three_conditional_blade_checks() {
                    let db = load_real_database();
                    let mut game = TestGame::new(db);
                    let mia = game.id("PL!N-bp3-011-R");
                    // The target must actually share a heart colour with ミア, otherwise the
                    // printed condition is false and the test proves nothing. Picked from the
                    // card data rather than assumed.
                    let target_no = ["PL!N-bp4-001-R", "PL!N-sd1-010-SD", "PL!-sd1-010-SD", "PL!S-sd1-001-SD"]
                        .into_iter()
                        .find(|no| {
                            let id = card_id(&game.db, no);
                            expected_shared_color_blade(&game, mia, id) > 0
                        })
                        .expect("a member sharing a heart colour with ミア・テイラー");
                    let target = game.id(target_no);
                    let filler = game.id("PL!-sd1-010-SD");

                    game.state.player2.stage.stage[0] = target;
                    game.state.player1.hand.cards.push(mia);
                    game.state.player1.hand.cards.push(filler);
                    game.give_energy(7);
                    fill_decks(&mut game);

                    let expected_blade = expected_shared_color_blade(&game, mia, target);
                    game.play_to_stage(mia, MemberArea::Center);

                    while game.has_pending_choice() {
                        if game.pending_choice_type().as_deref() == Some("SelectAutoAbility") {
                            game.select_indices(&[]);
                        } else {
                            game.select_indices(&[0]);
                        }
                    }

                    // 「同じ色のハートがある場合、ブレードを得る」 — the exact number of shared
                    // colours, not ">= 0" (which is true for every blade modifier in the game).
                    assert_eq!(
                        game.state.mods.get_blade_modifier(mia),
                        expected_blade as i16,
                        "13: ミア gains one blade per heart colour shared with the chosen \
                         opponent member ({target_no})"
                    );
                }

                // ====================================================================
                // サイコーハート (PL!N-bp3-026-L) ab#0: LiveStart conditional alternative.
                // If success zone has score 1 or 5 → +1 score. If both exist → +2.
                // ====================================================================

                fn saikou_drain(game: &mut TestGame) {
                    let mut safety = 0;
                    while game.has_pending_choice() && safety < 20 {
                        safety += 1;
                        game.select_indices(&[]);
                    }
                }

                // No cards in success zone → no bonus.
                #[test]
                fn saikou_edge_no_cards() {
                    let db = load_real_database();
                    let mut game = TestGame::new(db);
                    let saikou = game.id("PL!N-bp3-026-L");

                    game.state.player1.hand.cards.push(saikou);
                    fill_decks(&mut game);
                    advance_to_live_card_set_p1(&mut game);
                    game.set_live_card(saikou);
                    advance_to_live_start(&mut game);
                    saikou_drain(&mut game);

                    let score_mod = game.state.mods.get_score_modifier(saikou);
                    assert_eq!(score_mod, 0, "no cards: score unchanged");
                }

                // Score-1 card only in success zone → +1.
