                    #[test]
                    fn mixed_deck_dia_first_then_daisuki() {
                        let db = load_real_database();
                        let mut game = TestGame::new(db);
                        let dia = game.id("PL!S-bp2-004-R");
                        let daisuki = game.id("PL!S-bp3-020-L");

                        game.state.player1.stage.stage[2] = dia;
                        game.state.player1.stage.stage[0] = game.new_id("PL!-sd1-010-SD");
                        game.state.player1.stage.stage[1] = game.new_id("PL!-sd1-010-SD");
                        game.state.player1.hand.cards.push(daisuki);
                        for _ in 0..30 {
                            game.state
                                .player1
                                .main_deck
                                .cards
                                .push(game.id("LL-E-001-SD"));
                        }
                        for _ in 0..30 {
                            game.state
                                .player1
                                .main_deck
                                .cards
                                .push(game.id("PL!-sd1-010-SD"));
                        }
                        game.give_energy(15);
                        // Step to the set window and the yell window BY NAME: the five blind passes
                        // and the three bare ones this replaces were correct only while the phase
                        // sequence was frozen, and a drifted walk would leave the expected
                        // SelectAutoAbility simply absent.
                        game.advance_to_phase(rabuka_engine::game_state::Phase::LiveCardSetFirstAttacker);
                        game.set_live_card(daisuki);
                        // The yell happens as the live is performed, so step to the second
                        // attacker's window rather than the first: the first attacker's phase is
                        // reached before the yell prompt exists.
                        game.advance_to_phase(rabuka_engine::game_state::Phase::SecondAttackerPerformance);

                        assert!(game.has_pending_choice(), "SelectAutoAbility");
                        game.select_option(0);

                        while game.has_pending_choice() {
                            let c = game.get_pending_choice();
                            match c {
                                rabuka_engine::ability::types::Choice::SelectAutoAbility { .. } => {
                                    game.select_option(0)
                                }
                                rabuka_engine::ability::types::Choice::SelectCard { count, .. } => {
                                    game.select_indices(&(0..*count).collect::<Vec<_>>());
                                }
                                _ => game.select_indices(&[]),
                            }
                        }
                        assert!(!game.state.re_yell_revealed_cards.is_empty(), "re-yell");
                    }

