                        let himeno = g.id("PL!HS-bp2-009-R");
                        let mirakura_high = g.id("PL!HS-bp2-006-R");
                        g.state.player1.stage.stage[1] = mirakura_high;
                        g.state.player1.hand.cards.push(himeno);
