                    // P2 never performs and the scenario is a walkover, not a tie.
                    game.pass();
                    game.set_live_card(p2_live);
                    advance_to_live_victory(&mut game);
                    game.drain_choices_strict(&["SelectCard", "SelectAutoAbility"], &[0]);
