                    g.state.push_movement_event(koko, "stage", "stage", Some(koko), "p1", true);
                    trigger_auto(&mut g, koko);
                    assert_eq!(g.state.mods.get_heart_modifier(koko, HeartColor::Heart06), 1, "self effect should trigger");
